window.EXAM_KIT = {"title": "AI-103 Exam Kit", "passScore": 700, "exams": [{"id": "01-agent-vocabulary", "level": 1, "rank": "Easy", "title": "Agent and tool vocabulary", "minutes": 35, "cheat": "Cheat sheet 2.2 — agents, tools, and MCP", "blurb": "Short recall on tools, schemas, and how an agent loop uses an observation.", "focus": ["A tool performs an action. A resource is data the agent can read.", "An MCP tool is described with a schema so the model can build valid arguments.", "ReAct repeats thought, action, and observation until the goal is met or the options run out.", "A supervisor delegates work and decides what to do when a sub-agent fails."], "pool": 240, "questions": [{"id": "527528", "stem": "What is an “MCP gateway”?", "options": ["A hardware router", "A centralized service that proxies requests from multiple hosts to multiple MCP servers, handling authentication, rate-limiting, and routing", "A mobile app", "A database"], "answer": 1, "explanation": "An enterprise gateway adds a management layer, enforcing policies and providing a single point of control for all MCP interactions.", "topic": "Agents and tools", "source": 22}, {"id": "527543", "stem": "What is a “tool signature”?", "options": ["A handwritten note", "The combination of the tool’s name, parameter types, and return type, forming a contract for invocation", "The tool’s log file", "A cryptographic signature of the tool’s binary"], "answer": 1, "explanation": "The signature specifies what the tool expects and what it returns. The model uses this to construct valid calls; the runtime uses it for validation.", "topic": "Agents and tools", "source": 22}, {"id": "527448", "stem": "What is an “agentic loop”?", "options": ["A single prompt-response turn", "A repetitive cycle where the agent receives an input, reasons, possibly calls tools, observes results, and decides whether to continue or produce a final answer", "A loop in the Python code that retries API calls", "A feedback form for users"], "answer": 1, "explanation": "The agentic loop is the core execution cycle: the model processes the current state, optionally requests tool invocations, receives outcomes, and updates its state. It repeats until a termination condition (goal achieved, max iterations, or user stop) is met. This loop is what makes the system “agentic.”", "topic": "Agents and tools", "source": 21}, {"id": "527441", "stem": "What is a “tool use policy”?", "options": ["A natural language instruction in the system prompt telling the agent to be helpful", "A set of rules that govern which tools can be called under which circumstances, often enforced programmatically", "A document explaining how to install tools", "The schema of a single tool"], "answer": 1, "explanation": "Policies go beyond schema definitions; they may include rate limits, allowed times of day, user permissions, or conditional logic (e.g., “only use the payment tool if the user has confirmed”). These are enforced by the orchestration layer to ensure safe and compliant operation.", "topic": "Agents and tools", "source": 21}, {"id": "527577", "stem": "What is an “MCP transport bridge”?", "options": ["A physical bridge", "A component that translates between different MCP transports (e.g., allowing a stdio server to be accessed over SSE)", "A network cable", "A type of language model"], "answer": 1, "explanation": "Bridges enable flexibility: a local-only server can be exposed to remote hosts by converting its transport, expanding deployment options.", "topic": "Agents and tools", "source": 23}, {"id": "527558", "stem": "What is a “fallback tool” strategy?", "options": ["Using the same tool repeatedly", "Defining an alternative tool that the agent can try if the primary tool fails or returns empty results", "Removing all tools", "Forcing the user to choose the tool"], "answer": 1, "explanation": "Fallbacks increase resilience. For example, if a weather API fails, the agent can automatically try another weather service, improving task completion rates.", "topic": "Agents and tools", "source": 23}, {"id": "527427", "stem": "What is a “hallucinated tool call”?", "options": ["A tool call that returns fabricated data", "The model generating a call to a tool that has not been provided or does not exist", "A user request that references a non-existent tool", "A tool that produces random outputs"], "answer": 1, "explanation": "If the model invokes a function name that is not in the available tool list, the call is invalid. This can happen if the model confuses similar names or imagines capabilities. The runtime should reject such calls and inform the model of the error, allowing self-correction.", "topic": "Agents and tools", "source": 20}, {"id": "527454", "stem": "What is “dynamic tool selection”?", "options": ["Manually coding which tool to use for each request", "The agent choosing the appropriate tool at runtime based on the current context and user intent, rather than using a fixed set", "Selecting tools alphabetically", "Updating tool schemas without restarting"], "answer": 1, "explanation": "The agent evaluates the situation and picks the most suitable tool from a potentially large catalog. This can be achieved via the model’s own reasoning, or by using a retrieval-augmented tool selection that fetches relevant tool descriptions on the fly, making the system adaptable to varied requests.", "topic": "Agents and tools", "source": 21}, {"id": "527490", "stem": "What is “tool execution sandboxing”?", "options": ["Playing in a physical sandbox", "Running tool code in a restricted environment that limits access to the network, file system, and system resources", "Giving tools administrator privileges", "Storing tools in a cloud bucket"], "answer": 1, "explanation": "Sandboxing isolates tool execution from the main system. For example, a code execution tool runs in a container with read-only filesystems, no network outbound, and memory limits. This prevents malicious or buggy tool code from harming the host or exfiltrating data.", "topic": "Agents and tools", "source": 21}, {"id": "527570", "stem": "What is a “tool use policy” regarding PII?", "options": ["Encouraging the model to share PII", "A rule that prohibits sending personally identifiable information to external tools unless explicitly allowed and encrypted", "Storing PII in the prompt", "Ignoring privacy regulations"], "answer": 1, "explanation": "Data governance policies protect user privacy. The orchestration layer should scan tool arguments and block or redact PII before it leaves the secure boundary.", "topic": "Agents and tools", "source": 23}, {"id": "527563", "stem": "What is the main purpose of “agent tracing”?", "options": ["To draw pictures", "To record every step, tool call, reasoning trace, and timing for debugging, performance analysis, and compliance", "To hide the agent’s actions", "To compress the model"], "answer": 1, "explanation": "Tracing provides an execution log that developers and auditors can review to understand what the agent did and why, essential for improvement and trust.", "topic": "Agents and tools", "source": 23}, {"id": "527541", "stem": "What is a “tool use context limit” strategy?", "options": ["Removing all tools from the prompt", "Dynamically including only the most relevant tool schemas in the context based on the current task, using retrieval", "Printing all schemas on paper", "Sending tool schemas as images"], "answer": 1, "explanation": "When hundreds of tools exist, dynamic tool retrieval (similar to RAG) fetches only the schemas likely needed, saving tokens and reducing confusion.", "topic": "Agents and tools", "source": 22}, {"id": "527574", "stem": "What is the function of an “agent scaffold”?", "options": ["Physical support for the server", "A pre-built code framework that provides the core loop, tool integration, and memory management, letting developers focus on business logic", "A type of database", "A user authentication method"], "answer": 1, "explanation": "Scaffolds like LangChain, CrewAI, or custom runtimes accelerate development by providing battle-tested abstractions for the agentic loop and tool handling.", "topic": "Agents and tools", "source": 23}, {"id": "527518", "stem": "What is the purpose of “tool-use fine-tuning”?", "options": ["To teach the model to ignore all tools", "To train a model on examples of when and how to use tools, improving its ability to output correct structured calls", "To make tools run faster", "To convert tools into plain text"], "answer": 1, "explanation": "Fine-tuning on tool-use datasets teaches the model the syntax and decision boundaries, reducing errors in real-world agent deployments.", "topic": "Agents and tools", "source": 22}, {"id": "527609", "stem": "What is “tool selection via semantic search”?", "options": ["Searching for tools using regular expressions", "Encoding the user’s intent into an embedding and retrieving tools with similar description embeddings, enabling dynamic selection from a large catalog", "Alphabetically sorting tools", "Randomly picking a tool"], "answer": 1, "explanation": "This approach treats tool descriptions as documents for retrieval, solving the context-overflow problem when hundreds of tools exist. It selects only relevant tools.", "topic": "Agents and tools", "source": 23}, {"id": "527549", "stem": "What is “context pollution” in agentic workflows?", "options": ["Clean, organized history", "The accumulation of irrelevant or misleading tool outputs and thoughts that degrade the model’s decision-making", "A virus in the system", "A user typing too fast"], "answer": 1, "explanation": "Low-quality or excessive data in the context can confuse the model. Pruning, summarization, and careful tool output design prevent pollution.", "topic": "Agents and tools", "source": 22}, {"id": "527593", "stem": "What is “tool output truncation with a summary”?", "options": ["Deleting the tool output entirely", "Shortening a long tool result and appending a brief AI-generated summary of the truncated part, keeping context manageable", "Making the output longer", "Converting the output to base64"], "answer": 1, "explanation": "This balances completeness and context limits. The model sees the key information plus a note about what was omitted, preventing blind spots.", "topic": "Agents and tools", "source": 23}, {"id": "527605", "stem": "What is a “tool execution sandbox” typically used for?", "options": ["To make tools run slower", "To run untrusted code or potentially risky operations in an isolated environment, protecting the host system", "To improve internet speed", "To store user files"], "answer": 1, "explanation": "Sandboxing contains the impact of bugs or malicious code, preventing damage to the broader infrastructure. It’s a critical security measure.", "topic": "Agents and tools", "source": 23}, {"id": "527462", "stem": "What is a “termination condition” in an agentic loop?", "options": ["The condition that triggers the agent to stop iterating, such as reaching a final answer, exceeding a step limit, or encountering an unrecoverable error", "The initial user prompt", "The tool that finishes the fastest", "A signal from the operating system"], "answer": 0, "explanation": "Without a termination condition, an agent could loop indefinitely. Common conditions include the model emitting a special stop token or a final answer format, a maximum number of iterations, a human abort, or a policy-based stop. The loop must be bounded for safety and cost.", "topic": "Agents and tools", "source": 21}, {"id": "527560", "stem": "What is the role of “state machines” in agentic workflows?", "options": ["They replace language models", "They define explicit state transitions (e.g., waiting, planning, executing, done), providing deterministic control over the agent’s loop", "They generate images", "They store embeddings"], "answer": 1, "explanation": "State machines complement LLM-driven logic by enforcing a high-level flow, ensuring the agent doesn’t skip critical phases like validation or approval.", "topic": "Agents and tools", "source": 23}, {"id": "527568", "stem": "Which of the following is an anti-pattern in agent design?", "options": ["Breaking a task into small, testable steps", "Giving the agent a single, massive tool that does everything, reducing clarity and increasing failure surface", "Using tool descriptions with examples", "Adding guardrails for high-risk actions"], "answer": 1, "explanation": "Monolithic tools are hard to describe, error-prone, and make it difficult for the model to choose the right sub-function. Modular, single-purpose tools are preferred.", "topic": "Agents and tools", "source": 23}, {"id": "527409", "stem": "Which of the following is an example of tool chaining?", "options": ["An agent calling the same search tool five times in a loop", "An agent first translating a query, then passing the translated text to a search tool, and finally feeding the search results to a summarizer", "A user manually copying and pasting data between applications", "A single prompt that includes all necessary information without any external calls"], "answer": 1, "explanation": "Tool chaining involves composing multiple tool calls where the output of one becomes the input of the next. This creates a pipeline that automates a multi-step task. In this example, translation ? search ? summarization forms a clear chain.", "topic": "Agents and tools", "source": 20}, {"id": "527450", "stem": "Which of the following is an example of an agent’s “observation”?", "options": ["The user’s initial request", "The raw JSON returned by a tool after execution, before any model reasoning", "The model’s internal weights", "The system prompt"], "answer": 1, "explanation": "In the ReAct paradigm, the Observation is the result of an Action. It is the data (or error) received from the tool or environment, which the model then incorporates into the next Thought. This feedback is essential for the loop to function.", "topic": "Agents and tools", "source": 21}, {"id": "527419", "stem": "What is the role of a “function schema” in tool-calling APIs?", "options": ["It provides an example prompt for the user", "It defines the function’s signature, including the name, description, and parameters, so the model can output a structured call", "It encrypts the function’s source code", "It serves as a tutorial for human developers"], "answer": 1, "explanation": "When providing tools to a model, each tool includes a JSON schema that describes the function name, a natural language description, and the parameters object. The model uses this metadata to decide when to call the function and how to format arguments correctly.", "topic": "Agents and tools", "source": 20}, {"id": "527390", "stem": "What is the difference between “instruction tuning” and “RLHF”?", "options": ["Instruction tuning trains on (instruction, output) pairs, while RLHF refines the model using human preference comparisons", "They are exactly the same", "RLHF doesn’t require any training", "Instruction tuning uses reinforcement learning"], "answer": 0, "explanation": "Instruction tuning is supervised fine-tuning on instruction-following examples; RLHF is a subsequent step using reward models from human preferences to align behavior.", "topic": "Agents and tools", "source": 20}, {"id": "527475", "stem": "What is “tool blending” in the context of agentic workflows?", "options": ["Mixing different programming languages in one tool", "The ability of an agent to combine multiple tools in a single step where the output of one is seamlessly passed as input to another within the same reasoning block", "Changing the color scheme of a tool UI", "Merging two tools into one schema"], "answer": 1, "explanation": "Some agent frameworks allow the model to specify a sequence of tool calls that should be executed together, with dependencies, without interleaving user messages. This reduces round trips and latency, effectively “blending” operations into a cohesive unit.", "topic": "Agents and tools", "source": 21}, {"id": "527459", "stem": "Which of the following is NOT a typical component of an MCP server?", "options": ["A list of tool definitions with input schemas", "A list of resource templates", "A built-in large language model for generating responses", "A transport layer for communication"], "answer": 2, "explanation": "MCP servers expose tools and resources; they do not contain an LLM. The AI model resides in the host. The server simply wraps existing capabilities and communicates via the protocol. It is a bridge, not an AI provider.", "topic": "Agents and tools", "source": 21}, {"id": "527432", "stem": "Which of the following is a best practice for tool descriptions?", "options": ["Write them in a language the user prefers, ignoring the model", "Keep them concise yet precise, clearly stating what the tool does, what parameters are needed, and any side effects", "Omit all details to keep the prompt short", "Include the full source code of the tool"], "answer": 1, "explanation": "The model relies on the description to decide when and how to use the tool. A clear, well-structured description—including parameter meanings and expected behavior—leads to more accurate tool selection and argument generation. Overly long or vague descriptions hurt performance.", "topic": "Agents and tools", "source": 20}, {"id": "527531", "stem": "What is the role of “error handling middleware” in an agent runtime?", "options": ["To crash the agent safely", "To intercept tool errors, log them, possibly retry, or convert them into model-friendly messages for self-correction", "To compile the agent’s code", "To design the user interface"], "answer": 1, "explanation": "Middleware abstracts error processing, allowing the agent to gracefully recover from transient failures without cluttering the core reasoning loop.", "topic": "Agents and tools", "source": 22}, {"id": "527536", "stem": "What is the purpose of the `capabilities` field in MCP initialization?", "options": ["To advertise the server’s hardware specs", "To declare whether the server supports tools, resources, prompts, or subscriptions, allowing the host to adapt", "To list all user accounts", "To set the background color"], "answer": 1, "explanation": "During the handshake, the server tells the host what features it offers. The host can then decide which capabilities to use, ensuring compatibility.", "topic": "Agents and tools", "source": 22}, {"id": "527485", "stem": "What is a potential issue when an agent caches tool results indefinitely?", "options": ["Faster response times", "Using stale data that no longer reflects the current state of the external system", "Reduced token usage", "Better model performance"], "answer": 1, "explanation": "Caching improves speed but must include a freshness policy. If the agent caches a stock price for too long, it may base decisions on outdated information. Time-to-live (TTL) or cache invalidation strategies are needed to maintain accuracy.", "topic": "Agents and tools", "source": 21}, {"id": "527458", "stem": "What is the main benefit of an “agent harness” or “agent runtime”?", "options": ["It provides a standardized environment that manages the agent loop, tool execution, memory, logging, and error handling, so developers don’t have to build these from scratch", "It compresses the model into a smaller file", "It exclusively deals with UI rendering", "It replaces the need for a language model"], "answer": 0, "explanation": "An agent runtime (like LangChain agents, AutoGen, or custom frameworks) handles the repetitive infrastructure: calling the model, parsing responses, executing tools, injecting observations, managing conversation history, and enforcing termination conditions. This speeds up development and improves reliability.", "topic": "Agents and tools", "source": 21}, {"id": "527468", "stem": "What is a “tool-use loop” that includes an explicit verification step?", "options": ["Act, then immediately stop", "The agent calls a tool, examines the result, then calls a verification tool (or uses self-critique) to check the correctness before proceeding", "A loop with no actions", "A loop that only uses the user’s input"], "answer": 1, "explanation": "Verification improves reliability. After getting a tool output, the agent can cross-check it (e.g., verify a calculation with a second tool, or confirm that a summary matches the source). This additional step catches errors early and is part of robust agentic patterns.", "topic": "Agents and tools", "source": 21}, {"id": "527481", "stem": "What is the primary function of a “plan validator” in a plan-and-execute agent?", "options": ["To execute the plan", "To check the generated plan for logical consistency, completeness, and feasibility before execution begins", "To compress the plan into a shorter string", "To translate the plan into another language"], "answer": 1, "explanation": "Before committing to execution, a validator can detect missing steps, contradictory actions, or steps that would violate constraints. It can reject the plan and request regeneration, increasing the overall success rate and preventing wasted tool calls.", "topic": "Agents and tools", "source": 21}, {"id": "527478", "stem": "What is the “starter prompt” or “system prompt” typically used for in an agent?", "options": ["It is the first user message", "It provides the agent with its role, behavioral guidelines, available tools description, and output format instructions", "It is a hardware initialization command", "It logs the agent into the database"], "answer": 1, "explanation": "The system prompt sets the ground rules. It tells the model it is an agent, describes its capabilities, instructs it on how to use tools (e.g., output format for function calls), and often includes safety guidelines. It’s the foundation of the agent’s behavior.", "topic": "Agents and tools", "source": 21}, {"id": "527445", "stem": "What is a common challenge when integrating many tools (hundreds) with an agent?", "options": ["The model becomes more empathetic", "The prompt becomes too long because every tool’s schema must be included, and the model may confuse similar tools", "The tools automatically become faster", "There is no challenge; more tools always improve accuracy"], "answer": 1, "explanation": "Each tool adds its description and schema to the context, consuming tokens. With too many tools, the context can overflow, and the model may select the wrong tool or hallucinate. Solutions include tool retrieval (RAG for tools), hierarchical namespaces, or dynamic tool selection.", "topic": "Agents and tools", "source": 21}, {"id": "527439", "stem": "Which of the following is a sign that an agent needs better context compression?", "options": ["The agent always calls the correct tool on the first attempt", "Performance degrades and relevant early information is forgotten as the conversation exceeds the context limit", "The agent’s responses are too short", "The tool descriptions are too detailed"], "answer": 1, "explanation": "When the context window is filled, the model may lose older but critical information. Context compression techniques (summarization, embedding-based memory retrieval) condense the history, preserving key facts while discarding noise. This maintains performance over long sessions.", "topic": "Agents and tools", "source": 21}, {"id": "527497", "stem": "Which of the following is a sign that an agent’s tool descriptions are ineffective?", "options": ["The agent consistently picks the correct tool on the first attempt", "The agent frequently calls the wrong tool or hallucinates parameters", "Tool calls execute faster than expected", "The agent never needs to use tools"], "answer": 1, "explanation": "Poor descriptions confuse the model, leading to incorrect tool selection and malformed arguments. Clear, concise schemas drastically improve accuracy.", "topic": "Agents and tools", "source": 22}, {"id": "527422", "stem": "What is the primary function of a “context window” in a language model-based agent?", "options": ["It determines how many tools the agent can access", "It limits the amount of text (tokens) the model can consider at once, including conversation history and tool outputs", "It controls the volume of audio output", "It defines the geographic region of the server"], "answer": 1, "explanation": "The context window is the maximum number of tokens the model can process in a single inference. It must accommodate the system prompt, user messages, tool calls, and observations. Managing this limit is essential for long sessions to avoid truncation of important information.", "topic": "Agents and tools", "source": 20}, {"id": "527538", "stem": "Which of the following is an example of an “imperative” vs “declarative” plan in agents?", "options": ["“Make me a coffee” is declarative; a step-by-step sequence is imperative", "Both are the same", "Declarative plans use only Python code", "Imperative plans never use tools"], "answer": 0, "explanation": "A declarative goal states the desired outcome without specifying steps. An imperative plan lists exact actions. Many agents combine both: a high-level declarative objective and an imperative execution plan.", "topic": "Agents and tools", "source": 22}]}, {"id": "02-search-vocabulary", "level": 2, "rank": "Easy", "title": "Search and grounding vocabulary", "minutes": 35, "cheat": "Cheat sheet 2.1 and 5.1 — RAG and retrieval", "blurb": "Short recall on indexes, vector search, OCR, and how grounding finds source text.", "focus": ["Use keyword search for exact terms, vector search for meaning, and hybrid search for both.", "Integrated vectorization needs a vector profile and a vectorizer tied to an embedding model.", "Indexers pull from a source on a schedule. Your own code pushes data when updates must be immediate.", "OCR turns document images into text that a retrieval pipeline can index."], "pool": 300, "questions": [{"id": "527636", "stem": "What is “agent-initiated handoff”?", "options": ["The user switching apps", "The agent deciding that another specialized agent should handle the request and transferring the conversation and context", "The server disconnecting", "The model closing the chat"], "answer": 1, "explanation": "The agent evaluates its own limitations and seamlessly escalates or transfers to a more capable agent, improving user experience without user intervention.", "topic": "Search and grounding", "source": 24}, {"id": "527622", "stem": "What is “tool call time-to-live” (TTL)?", "options": ["The time it takes to code the tool", "A setting that defines how long a cached tool result is valid before re-executing the call", "The tool’s execution speed", "The lifespan of the server"], "answer": 1, "explanation": "TTL prevents stale data. After the TTL expires, the next call forces a fresh execution, ensuring the agent works with up-to-date information.", "topic": "Search and grounding", "source": 24}, {"id": "527632", "stem": "What is an “MCP capability negotiation”?", "options": ["A business negotiation", "During initialization, host and server agree on which features (tools, resources, subscriptions, etc.) to use, ensuring compatibility", "A price discussion", "A debate about which LLM to use"], "answer": 1, "explanation": "Both sides declare their capabilities. This prevents the host from requesting unsupported features and allows graceful fallbacks.", "topic": "Search and grounding", "source": 24}, {"id": "527657", "stem": "What is a “vector store” in a RAG pipeline?", "options": ["A database that stores only raw text files", "A specialized database or index that stores vector embeddings and supports similarity search", "A cloud storage service for images", "A library for tokenizing prompts"], "answer": 1, "explanation": "A vector store holds embedding vectors and enables operations like cosine similarity or Euclidean distance searches, typically using ANN algorithms. It is a critical component for semantic retrieval in RAG.", "topic": "Search and grounding", "source": 24}, {"id": "527691", "stem": "What is “Azure AI Search document cracking”?", "options": ["The process of breaking encryption on documents", "The ability of indexers to read and extract content from diverse file formats like PDF, DOCX, JSON, and images", "A security vulnerability", "A method of deleting documents"], "answer": 1, "explanation": "Document cracking is the built-in functionality of Azure AI Search indexers to parse and extract text and metadata from various data sources, making the content available for indexing and enrichment.", "topic": "Search and grounding", "source": 25}, {"id": "527857", "stem": "What is the “Matryoshka embedding” technique?", "options": ["Embedding only numbers", "Training embeddings such that the first k dimensions of a larger vector can be used as a lower-dimensional representation without a significant loss in quality", "Nesting documents inside each other", "Using only one dimension"], "answer": 1, "explanation": "Matryoshka representation learning allows a single model to produce embeddings that can be truncated to a range of shorter lengths (e.g., 256, 512, 1024) while preserving semantics. This provides flexibility for storage/performance trade-offs.", "topic": "Search and grounding", "source": 28}, {"id": "527723", "stem": "What is a “knowledge store” in Azure AI Search?", "options": ["A temporary cache for queries", "A persistent store of enriched documents (projections into Azure Storage tables/blobs/files) for downstream analytics and data exploration", "A synonym library", "A search index backup"], "answer": 1, "explanation": "Knowledge stores persist the outputs of AI enrichment pipelines, allowing data scientists or other applications to use the enriched data without hitting the search index. It can also serve as a source for further RAG processing.", "topic": "Search and grounding", "source": 25}, {"id": "527861", "stem": "What is a “grounding score” usually derived from?", "options": ["The number of citations only", "An NLI model or LLM evaluator that outputs a probability that the answer is entailed by the provided context", "The length of the answer", "The user’s rating"], "answer": 1, "explanation": "A grounding score is a numerical metric (0-1) indicating how well the answer is supported by the context. It’s often generated by a fine-tuned model or via a prompted LLM that checks entailment.", "topic": "Search and grounding", "source": 28}, {"id": "527626", "stem": "What is the purpose of “tool input sanitization”?", "options": ["To delete tool inputs", "To clean and validate inputs to prevent injection attacks, escape special characters, and ensure they match expected types before execution", "To make inputs longer", "To change the user’s intent"], "answer": 1, "explanation": "Sanitization protects against malicious inputs that could exploit vulnerabilities in the tool’s implementation, such as SQL injection or script injection.", "topic": "Search and grounding", "source": 24}, {"id": "527720", "stem": "What is “Azure AI Search index aliases” useful for?", "options": ["Renaming user queries", "Creating a stable logical name that points to different physical indexes, enabling zero-downtime index swapping after rebuilds", "Duplicating API keys", "Encrypting data"], "answer": 1, "explanation": "Aliases allow applications to reference a constant index name. After re-indexing (e.g., due to embedding model change), the alias can be switched to the new index without changing client code.", "topic": "Search and grounding", "source": 25}, {"id": "527663", "stem": "What is the role of a skillset in Azure AI Search?", "options": ["It defines the network firewall rules", "It orchestrates a sequence of AI enrichments such as OCR, language detection, and embedding generation during indexing", "It stores user queries", "It manages API authentication"], "answer": 1, "explanation": "A skillset is a collection of pre-built or custom skills that process documents in an enrichment pipeline. For RAG, a common skill is the “AzureOpenAIEmbedding” skill that generates vector embeddings for chunks.", "topic": "Search and grounding", "source": 24}, {"id": "527820", "stem": "What is a “vector search profile” in Azure AI Search?", "options": ["A configuration that combines the algorithm, vectorizer, and compression settings for a set of vector fields", "A user profile", "A synonym map", "An API key"], "answer": 0, "explanation": "A vector search profile bundles the ANN algorithm (e.g., HNSW) and the vectorizer definition. Each vector field in the index references a profile, dictating how its vectors are indexed and queried.", "topic": "Search and grounding", "source": 27}, {"id": "527649", "stem": "What is the role of a reranker in a retrieval pipeline?", "options": ["To generate embeddings for the query", "To reorder initially retrieved candidates using a more precise cross-encoder model", "To index documents into the vector store", "To apply OCR on scanned documents"], "answer": 1, "explanation": "A reranker, often a cross-encoder, takes the query and each candidate document and outputs a relevance score. It re-sorts a small set of top candidates from a fast first-stage retriever (e.g., vector search) for higher accuracy, but is computationally more expensive.", "topic": "Search and grounding", "source": 24}, {"id": "527619", "stem": "What is a “context overflow” error in an agent runtime?", "options": ["The model became too intelligent", "The combined tokens of the conversation and tool outputs exceeded the model’s maximum context window, causing a fatal error", "The memory worked perfectly", "The tool executed too fast"], "answer": 1, "explanation": "Exceeding the context limit triggers an error. Robust systems preempt this with compression, summarization, or early truncation to stay within bounds.", "topic": "Search and grounding", "source": 24}, {"id": "527709", "stem": "What is “hallucination” in the context of a RAG system?", "options": ["The model generates text that is not supported by the retrieved evidence, producing plausible but incorrect information", "The vector search returns too many results", "The embedding model fails to load", "The user asks an unclear question"], "answer": 0, "explanation": "Even with retrieval, a model may ignore the context or misinterpret it, generating fabrications. Proper grounding techniques, prompt instructions, and post-generation verification help mitigate this.", "topic": "Search and grounding", "source": 25}, {"id": "527849", "stem": "What is the primary purpose of “term boosting” in a query?", "options": ["To reduce recall", "To increase the importance of certain query terms in the scoring function, making documents that contain those terms rank higher", "To delete terms", "To ignore user input"], "answer": 1, "explanation": "In Azure AI Search, you can apply term boosting (e.g., “term^2”) in the simple query syntax to influence the BM25 score, which can be useful when you know certain keywords are more important for relevance.", "topic": "Search and grounding", "source": 27}, {"id": "527903", "stem": "What is the purpose of a mel spectrogram in audio processing?", "options": ["To visualize video frames", "To represent audio frequencies on a perceptually motivated scale", "To compress image files", "To detect objects in a soundscape"], "answer": 1, "explanation": "The mel scale approximates human auditory perception; mel spectrograms are a common input representation for speech and audio models.", "topic": "Search and grounding", "source": 28}, {"id": "527616", "stem": "What is “step-by-step reasoning with tool use” commonly known as?", "options": ["Zero-shot generation", "ReAct or interleaved reasoning and acting", "Pure memory retrieval", "Passive listening"], "answer": 1, "explanation": "The ReAct paradigm formalizes this interleaving: the model thinks, acts, observes, and repeats, enabling complex, grounded problem solving.", "topic": "Search and grounding", "source": 24}, {"id": "527865", "stem": "What is a “token-aware chunk splitter” designed to prevent?", "options": ["Splitting words exactly at token boundaries", "Exceeding the embedding model’s token limit by counting tokens using the model’s tokenizer, not just characters, while splitting", "Generating too many chunks", "Using too little memory"], "answer": 1, "explanation": "A token-aware splitter uses the target model’s tokenizer to measure chunk length in tokens, ensuring it stays within the max input size. This avoids unintentional truncation that character or word counts might not catch.", "topic": "Search and grounding", "source": 28}, {"id": "527776", "stem": "What is the purpose of the “semantic cache” pattern in RAG?", "options": ["To store user passwords", "To cache the response to a query by using a similarity threshold on the query embedding, so that similar future queries return the cached answer directly without full retrieval-generation", "To delete old vectors", "To compress the index"], "answer": 1, "explanation": "A semantic cache computes the embedding of a new query and compares it to stored embeddings of past queries. If a match is found within a threshold, the cached response (with citations) is served, reducing latency and cost.", "topic": "Search and grounding", "source": 26}, {"id": "527783", "stem": "What is a “function calling” or “tool use” extension to RAG?", "options": ["The model only generates text", "The model can decide to call external APIs (e.g., a calculator, database query) based on the user request, and incorporate the result into its grounded response", "It deletes all tools", "It only uses vector search"], "answer": 1, "explanation": "Augmenting RAG with tool use allows the system to fetch structured data, perform computations, or trigger actions when retrieved text is insufficient. This creates a more capable agent that still grounds actions in external sources.", "topic": "Search and grounding", "source": 26}, {"id": "527851", "stem": "What is the purpose of “indexing schedule” in Azure AI Search?", "options": ["To disable indexing", "To define a recurring time window (e.g., every 5 minutes, daily at 2 AM) for running the indexer to keep the search index up to date", "To set the embedding dimension", "To create a firewall rule"], "answer": 1, "explanation": "Indexer schedules allow periodic automatic updates. For RAG, this ensures new or modified documents become searchable without manual intervention, with the frequency tailored to how often the source content changes.", "topic": "Search and grounding", "source": 27}, {"id": "527742", "stem": "What is a “text splitter” that respects markdown structure?", "options": ["A splitter that cuts text only at sentence boundaries using a list of punctuation", "A splitter that recognizes markdown headers (##, #) and splits sections, then recursively splits if needed, preserving document hierarchy", "A splitter that only uses spaces", "A splitter that converts markdown to PDF"], "answer": 1, "explanation": "Markdown-aware splitters use headers as strong boundary hints, then use other separators. This keeps sections together and maintains the logical structure of technical documentation, which aids retrieval.", "topic": "Search and grounding", "source": 26}, {"id": "527831", "stem": "What is a “text-embedding-3-small” style model characteristic?", "options": ["It is huge and slow", "It is a smaller, faster embedding model that still produces high-quality dense vectors, often using Matryoshka representation learning to allow flexible dimension reduction", "It cannot be used for retrieval", "It only works in English"], "answer": 1, "explanation": "Newer embedding models support Matryoshka embeddings, where you can truncate the vector to a smaller dimension without losing much quality. This allows trading off accuracy for speed and storage within a single model.", "topic": "Search and grounding", "source": 27}, {"id": "527753", "stem": "What is the main goal of the “Corrective RAG” (CRAG) approach?", "options": ["To correct grammar in the retrieved passages", "To evaluate the relevance of retrieved documents and, if needed, perform additional web searches to correct or supplement the context before generation", "To always retrieve from a local database", "To reduce the number of chunks to one"], "answer": 1, "explanation": "CRAG introduces a retrieval evaluator that grades the quality of the initial retrieval. If the retrieved passages are insufficient, it triggers an external search (e.g., web) to fetch better information, correcting the context supplied to the generator.", "topic": "Search and grounding", "source": 26}, {"id": "527713", "stem": "What is the purpose of a “guardrails” system in a RAG application?", "options": ["To accelerate vector search", "To block harmful content, detect jailbreak attempts, and ensure the final answer complies with safety and policy constraints", "To generate embeddings", "To compress the prompt"], "answer": 1, "explanation": "Guardrails add a safety layer that can filter prompts and responses, detect adversarial inputs, and enforce responsible AI policies, which is especially important in customer-facing RAG applications.", "topic": "Search and grounding", "source": 25}, {"id": "527740", "stem": "What is the main advantage of a “re-rank then generate” pattern?", "options": ["It eliminates the need for generation", "By reordering retrieved passages with a more accurate model before they are passed to the generator, the most relevant information is prioritized, improving answer quality", "It saves storage", "It uses only BM25"], "answer": 1, "explanation": "Ensuring the prompt begins with the most relevant chunks helps the LLM focus on the best evidence, potentially reducing the chance of being distracted by less useful text placed prominently.", "topic": "Search and grounding", "source": 26}, {"id": "527869", "stem": "What is a “recall-oriented” chunking strategy typically used for?", "options": ["When precision is the only goal", "When you want to maximize the chance of retrieving any relevant text, even at the expense of including some irrelevant noise, like in legal e-discovery", "When you want minimal results", "When chunk size is 1 token"], "answer": 1, "explanation": "For high-recall scenarios, you might use smaller chunks with high overlap and low threshold filtering to ensure nothing is missed. Precision is sacrificed, but the generator or a reranker can handle the noise.", "topic": "Search and grounding", "source": 28}, {"id": "527859", "stem": "What is the function of the “searchDocuments” API in Azure AI Search?", "options": ["To delete documents", "To execute search queries against an index, returning results based on text, vector, or hybrid queries", "To create an index", "To define a skillset"], "answer": 1, "explanation": "This is the core REST API endpoint for querying. It accepts query parameters including search text, vectors, filters, and semantic configuration, returning ranked documents.", "topic": "Search and grounding", "source": 28}, {"id": "527871", "stem": "What is the role of “passage retrieval” in a long-document context?", "options": ["To retrieve the entire document", "To extract the most relevant snippet (passage) from a larger chunk or document, which is then used as the final context for the generator", "To ignore the document", "To compress the image"], "answer": 1, "explanation": "Even when chunks are moderate, further passage extraction can refine context to the exact sentences that answer the query, reducing noise and improving the generator’s focus.", "topic": "Search and grounding", "source": 28}, {"id": "527895", "stem": "What is the main advantage of a multimodal AI model over a unimodal one?", "options": ["Faster training time", "Ability to process only text", "Simultaneous understanding of multiple data types", "Lower computational cost"], "answer": 2, "explanation": "Multimodal models integrate information from different modalities (text, image, audio) allowing richer understanding. Unimodal models are limited to a single modality.", "topic": "Search and grounding", "source": 28}, {"id": "527825", "stem": "What is a “fused hybrid search” in the context of a single request?", "options": ["A search that uses only one algorithm", "A single query that simultaneously performs keyword and vector search, then merges the results using RRF, returning a unified result set", "Two separate API calls", "A search that ignores vector results"], "answer": 1, "explanation": "Azure AI Search supports a single hybrid query that includes both a text search and a vector query. The service internally runs both, fuses the ranked results, and returns the merged list, simplifying client logic.", "topic": "Search and grounding", "source": 27}, {"id": "527844", "stem": "What is the role of a “document watermark” in the retrieval pipeline?", "options": ["To encrypt the document", "To track the last processed timestamp of a document, enabling efficient incremental ingestion by only processing changes since the watermark", "To split the document", "To add an image"], "answer": 1, "explanation": "A high-watermark (e.g., a datetime field) indicates which documents have been updated. The ingestion pipeline can query “since last watermark” to only process new or modified items, making index updates efficient.", "topic": "Search and grounding", "source": 27}, {"id": "527898", "stem": "Which of the following is a typical output of an object detection model?", "options": ["A single class label for the entire image", "Bounding boxes and class labels for each detected object", "A pixel-level mask for each object", "A text description of the scene"], "answer": 1, "explanation": "Object detection localizes objects with bounding boxes and assigns a class label to each. Instance segmentation would provide pixel masks.", "topic": "Search and grounding", "source": 28}, {"id": "527786", "stem": "What is the main advantage of using a “model-agnostic” RAG framework?", "options": ["It locks you into one embedding provider", "It allows swapping embedding models, vector stores, and LLMs with minimal code changes, making the system flexible and future-proof", "It only works on-premises", "It eliminates the need for retrieval"], "answer": 1, "explanation": "A modular design with abstraction layers enables teams to test different components (e.g., switching from Ada to a new embedding model) without rewriting the entire pipeline, which is crucial in the fast-evolving AI landscape.", "topic": "Search and grounding", "source": 26}, {"id": "527822", "stem": "What is the main purpose of the “enrichment cache” in Azure AI Search?", "options": ["To permanently store the final answer", "To store intermediate enriched document output to avoid re-processing when skills or documents change partially, reducing pipeline costs", "To cache user queries", "To delete documents"], "answer": 1, "explanation": "Enrichment caching stores the outputs of skills in a blob container. If only a single skill changes, the indexer can reuse cached results from upstream skills, saving computation and time during incremental updates.", "topic": "Search and grounding", "source": 27}, {"id": "527800", "stem": "What is the purpose of “synthetic data generation” for RAG evaluation?", "options": ["To replace real documents", "To create a large set of question-context-answer triples automatically from documents, enabling robust evaluation of retrieval and generation components", "To delete the index", "To reduce the number of queries"], "answer": 1, "explanation": "Using an LLM to generate hypothetical questions that each chunk can answer yields a labeled dataset. These synthetic pairs can then be used to compute recall@k and answer correctness for the RAG pipeline.", "topic": "Search and grounding", "source": 27}, {"id": "527814", "stem": "What is the purpose of “session context” in a conversational RAG system?", "options": ["To delete history", "To carry forward previously retrieved documents and user intents to provide coherent multi-turn answers without re-retrieving for every turn", "To reduce the number of turns", "To compress the chat"], "answer": 1, "explanation": "By maintaining a short-term memory of retrieved facts and the conversation state, the system can answer follow-up questions like “Tell me more about that” by using already-fetched context, improving efficiency and consistency.", "topic": "Search and grounding", "source": 27}, {"id": "527839", "stem": "What is the purpose of “multi-layer reasoning” in RAG prompted systems?", "options": ["To use only one sentence", "To break down the question into a step-by-step plan, retrieve information for each step, and synthesize a final answer, often using a tool-augmented language model", "To avoid retrieval entirely", "To always use BM25"], "answer": 1, "explanation": "Multi-layer reasoning involves planning, tool use (retrieval, calculator), and synthesis. It’s a core component of agentic RAG, capable of handling complex, multi-step problems by iteratively calling the retriever.", "topic": "Search and grounding", "source": 27}, {"id": "527696", "stem": "What is the “embedding drift” problem that might necessitate re-indexing?", "options": ["The embedding model changes or is fine-tuned, so new embeddings are no longer compatible with the old vector index", "The user’s language evolves", "Vectors move on disk", "The tokenizer runs out of memory"], "answer": 0, "explanation": "If the embedding model is updated (new checkpoint or fine-tuned on domain data), the vector space shifts. All documents must be re-embedded and re-indexed to maintain consistency between query and document embeddings.", "topic": "Search and grounding", "source": 25}]}, {"id": "03-vision-language", "level": 3, "rank": "Moderate", "title": "Vision, speech, and language concepts", "minutes": 45, "cheat": "Cheat sheet domains 3 and 4 — vision, text, and speech", "blurb": "Applied concepts for images, speech, translation, and multimodal data.", "focus": ["A multimodal example pairs two kinds of data, such as an image and its caption.", "Captions, alt text, and visual question answering are different outputs from the same picture.", "Live speech translation has to stay low-latency so the conversation does not stall.", "Face verification is judged with false acceptance and false rejection, and public use raises privacy duties."], "pool": 240, "questions": [{"id": "528054", "stem": "What is a “visual grounding” task?", "options": ["Classifying an image into a category", "Locating an object in an image based on a natural language description", "Converting an image to a sketch", "Generating an image from text"], "answer": 1, "explanation": "Visual grounding (or referring expression comprehension) links words to image regions, localizing “the red car next to the tree.”", "topic": "Vision and language", "source": 31}, {"id": "528123", "stem": "What is “text-to-speech with emotion”?", "options": ["Monotone speech generation", "Synthesizing speech with a specified emotional tone, like happy or sad", "Translating emotional text", "Recognizing emotion from speech"], "answer": 1, "explanation": "Emotional TTS controls prosody and voice quality to convey feelings, making interactions more natural and engaging.", "topic": "Vision and language", "source": 32}, {"id": "528066", "stem": "What is a “mel scale” designed to mimic?", "options": ["The frequency range of a dog's hearing", "The non-linear human perception of pitch", "The speed of sound in water", "The brightness of an image"], "answer": 1, "explanation": "The mel scale compresses higher frequencies, reflecting the fact that humans are less sensitive to differences at high pitches.", "topic": "Vision and language", "source": 31}, {"id": "527987", "stem": "What is a “spectrogram” in audio analysis?", "options": ["A visual representation of the spectrum of frequencies over time", "A list of detected objects", "A 3D model of a room", "A type of microphone array"], "answer": 0, "explanation": "A spectrogram plots frequency (y-axis) against time (x-axis) with amplitude represented by color, commonly used as input for audio models.", "topic": "Vision and language", "source": 30}, {"id": "528097", "stem": "What is “prosody transfer” in speech synthesis?", "options": ["Changing the speaker's identity completely", "Applying the intonation and rhythm pattern from one utterance to another", "Converting speech to text faster", "Adding silence between words"], "answer": 1, "explanation": "Prosody transfer allows a synthetic voice to adopt the speaking style of a reference audio, making it more expressive.", "topic": "Vision and language", "source": 32}, {"id": "528046", "stem": "What is the function of a “pooling layer” in a CNN?", "options": ["To increase the number of channels", "To progressively reduce the spatial dimensions and summarize features", "To add non-linearity", "To flatten the feature map"], "answer": 1, "explanation": "Pooling (max or average) reduces resolution, making the representation more compact and invariant to small translations.", "topic": "Vision and language", "source": 31}, {"id": "528126", "stem": "What is a “diffusion model” for audio generation?", "options": ["A model that compresses audio", "A generative model that gradually denoises random noise into structured audio based on a prompt", "A model that classifies audio events", "A model that transcribes speech"], "answer": 1, "explanation": "Diffusion models for audio synthesize high-fidelity music or speech by reversing a noise process, similar to image diffusion.", "topic": "Vision and language", "source": 32}, {"id": "528137", "stem": "What is a “multi-talker ASR” system designed to handle?", "options": ["A single speaker reading a script", "Overlapping speech from multiple people (e.g., a meeting with cross-talk)", "Music playing without lyrics", "Silence"], "answer": 1, "explanation": "Multi-talker or overlapping speech recognition separates and transcribes simultaneous speakers, a very challenging area.", "topic": "Vision and language", "source": 32}, {"id": "528139", "stem": "What is the function of a “phoneme” in speech technology?", "options": ["A unit of text formatting", "The smallest perceptually distinct unit of sound in a language", "A type of microphone", "A whole word"], "answer": 1, "explanation": "Phonemes are the building blocks of pronunciation; “cat” has three phonemes: /k/, /æ/, /t/.", "topic": "Vision and language", "source": 32}, {"id": "528042", "stem": "What is the output of an “image super-resolution” model?", "options": ["A lower-resolution version of the input", "A higher-resolution image with finer details inferred", "A text description of the image", "A set of bounding boxes"], "answer": 1, "explanation": "Super-resolution upscales an image, using AI to hallucinate plausible high-frequency details missing from the low-res input.", "topic": "Vision and language", "source": 31}, {"id": "528017", "stem": "What is a “heatmap” in the context of computer vision?", "options": ["A graphical representation of temperature in the scene", "A 2D array highlighting the spatial importance or probability of a detection", "A table of classification accuracy", "A compressed image format"], "answer": 1, "explanation": "Heatmaps are often used to show the likelihood of an object’s presence at each pixel, or attention weights.", "topic": "Vision and language", "source": 30}, {"id": "528021", "stem": "Which of the following is a generative AI task for audio?", "options": ["Classifying sound events", "Creating a new music clip from a text prompt", "Transcribing speech to text", "Separating vocals from accompaniment"], "answer": 1, "explanation": "Text-to-audio or text-to-music generation produces novel audio content based on descriptive prompts, a generative task.", "topic": "Vision and language", "source": 30}, {"id": "528008", "stem": "What is the main output of a speaker recognition system?", "options": ["A text transcript of speech", "The identity of the speaker or a similarity score against enrolled speakers", "The translation of the spoken content", "A summary of the conversation"], "answer": 1, "explanation": "Speaker recognition verifies or identifies a person based on voice characteristics, not the words spoken.", "topic": "Vision and language", "source": 30}, {"id": "528133", "stem": "What is a “data augmentation” technique specific to audio?", "options": ["Rotating the image", "Adding background noise, changing speed, or applying pitch shift", "Swapping words in a sentence", "Changing image contrast"], "answer": 1, "explanation": "Augmenting audio with variations in tempo, pitch, and additive noise improves model robustness for ASR and audio classification.", "topic": "Vision and language", "source": 32}, {"id": "527979", "stem": "What is the primary use of “optical flow” in video analysis?", "options": ["Measuring camera color balance", "Estimating the motion of objects between consecutive frames", "Recognizing text in video", "Compressing audio streams"], "answer": 1, "explanation": "Optical flow computes the apparent motion of brightness patterns, useful for action recognition, tracking, and video compression.", "topic": "Vision and language", "source": 30}, {"id": "528112", "stem": "What is the purpose of “phoneme alignment” in a TTS dataset?", "options": ["To label each audio frame with the corresponding phoneme", "To separate voice from background music", "To translate phonemes to text", "To increase the volume of the audio"], "answer": 0, "explanation": "Accurate time-aligned phoneme labels are essential for training duration models and improving TTS naturalness.", "topic": "Vision and language", "source": 32}, {"id": "527947", "stem": "What is the main function of a “vocoder” in speech synthesis?", "options": ["Convert text to phonemes", "Generate a raw audio waveform from acoustic features like a mel spectrogram", "Detect the speaker’s identity", "Remove background music"], "answer": 1, "explanation": "The vocoder transforms intermediate representations (e.g., mel spectrograms) into the final time-domain audio signal.", "topic": "Vision and language", "source": 29}, {"id": "527960", "stem": "Which of the following is an example of a multimodal dataset?", "options": ["A collection of text-only news articles", "A set of images with corresponding captions", "A database of audio files without transcriptions", "A list of spreadsheet tables"], "answer": 1, "explanation": "Multimodal datasets contain aligned data from different modalities, such as image-text pairs, enabling training of vision-language models.", "topic": "Vision and language", "source": 29}, {"id": "527929", "stem": "Which of the following is an example of a multimodal AI task?", "options": ["Spam email classification", "Generating a video description from its audio and visual tracks", "Text summarization of a news article", "Music genre classification from audio only"], "answer": 1, "explanation": "Combining audio and visual information to describe video content is inherently multimodal, requiring fusion of two modalities.", "topic": "Vision and language", "source": 29}, {"id": "528031", "stem": "What is the role of “attention” in an image captioning model?", "options": ["It helps the decoder focus on relevant parts of the image while generating each word", "It resizes the image to a smaller size", "It removes objects from the image", "It translates the caption into another language"], "answer": 0, "explanation": "Visual attention allows the model to dynamically look at different regions of the image as it produces each word of the caption.", "topic": "Vision and language", "source": 30}, {"id": "528001", "stem": "What is the main goal of noise reduction in speech preprocessing?", "options": ["Making the voice sound more robotic", "Improving the clarity and accuracy of downstream tasks like ASR", "Increasing the file size", "Changing the spoken language"], "answer": 1, "explanation": "Removing background noise helps ASR and speaker recognition systems perform more reliably.", "topic": "Vision and language", "source": 30}, {"id": "528119", "stem": "What is a “vector database” used for in a multimodal search system?", "options": ["Storing raw images in folders", "Efficiently indexing and querying high-dimensional embeddings", "Compressing video files", "Recording audio streams"], "answer": 1, "explanation": "Embeddings of images, text, or audio are stored in a vector database, allowing fast similarity search for retrieval applications.", "topic": "Vision and language", "source": 32}, {"id": "527999", "stem": "Which of the following is a direct application of speech synthesis?", "options": ["Transcribing a podcast", "Generating a spoken weather forecast from text", "Identifying a song from a short audio clip", "Reading a scanned contract into a database"], "answer": 1, "explanation": "Text-to-speech systems convert written text into a natural-sounding voice, for example reading out a weather bulletin.", "topic": "Vision and language", "source": 30}, {"id": "528048", "stem": "What is the purpose of “token merging” in some vision transformers?", "options": ["To increase the number of patches", "To combine redundant image patches to reduce computation", "To convert image tokens to text tokens", "To improve color accuracy"], "answer": 1, "explanation": "Token merging accelerates ViT inference by gradually merging similar tokens, maintaining accuracy while reducing computational load.", "topic": "Vision and language", "source": 31}, {"id": "527953", "stem": "What is the purpose of “attention” in a machine translation model?", "options": ["To ignore the source sentence entirely", "To dynamically weigh the relevance of source tokens when generating each target word", "To speed up translation by skipping words", "To change the font of the translated text"], "answer": 1, "explanation": "Attention mechanisms allow the decoder to focus on different parts of the source sentence, solving the bottleneck of a fixed-length context vector.", "topic": "Vision and language", "source": 29}, {"id": "527970", "stem": "What is the purpose of “non-maximum suppression” in object detection?", "options": ["To increase the number of boxes", "To eliminate duplicate bounding boxes predicting the same object", "To enhance image resolution", "To convert boxes to polygons"], "answer": 1, "explanation": "NMS filters overlapping boxes by keeping the one with highest confidence and suppressing others, ensuring a single detection per object.", "topic": "Vision and language", "source": 29}, {"id": "528105", "stem": "Which of the following is a challenge in OCR for historical documents?", "options": ["Consistent modern fonts", "Degraded paper, variable handwriting, and outdated typography", "Perfect digital scans", "Use of only one language"], "answer": 1, "explanation": "Historical documents present difficulties like faded ink, bleed-through, and irregular letter shapes that challenge standard OCR.", "topic": "Vision and language", "source": 32}, {"id": "528091", "stem": "Which of the following is a use case for “video question answering”?", "options": ["Generating a summary of a text document", "Asking \"Is the person in the video wearing a helmet?\" and receiving a yes/no answer", "Converting video frames to PDF", "Detecting the language of the audio"], "answer": 1, "explanation": "Video QA models understand spatiotemporal visual content to answer natural language queries about what happens in a video.", "topic": "Vision and language", "source": 31}, {"id": "527985", "stem": "Which of the following is an application of multimodal AI in healthcare?", "options": ["Transcribing doctor’s handwriting only", "Analyzing medical images along with patient clinical notes for diagnosis", "Replacing all human radiologists", "Voice cloning for entertainment"], "answer": 1, "explanation": "Multimodal models can integrate chest X-rays, MRI scans, and text-based patient history to assist in more accurate diagnoses.", "topic": "Vision and language", "source": 30}, {"id": "528055", "stem": "Which of the following is an example of using AI for media accessibility?", "options": ["Using facial recognition to unlock a phone", "Automatically generating sign language avatars from spoken news", "Detecting product defects", "Enhancing image resolution"], "answer": 1, "explanation": "Converting speech or text to sign language is a direct accessibility application, making content available to deaf or hard-of-hearing users.", "topic": "Vision and language", "source": 31}, {"id": "528057", "stem": "What is a “confusion matrix” used for in evaluating an image classifier?", "options": ["Showing the number of correct and incorrect predictions per class", "Visualizing the network architecture", "Plotting the loss curve over epochs", "Displaying the pixel intensity distribution"], "answer": 0, "explanation": "A confusion matrix breaks down true positives, false positives, etc., for each class, helping identify where the model confuses categories.", "topic": "Vision and language", "source": 31}, {"id": "528080", "stem": "What is a “data lake” often used for when training multimodal AI models?", "options": ["Storing only structured text", "Aggregating vast amounts of raw, unlabeled multimodal data (images, audio, video, text) for self-supervised learning", "Archiving model weights", "Managing GPU clusters"], "answer": 1, "explanation": "Large-scale self-supervised training requires huge repositories of diverse multimodal data, often stored in data lakes.", "topic": "Vision and language", "source": 31}, {"id": "528125", "stem": "Which of the following is an example of “intelligent document redaction”?", "options": ["Deleting the entire document", "Automatically locating and obscuring personally identifiable information (PII) like social security numbers", "Changing the font size", "Adding watermarks"], "answer": 1, "explanation": "AI can detect sensitive entities and apply black boxes or removal to ensure privacy compliance before sharing.", "topic": "Vision and language", "source": 32}, {"id": "527941", "stem": "Which of the following is a key component of a neural text-to-speech pipeline?", "options": ["Optical flow estimator", "Acoustic model and vocoder", "Bounding box regressor", "Language translator"], "answer": 1, "explanation": "The acoustic model converts text to acoustic features (mel spectrograms), and the vocoder transforms those features into a waveform.", "topic": "Vision and language", "source": 29}, {"id": "527928", "stem": "What is a common use case for speaker diarization in meeting transcription?", "options": ["Identifying the meeting topic", "Labeling each spoken segment with the corresponding speaker", "Translating the conversation in real time", "Converting the transcript to a summary"], "answer": 1, "explanation": "Diarization assigns speaker tags (e.g., Speaker A, Speaker B) to each utterance, making transcripts more readable and useful.", "topic": "Vision and language", "source": 29}, {"id": "528074", "stem": "Which of the following is NOT a typical output of a document intelligence API?", "options": ["Extracted text with bounding boxes", "Detected tables in structured format", "A spoken summary of the document", "Detected key-value pairs"], "answer": 2, "explanation": "Document intelligence APIs extract text, tables, and entities, but producing a spoken summary is not a standard document AI output without TTS integration.", "topic": "Vision and language", "source": 31}, {"id": "527917", "stem": "What is the purpose of a voice activity detector (VAD) in a speech pipeline?", "options": ["Recognizing the speaker’s identity", "Identifying segments that contain human speech versus silence/noise", "Translating speech to another language", "Generating synthetic voice samples"], "answer": 1, "explanation": "VAD isolates speech segments, reducing processing of silence and improving efficiency of downstream tasks like ASR.", "topic": "Vision and language", "source": 29}, {"id": "528068", "stem": "Which of the following is an example of “multimodal in-context learning”?", "options": ["Training a model from scratch on a new dataset", "Providing a few image-text examples in the prompt so the model can perform a new task without weight updates", "Translating a document without OCR", "Running a speech recognizer on a single sentence"], "answer": 1, "explanation": "Large multimodal models can follow demonstration patterns within the prompt, adapting to tasks like new visual classification without fine-tuning.", "topic": "Vision and language", "source": 31}, {"id": "528070", "stem": "What is the primary purpose of a “checkpoint” file in deep learning training?", "options": ["To debug the code", "To save the model parameters at a particular training step for resuming or deployment", "To visualize data distributions", "To encrypt the dataset"], "answer": 1, "explanation": "Checkpoints allow training to resume from a saved state and store the best model for later use.", "topic": "Vision and language", "source": 31}, {"id": "527922", "stem": "What is the key difference between object detection and image segmentation?", "options": ["Detection provides bounding boxes, while segmentation assigns a class label to each pixel", "Detection works only on videos", "Segmentation does not require training data", "Detection identifies objects but segmentation only detects edges"], "answer": 0, "explanation": "Object detection locates objects with boxes, whereas semantic or instance segmentation provides pixel-level classification.", "topic": "Vision and language", "source": 29}]}, {"id": "04-safety-operations", "level": 4, "rank": "Moderate", "title": "Safety, security, and operations", "minutes": 45, "cheat": "Cheat sheet 1.3 and 1.4 — monitor, secure, and responsible AI", "blurb": "Quotas, fairness, guardrails, and how a model reaches production safely.", "focus": ["HTTP 429 means callers are over the allowed rate or quota.", "Group fairness compares outcomes across groups. Overall accuracy does not show that.", "Keep a human in the loop when a wrong automated decision is costly.", "Roll a new model out to a small share of traffic and watch it before everyone gets it."], "pool": 240, "questions": [{"id": "528350", "stem": "What is a “gradual rollout” in AI deployment?", "options": ["Deploying to 100% of users instantly", "Starting with a small percentage of users and increasing over time while monitoring health", "Training the model gradually", "Removing the old model immediately"], "answer": 1, "explanation": "Gradual rollout (often synonymous with canary or phased rollout) limits risk by exposing the new model incrementally, allowing early detection of issues.", "topic": "Safety and operations", "source": 36}, {"id": "528264", "stem": "What is the primary purpose of an AI risk register?", "options": ["To list all models that have never failed", "To document identified risks, their likelihood, impact, and mitigation strategies for each AI system", "To track the daily stock price", "To store training data"], "answer": 1, "explanation": "A risk register is a governance tool for proactively managing AI risks (e.g., bias, security, operational), assigning ownership, and tracking controls.", "topic": "Safety and operations", "source": 34}, {"id": "528369", "stem": "What is a “regression test suite” for an AI model?", "options": ["A set of tests that ensure new model versions or code changes don't break existing functionality (e.g., a golden set of inputs with expected outputs)", "A test to measure the model's speed", "A fairness audit", "A user acceptance test"], "answer": 0, "explanation": "Regression tests verify that behavior on known inputs remains consistent, catching unintended breaking changes during development or deployment.", "topic": "Safety and operations", "source": 36}, {"id": "528331", "stem": "What is the role of “audit logging” in AI security?", "options": ["To speed up model inference", "To provide an immutable record of who accessed the system, what predictions were made, and when, enabling forensic analysis and compliance", "To reduce training time", "To compress model weights"], "answer": 1, "explanation": "Audit logs are essential for detecting breaches, monitoring insider threats, and proving regulatory compliance. They must be tamper-proof.", "topic": "Safety and operations", "source": 35}, {"id": "528356", "stem": "What is the purpose of a “threat model” for an AI system?", "options": ["To list all possible features", "To systematically identify potential security threats, vulnerabilities, and attack vectors specific to that system", "To measure model accuracy", "To count the number of API calls"], "answer": 1, "explanation": "Threat modeling (e.g., STRIDE) helps prioritize security controls by understanding how an adversary might attack the AI pipeline, from data collection to inference.", "topic": "Safety and operations", "source": 36}, {"id": "528163", "stem": "What is the main goal of adversarial testing in AI security?", "options": ["To measure carbon emissions", "To identify vulnerabilities by simulating malicious inputs", "To compress the model for mobile deployment", "To generate synthetic training data"], "answer": 1, "explanation": "Adversarial testing crafts inputs designed to cause misclassification or unsafe outputs, revealing weaknesses in model robustness. It is a proactive security measure. It does not measure emissions, compress models, or generate data for training.", "topic": "Safety and operations", "source": 33}, {"id": "528173", "stem": "What is the main purpose of rate limiting on an AI inference API?", "options": ["To improve model accuracy", "To prevent abuse and ensure service availability under high load", "To speed up token generation", "To audit model decisions"], "answer": 1, "explanation": "Rate limiting restricts the number of requests a user can make in a given timeframe, protecting the service from DDoS attacks, excessive costs, and resource exhaustion, thus maintaining availability.", "topic": "Safety and operations", "source": 33}, {"id": "528180", "stem": "What is the purpose of a feature store in an operational ML platform?", "options": ["To store raw log files for debugging", "To provide a centralized repository for consistent feature definitions and serving", "To manage container orchestration", "To host model weights"], "answer": 1, "explanation": "A feature store ensures that the same feature engineering logic is used during training and inference, reducing training-serving skew and enabling feature reuse. It doesn’t store logs or manage containers.", "topic": "Safety and operations", "source": 33}, {"id": "528267", "stem": "Which of the following is an example of a “representation harm” in AI?", "options": ["The model denies a loan unfairly", "A translation model associates \"nurse\" only with female pronouns, reinforcing stereotypes", "The model crashes during inference", "The model has high latency"], "answer": 1, "explanation": "Representational harm involves stereotypes, denigration, or erasure of groups in outputs. Allocative harm is about resource distribution (loan denial). Both are fairness concerns.", "topic": "Safety and operations", "source": 34}, {"id": "528282", "stem": "Which of the following is a practice that supports “operational resilience”?", "options": ["Single point of failure for all model serving", "Multi-region deployment with failover capability", "No monitoring", "Manual restarts only"], "answer": 1, "explanation": "Distributing the service across independent failure domains (regions) ensures that a regional outage doesn’t take down the entire service, a core resilience pattern.", "topic": "Safety and operations", "source": 35}, {"id": "528236", "stem": "Which of the following is a primary goal of a responsible AI review board?", "options": ["To develop front-end UI components", "To evaluate the ethical implications, risk level, and compliance of proposed AI projects", "To manage cloud storage buckets", "To train the final model"], "answer": 1, "explanation": "The review board provides oversight, assessing whether a project aligns with organizational values, regulatory requirements, and risk appetite before it proceeds.", "topic": "Safety and operations", "source": 34}, {"id": "528169", "stem": "What is the function of a gatekeeper model in a responsible AI architecture?", "options": ["To encrypt all model outputs", "To act as an additional layer that reviews and filters outputs for policy violations", "To balance load across inference servers", "To compress the model before serving"], "answer": 1, "explanation": "A gatekeeper (or guard) model sits alongside the main AI model to check outputs for toxicity, PII leakage, or other policy violations, blocking or rewriting them if necessary. This adds a safety net beyond built-in safeguards.", "topic": "Safety and operations", "source": 33}, {"id": "528298", "stem": "Which of the following is a key principle of a “responsible AI lifecycle”?", "options": ["Fire and forget: deploy models with no further oversight", "Iterative and continuous: responsible AI considerations are embedded from design through decommissioning", "Only consider ethics if there's a lawsuit", "Maximize accuracy at all costs"], "answer": 1, "explanation": "Responsible AI is not a one-time checklist but an ongoing practice integrated into every phase of the AI lifecycle, including monitoring and updating.", "topic": "Safety and operations", "source": 35}, {"id": "528342", "stem": "What is the main benefit of using a “service mesh” for AI inference security?", "options": ["It generates training data", "It can enforce mutual TLS, access control policies, and retries between the API gateway and model servers transparently", "It trains the model", "It eliminates all bugs"], "answer": 1, "explanation": "A service mesh abstracts network security and resilience logic, ensuring secure, authenticated, and reliable service-to-service communication without application code changes.", "topic": "Safety and operations", "source": 36}, {"id": "528284", "stem": "What is the function of a “bias mitigation” algorithm applied in pre-processing?", "options": ["To modify the model architecture", "To transform the training data to reduce discrimination while preserving predictive utility", "To change the deployment hardware", "To encrypt the model"], "answer": 1, "explanation": "Pre-processing methods like reweighing or relabeling adjust the data before training to reduce bias, without altering the model itself. Other types are in-processing and post-processing.", "topic": "Safety and operations", "source": 35}, {"id": "528223", "stem": "What is the main advantage of using a semantic cache in an LLM inference service?", "options": ["To retrain the model faster", "To reduce latency and cost by returning cached responses for semantically similar queries", "To encrypt model weights", "To increase the model’s vocabulary"], "answer": 1, "explanation": "A semantic cache stores previous query-response pairs and retrieves them when a new query is similar enough, avoiding costly re-inference. It improves efficiency and user experience.", "topic": "Safety and operations", "source": 34}, {"id": "528197", "stem": "What is the primary purpose of a data provenance tracking system in responsible AI?", "options": ["To compress datasets", "To record the origin, transformations, and usage rights of data used in AI models", "To increase training speed", "To cache model predictions"], "answer": 1, "explanation": "Data provenance (lineage) documentation ensures that data sources, consent, and processing steps are transparent, aiding compliance with regulations and enabling auditing. It doesn’t compress, speed up training, or cache predictions.", "topic": "Safety and operations", "source": 33}, {"id": "528315", "stem": "What is the purpose of “output length constraints” in a generative AI safety filter?", "options": ["To improve the model's grammar", "To prevent the model from generating extremely long, potentially harmful, or costly responses", "To increase model accuracy", "To encrypt the output"], "answer": 1, "explanation": "Limiting output length can mitigate the risk of verbose harmful content, reduce cost, and prevent abuse such as generating novels of toxic material.", "topic": "Safety and operations", "source": 35}, {"id": "528219", "stem": "What is the primary purpose of a service mesh in a microservices-based AI deployment?", "options": ["To label training data", "To manage service-to-service communication, including traffic routing and security policies", "To transform features", "To store model artifacts"], "answer": 1, "explanation": "A service mesh handles network connectivity, load balancing, retries, and mutual TLS between microservices without changing application code, enhancing reliability and security for AI components.", "topic": "Safety and operations", "source": 34}, {"id": "528228", "stem": "What is the role of a data protection officer (DPO) in an organization deploying AI?", "options": ["To code the neural network layers", "To ensure AI processing activities comply with data protection laws and advise on impact assessments", "To manage cloud infrastructure", "To design product UI"], "answer": 1, "explanation": "A DPO oversees compliance with data privacy regulations like GDPR, including advising on data protection impact assessments for AI systems that process personal data.", "topic": "Safety and operations", "source": 34}, {"id": "528177", "stem": "What is the primary reason to implement model versioning in a production environment?", "options": ["To reduce the model file size", "To enable traceability, rollback, and comparison of different model iterations", "To decrease inference latency", "To automatically generate documentation"], "answer": 1, "explanation": "Model versioning assigns unique identifiers to each trained model artifact, allowing teams to track which version is in production, quickly roll back to a prior version, and compare performance across versions.", "topic": "Safety and operations", "source": 33}, {"id": "528274", "stem": "What is the primary reason to use a “model card” even for an internal-only AI system?", "options": ["To satisfy marketing requirements", "To provide internal stakeholders and auditors with transparent documentation about the model's capabilities, limitations, and risks", "To replace the model's code", "To increase model accuracy"], "answer": 1, "explanation": "Model cards serve as transparency artifacts that help internal governance, risk management, and ensure responsible use, not just external communication.", "topic": "Safety and operations", "source": 34}, {"id": "528374", "stem": "What is the primary purpose of a “fault injection” test in a production-like environment?", "options": ["To verify that the system gracefully handles failures (e.g., network timeouts, database errors) without catastrophic impact", "To measure the model's precision", "To train the model", "To collect training data"], "answer": 0, "explanation": "Fault injection (a form of chaos engineering) validates resilience by deliberately causing failures, ensuring that fallbacks, retries, and alerts work as designed.", "topic": "Safety and operations", "source": 36}, {"id": "528185", "stem": "What is the primary objective of conducting regular red-teaming exercises on an AI system?", "options": ["To test the model’s accuracy on a validation set", "To find security and safety weaknesses through adversarial simulation", "To evaluate the energy consumption of training", "To measure the model’s learning rate convergence"], "answer": 1, "explanation": "Red-teaming involves experts deliberately trying to make the model fail or produce harmful outputs, uncovering vulnerabilities that standard evaluation might miss, thus strengthening safety and security.", "topic": "Safety and operations", "source": 33}, {"id": "528194", "stem": "Which of the following is an example of operational excellence in AI lifecycle management?", "options": ["Deploying models without any monitoring", "Automating model retraining pipelines triggered by performance degradation alerts", "Using only manual code reviews for model validation", "Running a single test environment for all stages"], "answer": 1, "explanation": "Automated retraining pipelines that respond to monitoring alerts reduce manual toil and accelerate recovery from drift, embodying operational excellence. Lack of monitoring, manual-only validation, and single environment are anti-patterns.", "topic": "Safety and operations", "source": 33}, {"id": "528161", "stem": "What is the main advantage of using shadow deployment when rolling out a new model version?", "options": ["It eliminates all downtime", "It allows the new model to process production traffic alongside the old model without affecting users", "It automatically labels new training data", "It reduces cloud storage costs"], "answer": 1, "explanation": "In shadow deployment, the new model receives a copy of live traffic and its outputs are logged and compared, but not served to users. This enables realistic testing without user impact. It does not eliminate downtime by itself, nor auto-label data.", "topic": "Safety and operations", "source": 33}, {"id": "528258", "stem": "Which of the following is a recommended practice for handling API keys used by an AI service?", "options": ["Commit them to the public repository", "Rotate keys periodically and never hardcode them; use a secrets manager", "Share keys via email", "Use the same key for all environments indefinitely"], "answer": 1, "explanation": "Secrets management with rotation minimizes the impact of a leaked key, while hardcoding and sharing are severe security anti-patterns.", "topic": "Safety and operations", "source": 34}, {"id": "528234", "stem": "What is a key characteristic of a “trustworthy” AI system according to many ethical guidelines?", "options": ["It maximizes shareholder value at any cost", "It is lawful, ethical, and robust, with human oversight and explainability", "It is a black box with no documentation", "It always uses the largest model available"], "answer": 1, "explanation": "Trustworthy AI frameworks (e.g., EU Ethics Guidelines) emphasize that systems should respect law, ethics, and be technically robust, with appropriate transparency and oversight.", "topic": "Safety and operations", "source": 34}, {"id": "528174", "stem": "Which of the following is an example of a proactive AI security measure during model development?", "options": ["Monitoring production logs for anomalies", "Running static analysis on model serialization formats to detect vulnerable code", "Setting up a rollback strategy", "Conducting post-incident reviews"], "answer": 1, "explanation": "Proactive security includes scanning model files (e.g., Pickle, ONNX) for embedded malicious code or known vulnerabilities before deployment. Monitoring, rollback, and post-incident reviews are reactive or operational measures.", "topic": "Safety and operations", "source": 33}, {"id": "528303", "stem": "Which of the following is a common limitation of using BLEU for evaluating generative AI outputs?", "options": ["It perfectly captures semantic meaning", "It relies on n-gram overlap and may penalize correct paraphrases, missing meaning similarity", "It requires no reference text", "It is only for speech"], "answer": 1, "explanation": "BLEU is a lexical metric that doesn’t understand meaning. A perfectly valid answer with different wording can get a low score, so it should be complemented with other metrics.", "topic": "Safety and operations", "source": 35}, {"id": "528230", "stem": "Which of the following is a common metric for evaluating the calibration of a probabilistic classifier?", "options": ["Expected Calibration Error (ECE)", "Mean Squared Error (MSE)", "Euclidean distance", "Silhouette score"], "answer": 0, "explanation": "ECE measures how well predicted probabilities align with actual empirical frequencies. Well-calibrated probabilities are important for risk-sensitive applications. MSE is for regression, others for clustering or distance.", "topic": "Safety and operations", "source": 34}, {"id": "528294", "stem": "Which of the following is an indicator that a model may have been subjected to a data poisoning attack?", "options": ["The model's inference latency is low", "Unexplained, targeted misclassifications for specific trigger patterns in the input", "The model's explanation quality improves", "The training time decreases"], "answer": 1, "explanation": "Data poisoning implants backdoors during training; at inference, the presence of a trigger (e.g., a specific pattern) causes a predetermined misclassification.", "topic": "Safety and operations", "source": 35}, {"id": "528208", "stem": "What is the key benefit of using a canary analysis tool like an automated rollback based on key metrics?", "options": ["It reduces the need for any human supervision", "It automatically detects regressions during a canary deployment and rolls back if metrics degrade", "It retrains the model with zero data", "It encrypts all model inference"], "answer": 1, "explanation": "Canary analysis tools compare the performance of the canary instance against a baseline using statistical tests and can trigger an automatic rollback if significant degradation is detected, reducing mean time to recovery.", "topic": "Safety and operations", "source": 33}, {"id": "528162", "stem": "Which of the following is a common key performance indicator (KPI) for monitoring an AI API’s operational health?", "options": ["Number of likes on social media", "P99 latency of inference responses", "Lines of code changed", "Number of model parameters"], "answer": 1, "explanation": "Latency, especially high percentiles like P99, reflects the worst-case response times users experience and is critical for SLO monitoring. Social media likes, code changes, and parameter count are not operational health metrics.", "topic": "Safety and operations", "source": 33}, {"id": "528326", "stem": "What is the main security risk of using an insecure deserialization function to load a model file from an untrusted source?", "options": ["Slower inference", "Remote code execution", "Increased model size", "Data normalization"], "answer": 1, "explanation": "Insecure deserialization (e.g., unpickling untrusted files) can execute arbitrary code, allowing attackers to take over the server. Secure formats like ONNX or SafeTensors are preferred.", "topic": "Safety and operations", "source": 35}, {"id": "528182", "stem": "Which of the following is a best practice for managing credentials used by an AI service to access a backend database?", "options": ["Hardcode credentials in the model’s source code", "Store credentials in a secure secrets manager and rotate them regularly", "Share a single set of credentials across all environments", "Embed credentials in the container image"], "answer": 1, "explanation": "Using a secrets manager (like a vault) with automated rotation reduces the risk of credential leakage. Hardcoding, sharing, or embedding in images are security anti-patterns.", "topic": "Safety and operations", "source": 33}, {"id": "528310", "stem": "Which of the following is a benefit of using a “blue/green” deployment over a “rolling deployment” for a critical AI model?", "options": ["It's cheaper", "Instant rollback by simply switching traffic back to the blue environment, without waiting for a rolling revert", "It uses less infrastructure", "It requires no testing"], "answer": 1, "explanation": "Blue/green provides a full parallel environment, enabling immediate traffic switching if the green environment has a problem, reducing recovery time compared to rolling back instances.", "topic": "Safety and operations", "source": 35}, {"id": "528201", "stem": "Which of the following is an example of a process that supports continuous monitoring of responsible AI metrics in production?", "options": ["Quarterly manual bias review", "Automated daily fairness metric dashboards with alerts", "Running a one-time fairness check before launch", "Disabling logging to save costs"], "answer": 1, "explanation": "Continuous monitoring requires automated, ongoing measurement with alerts, not just periodic or pre-launch checks. This ensures timely detection of fairness deviations in production.", "topic": "Safety and operations", "source": 33}, {"id": "528248", "stem": "Which of the following is an example of a content safety risk in a multi-modal AI system that processes both text and images?", "options": ["The model generates a longer response than expected", "The model outputs a description promoting violence after receiving a neutral image", "The model's latency increases by 10%", "The model uses too much GPU memory"], "answer": 1, "explanation": "Multi-modal models can produce harmful outputs based on visual inputs. Ensuring outputs across all modalities are safe is a core content safety requirement.", "topic": "Safety and operations", "source": 34}, {"id": "528241", "stem": "In responsible AI, “inclusive design” means:", "options": ["Designing the user interface using only one color", "Ensuring the AI system is accessible and works well for diverse users, including those with disabilities", "Only including technical team members in design decisions", "Limiting the training data to one demographic"], "answer": 1, "explanation": "Inclusive design proactively considers a wide range of human diversity, leading to AI systems that are fair and usable by everyone, avoiding discrimination or exclusion.", "topic": "Safety and operations", "source": 34}]}, {"id": "05-plan-secure", "level": 5, "rank": "Hard", "title": "Scenario lab: plan, secure, and monitor", "minutes": 60, "cheat": "Cheat sheet domain 1 — plan and manage an Azure AI solution", "blurb": "Longer scenarios on identity, networking, quotas, safety filters, and tracing.", "focus": ["Prefer keyless Microsoft Entra access. Do not embed keys in the app.", "A locked-down search or storage resource disables public access and uses a private endpoint.", "Provisioned throughput fits steady volume. Pay-as-you-go fits variable work. Batch fits offline jobs.", "Send Foundry traces to Application Insights. Content Safety should support human judgment on borderline cases."], "pool": 69, "questions": [{"id": "542433", "stem": "In Microsoft Foundry, a _____ is the organizing workspace that groups agents, evaluations, files, deployments, indexes, tracing, and datasets for an AI application lifecycle.", "options": ["project", "model catalog", "resource group", "storage container"], "answer": 0, "explanation": "A project is the Foundry workspace used to organize the assets involved in building and operating AI applications. This includes agents, evaluations, files, deployments, indexes, traces, and datasets associated with a development effort.\nA resource group or storage container can hold Azure resources or data, but those are Azure infrastructure constructs rather than the Foundry project-level workspace. The exam-relevant distinction is that Foundry projects organize AI development artifacts and lifecycle assets inside the Foundry experience.\nWhy the other options are incorrect:\n• B. The model catalog helps users discover and select models. It does not organize the full lifecycle of agents, evaluations, indexes, files, datasets, and tracing. A model catalog is model-selection focused. The question asks for the workspace construct that groups many project assets.\n• C. A resource group organizes Azure resources for management, billing, deployment, and access control. It is not the Foundry project workspace that directly organizes agents, evaluations, files, deployments, indexes, tracing, and datasets. A Foundry project may depend on Azure resources in a resource group. That does not make the resource group the Foundry-level organizing unit.\n• D. A storage container stores blobs such as files or data artifacts. It cannot organize agents, evaluations, model deployments, indexes, and tracing as a Foundry project does. It may support data storage behind a solution. It is too narrow for the lifecycle organization described in the stem.\nAzure AI Projects client library for Python\nAzure AI Projects client library for .NET", "topic": "Plan and secure", "source": 44}, {"id": "542109", "stem": "A retail app lets users retouch profile photos. The team wants to make subtle edits to clothing and background while preserving facial features as accurately as possible.\nWhich control is the best fit?", "options": ["Transparent background with PNG", "Stream with partial_images", "High input_fidelity", "JPEG output format"], "answer": 2, "explanation": "High input_fidelity is the best fit because Microsoft states that the input_fidelity parameter controls how much effort the model puts into matching the style and features of input images, especially facial features. The documentation also says that high input fidelity is intended for subtle edits without changing unrelated areas, which matches the scenario closely.\nThe other controls in the options affect output format or generation experience, not how faithfully the edit preserves the source image. Since the key requirement is facial preservation during light retouching, input_fidelity is the platform control that most directly addresses that need.\nWhy the other options are incorrect:\n• A. Transparent background with PNG. This combination is useful when the output must have no background, such as sticker assets or product cutouts. It does not instruct the model to preserve facial structure or maintain subtle likeness during edits. It solves transparency, not identity preservation.\n• B. Stream with partial_images. Streaming helps return intermediate images faster and improves perceived responsiveness for the user. It does not improve facial preservation or style matching of the edited image. This is a UX and latency control, not a fidelity control.\n• D. JPEG output format. JPEG changes the output encoding format and can be useful for delivery scenarios where transparency is not required. It does not influence how closely the output adheres to the input subject’s facial features. This is a file-format decision, not an edit-accuracy decision.\nAzure OpenAI in Microsoft Foundry Models REST API v1 preview reference\nUse the image generation tool in Foundry Agent Service", "topic": "Plan and secure", "source": 39}, {"id": "542167", "stem": "A customer support chatbot accepts free-form prompts from the public. The team wants to detect and block adversarial prompt attacks before the model generates a response.\nWhich control should you configure?", "options": ["Prompt Shields", "Azure AI Search", "Azure Monitor alerts", "Document Intelligence"], "answer": 0, "explanation": "Prompt Shields is the documented control for detecting and blocking adversarial user input attacks on large language models before content is generated. That makes it the best fit when the requirement is specifically to stop jailbreak-style or policy-bypassing prompt attacks at input time, rather than to do general monitoring or unrelated AI processing.\nAzure AI Content Safety provides broader harmful-content moderation capabilities, but Prompt Shields is the feature called out for adversarial prompt attack detection. In practice, this question is asking for the most specific responsible AI control for malicious prompt input, not a retrieval component, observability signal, or document-processing service.\nWhy the other options are incorrect:\nB. Azure AI Search. Azure AI Search is useful when you need indexing, retrieval, and grounding support, but the requirement here is to inspect incoming prompts for adversarial attacks before generation occurs. Nothing in the requirement asks for search or retrieval behavior. Prompt Shields is the control specifically documented for adversarial prompt detection and blocking.\nC. Azure Monitor alerts. Alerts help operators observe issues after telemetry is produced, and Foundry observability integrates with Azure Monitor for dashboards, metrics, and alerts. That is valuable for production monitoring, but it is not the primary safety filter that analyzes and blocks malicious prompts before the model responds. This question asks for a prevention control, not an observability layer.\nD. Document Intelligence. The scenario is not about extracting text, layout, or fields from files. It is about preventing adversarial prompt attacks against an LLM. Prompt Shields directly matches that responsible AI requirement, while document-processing capability does not.\nWhat is Azure AI Content Safety?\nGuardrails and controls overview in Microsoft Foundry", "topic": "Plan and secure", "source": 40}, {"id": "542001", "stem": "A product team is launching a new chat assistant in multiple countries. Traffic will be bursty, the team wants pay-per-token billing, and there is no data residency restriction.\nWhich deployment option is the best fit?", "options": ["Standard", "Data Zone Standard", "Global Standard", "Regional Provisioned"], "answer": 2, "explanation": "Global Standard is the best choice because the workload is bursty, the team wants pay-per-token billing, and there is no requirement to constrain inferencing to a single region or data zone. Microsoft’s deployment guidance positions Global Standard as a common starting point for general workloads, with dynamic routing across Azure’s global infrastructure and higher default quota than geography-based standard deployments.\nThis option also avoids reserving throughput in advance, which would be a poorer fit for variable demand. Provisioned deployments are for customers who need more predictable throughput and lower latency variance at scale, while Standard is regional and typically better suited to low-to-medium volume regional workloads.\nWhy the other options are incorrect:\n• A. Standard. Standard is a single-region pay-per-token deployment, so it does not offer the same global routing benefits as Global Standard. It is generally suited to low-to-medium volume regional workloads rather than globally distributed bursty traffic. It also does not match the requirement to avoid manual multi-region balancing as cleanly as Global Standard.\n• B. Data Zone Standard. Data Zone Standard is used when prompts and responses must stay within a Microsoft-defined US or EU data zone. In this scenario, the team explicitly has no such residency requirement, so constraining traffic to a data zone adds an unnecessary design restriction. Global Standard better matches the requirement set and typically offers broader model availability and higher initial throughput.\n• D. Regional Provisioned. Regional Provisioned uses reserved PTUs and is intended for predictable throughput and lower latency variance. That is more appropriate for steady, high-volume production traffic than for a bursty workload that benefits from pay-as-you-go economics. It also keeps processing in a single region, which is not needed here.\nMicrosoft Foundry Models overview\nAzure OpenAI in Microsoft Foundry Models quotas and limits", "topic": "Plan and secure", "source": 37}, {"id": "542045", "stem": "A support team is building an assistant that must inspect customer-submitted photos of damaged packages.\nThe assistant must describe what it sees and produce a short text summary.\nWhich option is the best fit for this task?", "options": ["Phi model", "gpt-4o", "File Search", "Azure AI Search"], "answer": 1, "explanation": "This task is fundamentally multimodal because the input includes images and the output is text. Microsoft positions the gpt-4o family as the multimodal family with vision support for agent workloads, which makes it the strongest fit here.\nFile Search and Azure AI Search are tools for grounding or retrieval, not models for native image understanding. A Phi model can be efficient for smaller text-centric workloads, but this scenario is about understanding photos first, so a multimodal model is the better match.\nWhy the other options are incorrect:\nA. Phi model. Phi models are relevant when you want a smaller, less compute-intensive language model for efficient text workloads. That is a useful trade-off for some tasks, but it does not directly address the core requirement here, which is image understanding. In this scenario, efficiency matters less than choosing a model family designed for vision input.\nC. File Search. File Search is a built-in tool that augments an agent with knowledge from uploaded files or proprietary documents by using vector search. It helps with retrieval over documents, not with understanding package photos as the primary input. Choosing File Search would solve the wrong problem type.\nD. Azure AI Search. Azure AI Search is used to ground agents with data from an existing Azure AI Search index. That is valuable when you already have indexed enterprise content to retrieve from, but it does not replace a multimodal model for interpreting images. Here, there is no stated need for an existing search index at all.\nFoundry Models sold directly by Azure\nAgent tools overview for Microsoft Foundry Agent Service", "topic": "Plan and secure", "source": 38}, {"id": "542423", "stem": "A regulated claims-processing agent summarizes retrieved policy evidence and can recommend claim approval. Auditors must review how each answer was produced and who approved high-impact actions.\nWhich design element should you include?", "options": ["Token metrics and model temperature", "Content filters and private endpoints", "Traces, provenance, citations, approvals", "Fine-tuning and batch evaluation"], "answer": 2, "explanation": "Traces, provenance metadata, citations, and approvals directly support auditability. Trace logging shows execution flow, provenance metadata and citations connect outputs to source material, and approval workflows document human authorization before high-impact actions.\nThe important distinction is that auditability is about reconstructing what happened and why. Monitoring, filtering, networking, and evaluation can all be valuable, but they do not by themselves provide the evidence chain required for review.\nWhy the other options are incorrect:\n• A. Token metrics and model temperature can help analyze cost, latency, and generation behavior. They do not show the full decision path, cited evidence, or approval history. Auditors would still lack a reliable record of which sources supported the answer and who approved the action.\n• B. Content filters and private endpoints improve safety and network security. They do not provide provenance, citations, or workflow approval records. A secure system can still be unauditable if it does not capture trace and decision evidence.\n• D. Fine-tuning and batch evaluation can improve or assess model behavior. They do not create per-request traceability for production decisions. Batch evaluation also happens outside the live approval path and cannot prove that a specific claim recommendation used the correct cited evidence.\nObservability in generative AI\nBuild a workflow in Microsoft Foundry", "topic": "Plan and secure", "source": 44}, {"id": "542102", "stem": "A team is building a leave-request assistant in Foundry.\nThe process must route low-risk requests automatically, branch high-risk requests for manager review, and wait for approval before continuing.\nWhich Foundry capability should the team use?", "options": ["Foundry workflow", "Single agent thread", "Content Safety Studio", "Vector index"], "answer": 0, "explanation": "Foundry workflow is the best fit because Microsoft describes workflows as UI-based, declarative sequences of actions for orchestrating agents and business logic. The workflow guidance explicitly says workflows are ideal when you need branching logic and human-in-the-loop steps such as approvals or clarifying questions, which matches this semiautonomous approval scenario directly.\nA single agent thread by itself does not give you the same explicit orchestration model for repeatable branching and approval gates. The AI-103 study guide also places “Build autonomous or semiautonomous workflows with safeguards and approval flow controls” under Foundry agent-building skills, which aligns this scenario to workflow orchestration rather than search indexing or moderation tooling alone.\nWhy the other options are incorrect:\n• B. Single agent thread. A single agent thread can maintain conversation state, but the workflow article specifically calls out workflows for repeatable orchestration, branching, and human-in-the-loop steps. That means a thread alone is too narrow for a governed semiautonomous process that must pause, route, and resume predictably. It is part of an agent experience, but it is not the best control plane for approval flow logic.\n• C. Content Safety Studio. Content Safety Studio is for testing and building moderation systems that detect harmful or undesirable content. That helps with safeguards around unsafe inputs and outputs, but it does not provide the process orchestration, branching, or approval-wait behavior the scenario requires. It is a useful safety component, not the primary orchestration mechanism for the workflow itself.\n• D. Vector index. A vector index supports retrieval and grounding patterns, not approval routing or semiautonomous control flow. Nothing in the workflow guidance suggests that vector indexing is the correct tool for branching logic or pause-and-approve execution. It could support knowledge access in an agent, but it does not implement the approval process described in the question.\nBuild a workflow in Microsoft Foundry\nUsing function tools with human in the loop approvals", "topic": "Plan and secure", "source": 39}, {"id": "542002", "stem": "A legal review solution will be used by teams across France and Germany. The company requires prompts and responses to stay within the EU data zone, expects variable demand, and wants to avoid reserved capacity charges.\nWhich deployment option should you choose?", "options": ["Global Provisioned throughput", "Data Zone Standard", "Standard", "Data Zone Provisioned capacity"], "answer": 1, "explanation": "Data Zone Standard is the best fit because it keeps inferencing within the Microsoft-defined data zone while still using pay-per-token billing. Microsoft’s deployment comparison guidance specifically maps Data Zone Standard to EU or US data zone compliance needs when customers want standard, consumption-based deployment behavior rather than reserved throughput.\nThe scenario also says demand is variable, which points away from provisioned capacity. Provisioned types are recommended when low latency variance and consistent high throughput matter enough to justify reserved PTUs, whereas Standard types are the better fit for burstier or less predictable usage.\nWhy the other options are incorrect:\n• A. Global Provisioned throughput. Global Provisioned offers reserved capacity and global routing, but it does not confine processing to the EU data zone. The scenario explicitly requires EU data zone processing, so a global deployment would violate the residency constraint. It also introduces reserved-capacity economics the team is trying to avoid.\n• C. Standard. Standard keeps processing in a single deployment region rather than across the EU data zone. That can work for single-region compliance requirements, but it does not match the broader EU data zone requirement stated here. It also does not provide the specific zone-based routing model Microsoft documents for Data Zone deployment types.\n• D. Data Zone Provisioned capacity. This option does satisfy the EU data zone boundary, but it uses reserved PTUs intended for predictable high-throughput workloads. The scenario emphasizes variable demand and a desire to avoid reserved capacity charges, which makes Data Zone Standard the more appropriate operational and financial choice. It would be oversizing the deployment model for the described traffic pattern.\nFeature availability across cloud regions\nAzure OpenAI in Microsoft Foundry Models quotas and limits", "topic": "Plan and secure", "source": 37}, {"id": "542094", "stem": "A team connects a Foundry agent to Azure AI Search by using keyless authentication.\nThe project managed identity can see the search resource in Azure, but tool calls return 403. The identity currently has only Reader on the search service.\nWhat should you do next?", "options": ["Regenerate admin keys", "Assign Search Index Data Contributor and Search Service Contributor", "Disable role-based access control", "Add Cognitive Services OpenAI User"], "answer": 1, "explanation": "For Foundry agents using Azure AI Search with keyless authentication, Microsoft documents that the project managed identity needs Azure RBAC roles on the search service. The specific roles called out are Search Index Data Contributor and Search Service Contributor. A plain Reader assignment explains why the identity can see the resource but still fails at runtime when the tool tries to perform the required search operations.\nThis is also consistent with Azure AI Search RBAC guidance, which distinguishes ordinary Azure visibility from data-plane and service-level permissions. When RBAC is enabled, data-plane access is controlled through the appropriate search roles rather than through local keys or generic Reader access.\nWhy the other options are incorrect:\n• A. Regenerate admin keys. The scenario is explicitly using keyless authentication, so rotating keys does not address the missing RBAC permissions. It also moves away from the intended security posture instead of fixing it. The real failure is authorization of the managed identity, not key freshness.\n• C. Disable role-based access control. Turning off RBAC would weaken the security model and contradict the keyless design the team intentionally chose. Microsoft’s guidance is to use RBAC and Entra ID instead of keys when moving to more secure access patterns. The best next step is to assign the correct roles, not to back out of the control.\n• D. Add Cognitive Services OpenAI User. That role is relevant for authorizing access to Azure OpenAI, not for giving a Foundry project managed identity the correct permissions on Azure AI Search. The failure described is on the search side, so the missing permission must be a search RBAC role. This option targets the wrong resource and the wrong access boundary.\nConfigure Apps for Role-Based Security – Azure AI Search\nEnable Role-Based Access Control – Azure AI Search", "topic": "Plan and secure", "source": 38}, {"id": "542187", "stem": "A deployed Foundry agent already appears in the Agent Monitoring Dashboard. One analyst can open the dashboard, but log-based views still fail. The analyst already has RBAC access to the connected Application Insights resource.\nWhich additional Azure role should you assign?", "options": ["Reader", "Log Analytics Reader", "Monitoring Contributor", "Cognitive Services Data Reader"], "answer": 1, "explanation": "The best answer is Log Analytics Reader. Microsoft’s Agent Monitoring Dashboard documentation states that the dashboard reads telemetry from the Application Insights resource connected to the Foundry project, and that for log-based views you also need access to the associated Log Analytics workspace. It specifically calls out assigning the Log Analytics Reader role for log access.\nThis is a good AI-103 distinction because project access and Application Insights access are not the same as the permissions required to query log-based data in the linked workspace. In other words, the monitoring pipeline can already exist, but the analyst still needs the correct workspace-level log access to use those views successfully.\nWhy the other options are incorrect:\nA. Reader. The generic Reader role is plausible because it grants read access to Azure resources, but this question is specifically about log-based views tied to the associated Log Analytics workspace. Microsoft’s Foundry monitoring guidance explicitly names Log Analytics Reader for that scenario, which is more specific than a generic resource reader role. Reader does not match the documented prerequisite called out for those views.\nC. Monitoring Contributor. Monitoring Contributor can view monitoring data and modify monitoring settings, so it can sound like a stronger answer. But the question is not asking for a role to configure monitoring resources or edit alerting settings. It asks which additional role is needed for log-based views, and Microsoft explicitly identifies Log Analytics Reader for that requirement.\nD. Cognitive Services Data Reader. This option is unrelated to the stated problem. The issue is not model inference permissions or AI service data-plane access; it is workspace log access for monitoring telemetry. The relevant documented dependency is the associated Log Analytics workspace and the Log Analytics Reader role.\nAzure built-in roles for Monitor\nManage access to Log Analytics workspaces", "topic": "Plan and secure", "source": 40}, {"id": "542291", "stem": "A generative AI app recently added detailed formatting instructions to its system prompt. Since the change, valid responses often stop mid-sentence even though the model selects the correct information and no safety filter is triggered.\nWhat should the engineer adjust first?", "options": ["Increase max_tokens", "Lower temperature", "Disable content filtering", "Add semantic ranking to retrieval"], "answer": 0, "explanation": "Increasing max_tokens is the best first adjustment because the symptom is response truncation after the prompt became longer and more detailed. The model is selecting the correct information, and the issue is not randomness or unsafe content. The response likely needs a larger output budget to complete the required format.\nThis question tests operational tuning rather than general model quality. Temperature affects randomness, retrieval affects source selection, and content filtering affects safety enforcement. When answers stop mid-sentence, max_tokens is the generation parameter most directly tied to the maximum response length.\nWhy the other options are incorrect:\n• B. Lower temperature can make responses more focused and less random. It does not directly increase the number of tokens the model is allowed to produce. If the response is being cut off because the output budget is too small, lowering temperature will not reliably fix truncation. It may improve consistency, but not completion length.\n• C. Disable content filtering is not justified because the scenario states no safety filter is triggered. Content filters are important controls for production generative AI systems. Disabling them would weaken safety without addressing the observed issue. This option confuses safety enforcement with response length management.\n• D. Add semantic ranking to retrieval may improve relevance when the app retrieves poor or weakly ranked source content. The scenario says the model selects the correct information, so retrieval quality is not the primary issue. Semantic ranking also does not control how many tokens the model can generate. It is plausible in RAG troubleshooting, but not for mid-sentence truncation.\nAzure OpenAI in Microsoft Foundry Models REST API\nMicrosoft Foundry Playgrounds", "topic": "Plan and secure", "source": 42}, {"id": "542284", "stem": "A production agent passes manual testing but later produces responses that violate the organization’s safety policy. The team can see latency, token usage, and exceptions, but there are no safety scores or evaluator results for production samples.\nWhat should the team implement next?", "options": ["Add a private endpoint", "Increase model token quota", "Rebuild the vector index", "Enable continuous evaluations"], "answer": 3, "explanation": "The best next step is to enable continuous evaluations so the team can measure quality and safety signals from production samples or representative datasets over time. The issue is not that the system lacks basic telemetry; it already has latency, token usage, and exception data. The missing capability is responsible AI evaluation output that can detect safety regressions.\nThis is a common AI-103 troubleshooting distinction. Operational monitoring tells you whether the system is running, but evaluator-based instrumentation tells you whether responses remain acceptable against quality and safety criteria. Continuous evaluation helps identify degradation as prompts, data, users, and agent behavior change.\nWhy the other options are incorrect:\n• A. Add a private endpoint improves network isolation and reduces public exposure. It is useful when the problem is secure connectivity to Azure services. However, the reported issue is unsafe generated content and missing safety scores. A private endpoint would not produce evaluator results or detect policy-violating responses.\n• B. Increase model token quota could help if requests were failing because of quota limits or throttling. The scenario does not describe quota errors, rate limits, or insufficient throughput. More quota could even allow more unsafe responses to be produced without better instrumentation. It does not solve the missing safety evaluation gap.\n• C. Rebuild the vector index may help if retrieval quality is poor because documents are stale, badly chunked, or incorrectly embedded. The scenario does not indicate a retrieval failure or index corruption. Even if the vector index were improved, the team would still lack safety scoring for generated responses. This option targets grounding data, not responsible AI instrumentation.\nObservability in Generative AI – Microsoft Foundry\nRun evaluations from the Microsoft Foundry portal", "topic": "Plan and secure", "source": 42}, {"id": "542424", "stem": "A finance analyst uploads CSV files and asks an assistant to calculate trends, generate charts, and iteratively inspect intermediate results. The assistant must run Python in a controlled execution environment rather than relying only on text generation.\nWhich capability should be included?", "options": ["Large language model deployment", "Multimodal model deployment", "Small language model deployment", "Code Interpreter tool"], "answer": 3, "explanation": "The Code Interpreter tool is the best fit because the requirement is to execute Python over uploaded data and generate analytical outputs such as calculations and charts. A model can reason about the user’s request, but the tool provides the execution environment needed to perform the data analysis reliably.\nThis is a common AI-103 distinction: not every task is solved by choosing a larger model. Foundry Tools extend an agent or application with specific capabilities such as code execution, retrieval, or external tool use. For this workload, the correct design is model plus tool, not a different model category alone.\nWhy the other options are incorrect:\n• A. A large language model deployment can reason about the request and produce explanations, but it does not by itself execute Python against uploaded CSV files. It may generate code, but generated code is not the same as executing code in a managed sandbox. The requirement specifically asks for iterative calculations and charts from data. That makes a tool capability necessary.\n• B. A multimodal model deployment is useful when inputs include images, audio, video, or other non-text modalities. The scenario is about CSV analysis and Python execution, not visual or multimodal understanding. A multimodal model would add capability that is not required for the workload. It still would not replace the need for a code execution environment.\n• C. A small language model deployment can be useful for narrow, low-latency, or lower-cost text tasks. It is not the best choice for interactive data analysis that requires running Python. Even if it can classify or summarize text efficiently, it does not provide sandboxed execution. The key requirement is computational tool use, not smaller model size.\nAgent tools overview for Foundry Agent Service\nMicrosoft Foundry Models overview", "topic": "Plan and secure", "source": 44}, {"id": "542262", "stem": "You are designing a Foundry-based text analysis solution for customer feedback. The app must identify named entities, extract main topics, generate a short summary, and return the result as a predictable JSON object for downstream processing.\nWhich design approach best satisfies the requirement?", "options": ["Azure AI Search semantic ranking", "Document Intelligence custom extraction", "Foundry model with tools", "Content Safety groundedness detection"], "answer": 2, "explanation": "A Foundry model with tools is the best fit because the solution needs generative prompting plus supporting text-analysis capabilities. The model can generate summaries and structured outputs, while Foundry Tools such as Azure Language capabilities can support entity and key phrase extraction.\nThis design also supports a predictable downstream contract when paired with structured JSON output. The important distinction is that the solution is not merely indexing, extracting fields from document layouts, or moderating content; it is orchestrating language analysis and generation into a structured response.\nWhy the other options are incorrect:\n• A. Azure AI Search semantic ranking is useful when improving retrieval relevance over indexed content. It can help a RAG solution find better passages, but it does not directly generate summaries or enforce structured JSON output. It also does not replace named entity extraction or key phrase extraction. This option confuses search ranking with language analysis orchestration.\n• B. Document Intelligence custom extraction is plausible if the input is forms, invoices, or scanned documents with layout-based fields. The scenario is about unstructured customer feedback, topics, entities, summaries, and JSON output. Document Intelligence is not the best primary choice for general text summarization and topic extraction. It solves document field extraction more than language-model text analysis.\n• D. Content Safety groundedness detection can help evaluate whether generated output is grounded in supplied context. It is useful for safety and reliability checks in generative applications. However, it does not extract topics, identify entities, generate summaries, or create the final JSON structure. It may support governance, but it is not the core implementation approach.\nNamed Entity Recognition overview\nKey phrase extraction overview", "topic": "Plan and secure", "source": 41}, {"id": "542027", "stem": "An operations team wants to estimate system-level throughput for an Azure OpenAI workload and understand how input and output token volumes change over time.\nThey want to use native Azure Monitor metrics rather than infer usage only from application logs.\nWhich metric pair should they prioritize?", "options": ["Blocked Volume and Safety System Event", "Time to Response and Time to Last Byte", "Processed Prompt Tokens and Generated Completion Tokens", "Azure OpenAI Requests and Potentially Abusive User Count"], "answer": 2, "explanation": "Processed Prompt Tokens and Generated Completion Tokens are the correct pair. Microsoft’s Azure OpenAI latency guidance says two metrics are needed to estimate system-level throughput with Azure Monitor metrics: Processed Prompt Tokens for input TPM and Generated Completion Tokens for output TPM.\nThese are token analytics metrics, not latency or safety metrics. Microsoft’s monitoring reference also lists Processed Prompt Tokens and Generated Completion Tokens as key Azure OpenAI usage metrics, which makes them the strongest fit when the question is specifically about input/output token consumption and throughput sizing.\nWhy the other options are incorrect:\nA. Blocked Volume and Safety System Event. These are safety-oriented metrics, not token throughput metrics. Microsoft lists them under content safety monitoring, which is useful for harmful-content oversight and policy signals but not for estimating how many prompt and completion tokens a workload processes over time. They answer a different observability question.\nB. Time to Response and Time to Last Byte. These are latency metrics and are valuable when you want to understand responsiveness and end-to-end completion timing. However, they do not directly quantify input and output token volume for throughput estimation. Microsoft specifically points to Processed Prompt Tokens and Generated Completion Tokens for system-level throughput analysis.\nD. Azure OpenAI Requests and Potentially Abusive User Count. Request counts help with load monitoring, and Potentially Abusive User Count is a safety metric, but neither metric pair isolates input and output token consumption. The question asks for token analytics suitable for throughput analysis, and Microsoft’s guidance is much more specific than simple request volume plus a safety signal.\nAzure OpenAI monitoring data reference\nMonitor Azure OpenAI in Microsoft Foundry Models", "topic": "Plan and secure", "source": 37}, {"id": "542093", "stem": "A bank is deploying a Foundry-based assistant into production.\nRequirements:\nDo not store secrets in application code.\nUse per-principal auditability and least-privilege access.\nKeep Azure OpenAI locked down by network rules.\nAllow Azure AI Search to call the embedding endpoint.\nWhich configuration best meets the requirements?", "options": ["API keys and private DNS", "Service principal secret and service endpoints", "Managed identity, RBAC, trusted services exception", "Query keys and search firewall"], "answer": 2, "explanation": "For production workloads, Microsoft recommends Microsoft Entra ID over API keys because it enables managed identities, conditional access, and granular RBAC, while API keys are coarse-grained and better suited to rapid prototyping. That directly addresses the requirements for keyless credentials, per-principal auditability, and least privilege.\nThe remaining requirement is allowing Azure AI Search to reach Azure OpenAI while network rules stay in place. Microsoft documents that Azure OpenAI can allow trusted Azure services access, and those services authenticate by using managed identity when the appropriate role assignment is present. Azure Search is one of the listed trusted services, and Microsoft also documents assigning the Cognitive Services OpenAI User role to the search service’s managed identity for this pattern.\nWhy the other options are incorrect:\n• A. API keys and private DNS. Private DNS can help name resolution, but it does not solve identity, role policy, or secret elimination by itself. API keys also fail the per-principal auditability and least-privilege requirement because keys are coarse-grained and not tied to individual principals the way Entra ID tokens are. This makes the option incomplete even if networking pieces are present.\n• B. Service principal secret and service endpoints. A service principal with a secret still leaves you managing secrets, which directly violates the no-secrets requirement. Service endpoints are also not the same control as a trusted-services exception plus managed identity flow into Azure OpenAI. The official guidance for production security emphasizes Entra ID and managed identities instead.\n• D. Query keys and search firewall. Query keys are unrelated to authorizing Azure AI Search to call Azure OpenAI embeddings through managed identity. A search firewall alone also does not satisfy the identity and least-privilege requirements for the end-to-end design. The core missing pieces are RBAC-backed keyless auth and the trusted-service path for Azure OpenAI.\nConfigure Virtual Networks for Foundry Tools\nConfigure a Managed Identity – Azure AI Search", "topic": "Plan and secure", "source": 38}, {"id": "542411", "stem": "A bank is designing an agent-based loan-assistance app. The app must access Foundry model deployments, a private search index, customer documents, and Key Vault secrets. Security requires least privilege, no embedded secrets in code, and private access paths for platform resources.\nWhich infrastructure design best satisfies the requirements?", "options": ["API keys stored in app configuration", "Managed identities with private endpoints", "Public endpoints with IP allowlists", "Shared service principal credential"], "answer": 1, "explanation": "Managed identities with private endpoints best satisfy the security requirements. Managed identity supports secretless access with Azure RBAC, while private endpoints reduce public network exposure for supported Azure resources.\nThe scenario requires both identity hardening and network isolation. API keys or shared credentials may allow access, but they do not provide the same least-privilege and secretless operational model as managed identities combined with private connectivity.\nWhy the other options are incorrect:\n• A. API keys stored in app configuration introduce secret-management risk and do not meet the no-embedded-secrets requirement. App configuration may centralize settings, but it does not remove the need to protect and rotate secrets. API keys are also typically broader and less identity-aware than RBAC assignments. This design is weaker for least privilege.\n• C. Public endpoints with IP allowlists can reduce exposure, but they still rely on public network paths. IP allowlists do not solve secretless authentication by themselves. They also become operationally brittle when clients, agents, or hosted services change outbound addresses. This option addresses part of networking but misses the identity requirement.\n• D. A shared service principal credential can authenticate workloads, but it creates credential distribution and rotation overhead. Sharing one credential also weakens workload-level accountability and least privilege. It does not inherently provide private network access. This option is plausible for automation, but it is not the best design for secure agent-based infrastructure.\nAzure Private Link overview\nRole-based access control in Azure AI services", "topic": "Plan and secure", "source": 44}, {"id": "542308", "stem": "Refer to:\nhttps://docs.google.com/document/d/1OOAvXtRkR0_VHHsLi486CG0AFxyqZVTDWRz1Kfq2KK0/edit-usp=sharing\nYou need to satisfy E1, BR2, TR2, and C2.\nThe selected model supports all deployment types shown in the answer options. Pinnacle has sufficient quota in Australia East and plans to purchase a one-year reservation after production load testing.\nWhich deployment type should you select?", "options": ["Global Standard", "Data Zone Standard", "Global Provisioned", "Regional Provisioned"], "answer": 3, "explanation": "Regional Provisioned uses the ProvisionedManaged deployment type. It allocates dedicated provisioned throughput and keeps model processing within the deployment’s specific Azure region. This satisfies Pinnacle’s requirement for reserved capacity, predictable latency, and processing restricted to Australia East.\nProvisioned deployments can be billed hourly during testing and can later be covered by an Azure Reservation for a sustained production workload. Pinnacle must size the required Provisioned Throughput Units from its expected prompt size, output size, request rate, and model selection. The available PTU quota must exist in the target region before the deployment is created.\nWhy the other options are incorrect:\nA. Global Standard can dynamically process requests across the global Azure infrastructure that supports the selected model. It provides pay-as-you-go capacity but does not reserve dedicated throughput for Pinnacle. Latency and available throughput can vary with service demand. It also fails C2 because processing is not restricted to Australia East.\nB. Data Zone Standard keeps processing within a Microsoft-defined data zone, such as the Asia-Pacific data zone. It does not guarantee that processing remains specifically in Australia East. Standard deployments also use shared pay-as-you-go capacity rather than reserved PTUs. This option therefore fails both TR2 and C2.\nC. Global Provisioned provides reserved PTUs and predictable high throughput. However, its processing scope is global rather than restricted to the resource’s deployment region. A reservation changes the capacity and billing model but does not impose single-region processing. It therefore satisfies BR2 but violates C2.\nCreate a provisioned deployment\nProvisioned throughput billing", "topic": "Plan and secure", "source": 42}, {"id": "542089", "stem": "A healthcare organization is deploying a clinical summarization model in Foundry. The deployment must meet these requirements:\nPrompts and responses must stay within the United States data zone\nTraffic is steady and high throughout the day\nThe application team wants lower latency variance during sustained load\nThey are willing to pay for reserved capacity\nWhich deployment type is the best fit?", "options": ["DataZone Provisioned", "Global Standard", "DataZone Standard", "Global Batch"], "answer": 0, "explanation": "DataZone Provisioned is the best match because it aligns with all three major constraints at the same time: US data-zone processing, consistent high-volume workload, and lower latency variance. Microsoft’s deployment guidance recommends DataZone Provisioned for US data-zone compliance when reserved capacity is acceptable, and it recommends Provisioned types when consistent throughput and lower latency variance are required.\nThe other choices each miss at least one critical requirement. The question is not asking for the cheapest elastic option or a large asynchronous batch pattern; it is asking for a production deployment that combines geography control with predictable performance under steady demand.\nWhy the other options are incorrect:\n• B. Global Standard. This is a strong default for general workloads and variable traffic, and Microsoft notes that it offers broad availability and high initial throughput. However, global processing can occur in any Azure geography where the model is deployed, which breaks the US data-zone requirement. It also does not provide the lower latency variance that Provisioned types are meant to address.\n• C. DataZone Standard. This does satisfy the US data-zone processing requirement, so it is a plausible distractor. The problem is that Standard types are better for variable or bursty traffic and do not provide the same predictable throughput and lower latency variance as Provisioned types. Because the workload is steady and high, this is not the strongest deployment choice.\n• D. Global Batch. Batch is intended for large asynchronous jobs with delayed turnaround and lower cost, not for interactive steady-state production inferencing. It also uses global processing rather than US data-zone restriction. This option fails both the responsiveness pattern and the geography constraint in the scenario.\nDeploy Microsoft Foundry Models in the Foundry portal\nEndpoints for Microsoft Foundry Models", "topic": "Plan and secure", "source": 38}, {"id": "542125", "stem": "A multinational insurer has 40,000 reviewed compliance summaries and extraction examples. The current prompt uses many examples, but it is becoming too large, too slow, and too expensive. The team wants:\nhigher-quality domain outputs than prompt engineering alone\nmore training examples than fit in the request context\nshorter prompts in production\nlower latency where possible\nWhich component or approach should be included?", "options": ["Fine-tuning", "Longer system message", "JSON mode", "More few-shot turns"], "answer": 0, "explanation": "Fine-tuning is the best answer because Microsoft states that it can provide higher-quality results than prompt engineering alone, lets you train on more examples than fit in the request context, and can reduce token usage by allowing shorter prompts. The documentation also notes that this can lower latency, particularly when using smaller models.\nThis makes fine-tuning the right escalation path when the domain task has many reviewed examples and the prompt-based approach is hitting context, cost, and latency limits. By contrast, simply adding more examples to the prompt pushes the solution further into the exact scaling problem described in the question.\nWhy the other options are incorrect:\n• B. Longer system message. A longer system message can add more rules, but Microsoft warns that overly long system messages consume context window and reduce room for user content. It also does not solve the requirement to leverage many more examples than fit in a prompt. This option increases prompt size rather than addressing the scaling issue.\n• C. JSON mode. JSON mode helps with valid JSON formatting, not with domain adaptation quality, training on many examples, or reducing prompt length. It is a formatting control, not a customization approach for improving specialized summarization or extraction behavior at scale. This option addresses structure, not model adaptation.\n• D. More few-shot turns. Few-shot examples are useful for priming behavior during the current inference, and Microsoft documents them as a way to condition the model with example input-output pairs. But the question explicitly says the prompt is already getting too large, slow, and expensive. Adding more few-shot turns would worsen the context and token problem instead of solving it.\nPrompt engineering techniques – Microsoft Foundry\nSystem message design for Azure OpenAI", "topic": "Plan and secure", "source": 39}, {"id": "542307", "stem": "Refer to:\nhttps://docs.google.com/document/d/1OOAvXtRkR0_VHHsLi486CG0AFxyqZVTDWRz1Kfq2KK0/edit-usp=sharing\nYou need to satisfy E2, BR1, and TR1.\nThe security team confirms that attacks can originate from either an engineer’s prompt or hidden instructions contained in a retrieved supplier bulletin. Both input sources must be evaluated before the model generates a response.\nWhich Azure AI Content Safety capability should you implement?", "options": ["Groundedness detection", "Prompt Shields", "Protected material detection", "Custom blocklist"], "answer": 1, "explanation": "Prompt Shields is designed to detect both user prompt attacks and document attacks. User prompt attacks are adversarial instructions supplied directly by a user, while document attacks are instructions embedded in external content that is added to a model’s context. This directly addresses the two attack paths described by BR1 and TR1.\nPinnacle should analyse the engineer’s prompt and the retrieved passages before sending them to the model. If Prompt Shields identifies an attack, the application can reject the affected input, remove the untrusted document, or route the interaction for additional handling. This control is distinct from evaluating whether a completed response is factually supported.\nWhy the other options are incorrect:\nA. Groundedness detection evaluates whether a generated response is supported by supplied source material. It is applied to model output rather than detecting instructions intended to hijack the model. A response could be grounded in a malicious retrieved instruction and still be unsafe. Groundedness detection therefore does not satisfy TR1.\nC. Protected material detection scans generated text or code for content that matches recognised protected material. Typical examples include known articles, song lyrics, recipes, and source code. It addresses intellectual-property risks rather than prompt injection. It would not identify an instruction hidden in a supplier bulletin.\nD. A custom blocklist detects explicitly configured terms or phrases. It can support organisation-specific moderation rules, but an attacker can express equivalent instructions without using a listed phrase. A blocklist does not analyse the structure and intent of prompt attacks. It is therefore insufficient as the primary control required by BR1.\nPrompt Shields quickstart\nShield Prompt REST API", "topic": "Plan and secure", "source": 42}, {"id": "542382", "stem": "You need to map each text analysis requirement to the best capability.\nMatch the following:\nDetect positive, neutral, or negative customer attitude\nClassify messages as angry, urgent, polite, or confused\nIdentify personal data such as phone numbers\nDetect harmful text categories and severity\nChoices:", "options": ["Sentiment analysis LLM tone classifier PII detection Content Safety text analysis", "PII detection Content Safety text analysis Sentiment analysis LLM tone classifier", "Content Safety text analysis PII detection LLM tone classifier Sentiment analysis", "LLM tone classifier Sentiment analysis Content Safety text analysis PII detection"], "answer": 0, "explanation": "Sentiment analysis is the best match for detecting positive, neutral, or negative attitude in text. A custom LLM-based tone classifier is appropriate when the business requires tone labels such as angry, urgent, polite, or confused, especially if those labels are part of a custom routing policy.\nPII detection is the right capability for identifying sensitive personal data such as phone numbers, email addresses, and other personal identifiers. Content Safety text analysis is the right capability for detecting harmful content categories and severity levels.\nWhy the other options are incorrect:\n• B. This mapping puts PII detection on customer attitude, which is incorrect because PII detection finds personal data rather than emotional polarity. It also maps Content Safety to tone classification, but safety categories are not the same as business tone labels. Sentiment analysis does not identify phone numbers or other personal identifiers. The final mapping also assigns the tone classifier to harmful content detection, which is not its primary purpose.\n• C. This mapping starts by assigning Content Safety to sentiment detection. Harm categories and severity do not replace sentiment polarity. It then maps PII detection to tone classification, which would not identify whether a user sounds angry or urgent. The remaining mappings also confuse tone classification with sensitive data and sentiment detection with harm analysis.\n• D. This mapping incorrectly uses an LLM tone classifier for basic sentiment polarity. A tone classifier may support custom labels, but sentiment analysis is the purpose-built capability for positive, neutral, and negative sentiment. Content Safety text analysis is also not used to identify phone numbers as sensitive personal data. PII detection is misplaced because it detects sensitive information, not harmful content categories.\nAzure AI Language PII detection\nAzure AI Content Safety harm categories", "topic": "Plan and secure", "source": 43}, {"id": "542316", "stem": "An organization already uses an Azure OpenAI content filter with approved thresholds for hate, sexual, violence, and self-harm categories.\nLegal now requires an additional policy that must:\nblock 40 unreleased internal project codenames\nallow exact-match or pattern-based organization-specific terms\nleave the existing harm-category thresholds unchanged\nbe manageable separately from the system prompt\nWhich solution should you implement?", "options": ["Enable protected-material detection and add the codenames as copyrighted terms", "Enable Prompt Shields for indirect attacks and classify the codenames as adversarial instructions", "Lower all four standard harm-category thresholds and instruct the model not to repeat internal names", "Create a custom blocklist containing the codenames and attach it to the deployment's content-filter configuration"], "answer": 3, "explanation": "Microsoft custom blocklists are designed for use-case-specific terms such as internal project names, competitor names, or other domain-sensitive content. They support custom terms and patterns and are then associated with the applicable content filtering configuration. This lets the organization introduce a separate lexical policy without altering the standard harm thresholds.\nWhy the other options are incorrect\nA. Protected-material controls address a different responsible-AI problem involving protected text or code rather than arbitrary company-defined terminology. An internal codename is not necessarily protected material simply because the organization considers it confidential. This approach would also fail to give administrators the explicit organization-controlled list management required in the scenario. It therefore applies a legitimate safety control to the wrong risk category.\nB. Prompt Shields are designed to identify adversarial attempts to manipulate model behaviour, including direct and indirect prompt attacks. Merely mentioning a prohibited internal codename does not make the input an adversarial instruction. Treating every codename as prompt injection would conflate application-specific terminology policy with attack detection. The requirement is better represented by deterministic custom blocked terms than by adversarial-prompt classification.\nC. Lowering standard harm thresholds would make the existing hate, sexual, violence, and self-harm moderation more restrictive across unrelated content. Those categories do not represent the business-specific requirement to suppress internal project names. A system instruction may discourage the model from repeating a term, but it is not the same control as a configurable filtering list. This option changes unrelated safety behaviour while still providing a weaker mechanism for the actual policy.\nContent filtering for Microsoft Foundry Models", "topic": "Plan and secure", "source": 42}, {"id": "542340", "stem": "An engineering team is designing audit controls for an agentic contract-review solution.\nMatch each audit need to the best responsible AI implementation component.\nMatch the following:\nCapture tool-call timing and inputs\nPreserve retrieved document IDs\nPause risky actions for review\nIdentify grounding sources later\nChoices:", "options": ["Approval workflow Trace logging Provenance metadata Trace logging", "Provenance metadata Approval workflow Trace logging Approval workflow", "Trace logging Azure Key Vault Approval workflow Content Safety filter", "Trace logging Provenance metadata Approval workflow Provenance metadata"], "answer": 3, "explanation": "Trace logging is the correct component for capturing runtime execution details such as tool-call timing, inputs, outputs, retries, and latency. Provenance metadata is the correct component for preserving which documents, chunks, indexes, or source versions influenced the response.\nApproval workflows are the correct control when a risky or high-impact action must pause until a human or business process approves it. Together, these three controls create a practical audit chain: what happened, what evidence was used, and who approved sensitive execution.\nWhy the other options are incorrect:\n• A. This choice incorrectly maps tool-call timing to an approval workflow. Approval workflows can record decisions, but they do not replace runtime trace logging. It also maps retrieved document IDs to trace logging instead of provenance metadata. The result would blur execution telemetry and source lineage, which weakens audit review.\n• B. This choice treats provenance metadata as if it captures tool execution. Provenance metadata explains source lineage, not the sequence and timing of agent actions. It also maps risky-action review to trace logging, which records activity but does not enforce a pause for approval. The mappings confuse evidence capture with workflow control.\n• C. This choice correctly maps trace logging and approval workflow in two places, but it uses Azure Key Vault for retrieved document IDs. Key Vault is for secrets, keys, and certificates, not source lineage for generated answers. Content Safety filters help detect harmful content, but they do not identify grounding sources later. This makes the mapping incomplete for auditability.\nBuild a workflow in Microsoft Foundry\nMicrosoft Agent Framework Workflows – Human-in-the-loop", "topic": "Plan and secure", "source": 43}, {"id": "542012", "stem": "A healthcare software company is building a clinician copilot in Foundry. The application will run in several EU countries and must satisfy these requirements:\nPrompts and responses must stay within the EU data zone\nTraffic is consistently high during business hours\nThe application must have low latency variance\nThe team does not require single-region-only processing\nThe deployment must be suitable for a production workload\nWhich deployment option should you choose?", "options": ["Data Zone Standard", "Standard", "Single-region Regional Provisioned deployment", "Data Zone Provisioned"], "answer": 3, "explanation": "Data Zone Provisioned is the best answer because it combines data-zone processing with reserved capacity for predictable throughput. Microsoft’s deployment guidance explicitly positions Data Zone Provisioned for workloads that need both data zone compliance and high, predictable throughput, which matches the EU processing requirement and the low-latency-variance requirement in this scenario.\nRegional Provisioned would provide reserved throughput, but it is the wrong boundary because the requirement is EU data zone processing rather than single-region-only processing. Data Zone Standard satisfies the EU boundary but remains best-effort pay-per-token, so it is less suitable when the business explicitly needs consistent high-volume performance with lower latency variance.\nWhy the other options are incorrect:\n• A. Data Zone Standard. Data Zone Standard correctly keeps inferencing within the EU data zone, so it is a plausible distractor. However, Microsoft describes Standard types as best-effort and notes that customers with high consistent volume can experience greater latency variability. Because the scenario requires low latency variance in a high-volume production workload, the provisioned variant is the better fit.\n• B. Standard. Standard is a single-region pay-per-token deployment and does not provide the EU-wide data zone routing model requested here. It is also better aligned to low-to-medium volume or burstier regional workloads rather than a consistently heavy production pattern. This option fails both the compliance-shape requirement and the performance-shape requirement.\n• C. Single-region Regional Provisioned deployment. Regional Provisioned does provide reserved throughput and lower latency variance, so it partly fits the performance requirement. But the scenario explicitly says the team does not require single-region-only processing and instead needs EU data zone processing, which is a different deployment boundary. Data Zone Provisioned is the closer and more complete match because it preserves the zone-level compliance model while still giving provisioned capacity.\nBaseline Microsoft Foundry Chat Reference Architecture\nFeature availability across cloud regions", "topic": "Plan and secure", "source": 37}, {"id": "542270", "stem": "A claims-processing team uses a generative AI app to summarize internal claim notes. The summaries must be concise, avoid unsupported assumptions, and respond with “insufficient information” when the notes do not contain enough detail.\nCurrent behavior:\n• The model sometimes invents missing claim details.\n• The output wording varies significantly across retries.\n• The app already retrieves the correct claim notes.\nWhich change best optimizes the generation behavior?", "options": ["Increase max_tokens and top_p", "Add Content Safety filter", "Lower temperature; strengthen instructions", "Raise temperature and expand retrieved context"], "answer": 2, "explanation": "Lowering temperature and strengthening the prompt instructions best address the stated behavior. The issue is not that the model lacks the correct retrieved notes; the problem is that the generation behavior is too variable and not sufficiently constrained when information is missing. A stronger system prompt can define the expected format, uncertainty behavior, and grounding rules, while a lower temperature reduces response variability.\nThis question tests the difference between retrieval quality and generation control. Since the app already retrieves the right claim notes, the best next optimization is to tune how the model uses that context. Prompt engineering and model parameters are the appropriate controls for concise, grounded, repeatable output.\nWhy the other options are incorrect:\n• A. Increase max_tokens and top_p would likely make the behavior worse. A higher top_p can allow broader token sampling, which may increase variation. Increasing max_tokens allows longer responses but does not improve grounding discipline. This option adjusts generation settings, but not in a way that matches the stated goal.\n• B. Add Content Safety filter is useful for detecting or blocking harmful content. It does not directly instruct the model to say “insufficient information” when claim notes lack evidence. It also does not reduce ordinary wording variation across retries. This is a plausible responsible AI control, but it does not solve the generation-tuning problem described.\n• D. Raise temperature and expand retrieved context conflicts with the consistency requirement. Higher temperature generally increases randomness and can make summaries less repeatable. Expanding retrieved context may help when relevant evidence is missing, but the scenario states the correct notes are already retrieved. The issue is how generation behaves, not whether retrieval finds the right content.\nPrompt engineering techniques\nHow to use structured outputs with Azure OpenAI", "topic": "Plan and secure", "source": 41}, {"id": "542037", "stem": "Match each scenario to the most appropriate integration method.\nMatch the following:\nA public OpenAPI weather service requires no credentials.\nAn Azure service accepts Microsoft Entra tokens and uses RBAC.\nA partner API uses x-api-key stored in a Foundry project connection.\nAn agent must ground answers on the current public web.\nChoices:", "options": ["File Search Managed identity OpenAPI Project connection OpenAPI SharePoint connection", "Anonymous OpenAPI Project connection OpenAPI Managed identity OpenAPI Grounding with Bing Search", "Anonymous OpenAPI Managed identity OpenAPI Project connection OpenAPI Grounding with Bing Search", "Anonymous OpenAPI Managed identity OpenAPI Grounding with Bing Search Project connection OpenAPI"], "answer": 2, "explanation": "Choice C is the strongest mapping. Microsoft documents anonymous authentication for public OpenAPI services with no credentials, managed identity for Azure services and Entra-protected APIs that accept Entra tokens, project-connection auth for API key or bearer-token OpenAPI integrations, and Grounding with Bing Search for real-time public web grounding.\nThis mapping also reflects how Foundry separates built-in tool authentication from external-connector scenarios. Built-in tools such as File Search authenticate automatically through Foundry Agent Service, while tools that access external data sources or external APIs rely on the auth method or connection pattern that matches the target system.\nWhy the other options are incorrect:\n• A. This choice incorrectly maps scenario 1 to File Search and scenario 4 to SharePoint. File Search is a built-in knowledge tool, not an anonymous OpenAPI integration for a public weather API. SharePoint is an enterprise content connector, not the connector for live public web grounding.\n• B. This choice swaps scenarios 2 and 3. Microsoft says managed identity is for Azure services or Entra-protected APIs that accept Entra tokens, while API-key-based third-party integrations should use a project connection. Reversing those two auth methods would misconfigure both integrations.\n• D. This choice incorrectly assigns Grounding with Bing Search to the partner API that uses x-api-key, and it assigns project-connection auth to the public web grounding scenario. Grounding with Bing Search is a specific web-grounding connector, not a general authentication method for a custom partner API. Project-connection OpenAPI auth is appropriate for the partner API, but not for replacing Bing web grounding.\nConnect OpenAPI tools to Microsoft Foundry agents\nUse Grounding with Bing Search tools with the agents API", "topic": "Plan and secure", "source": 37}, {"id": "542234", "stem": "A Foundry agent calls Azure AI Search through an OpenAPI tool using managed identity authentication.\nThe following have been verified:\nthe OpenAPI operation contains a valid operationId\nnetwork connectivity succeeds\nthe managed identity has the required Search data-plane role\nthe Search endpoint is correct\nthe target service returns 401 Unauthorized\ndecoding the token shows that its audience is the Foundry project instead of Azure AI Search\nWhich audience should be configured for the OpenAPI tool?", "options": ["https://ai.azure.com", "https://search.azure.com", "https://management.azure.com", "The individual Search service hostname"], "answer": 1, "explanation": "For managed-identity OpenAPI authentication, the audience must identify the downstream API that receives the token. Microsoft explicitly lists the Azure AI Search audience as\nhttps://search.azure.com\nand identifies an audience mismatch as a cause of 401 Unauthorized even when RBAC is otherwise configured correctly.\nExample configuration:\n{\n“auth”: {\n“type”: “managed_identity”,\n“security_scheme”: {\n“audience”: “https://search.azure.com”\n}\n}\n}\nWhy the other options are incorrect\nA.\nhttps://ai.azure.com\nis the Foundry data-plane audience, not the Azure AI Search audience.\nC.\nhttps://management.azure.com\nis used for Azure Resource Manager operations.\nD. The Search service hostname identifies the network endpoint but is not the documented Entra resource identifier for Azure AI Search.\nAzure AI Search role-based access\nAgent identity concepts", "topic": "Plan and secure", "source": 41}, {"id": "542224", "stem": "Refer to:\nhttps://docs.google.com/document/d/10TawY6TIMYV5-pBr-XCeG5E7HBS-1NenFkfXFIct3PM/edit-usp=sharing\nRed Hat Industries must map each lifecycle requirement to the correct Foundry or Azure monitoring capability.\nMatch the following:\nRequirements:\nSelect the deployed model endpoint\nCompare answer quality before release\nDebug prompt and tool execution\nReview token usage and latency\nChoices:", "options": ["Azure Monitor Foundry tracing Model deployment Foundry evaluations", "Foundry evaluations Azure Monitor Model deployment Foundry tracing", "Model deployment Foundry evaluations Foundry tracing Azure Monitor", "Foundry tracing Model deployment Azure Monitor Foundry evaluations"], "answer": 2, "explanation": "Model deployment is the correct match for selecting the deployed model endpoint used by the application. Foundry evaluations are used to compare answer quality, safety, groundedness, and other quality signals before or during release.\nFoundry tracing helps debug prompt execution, tool calls, and application behavior across a generative AI workflow. Azure Monitor is the correct operational monitoring destination for telemetry such as latency, token usage, errors, and runtime performance signals.\nWhy the other options are incorrect:\n• A. This mapping incorrectly assigns Azure Monitor to model endpoint selection. Azure Monitor can collect and analyze telemetry, but it does not choose the deployed model endpoint. It also maps tracing to quality comparison, which confuses debugging execution flow with evaluation. The correct capabilities are present, but they are assigned to the wrong lifecycle responsibilities.\n• B. This mapping incorrectly uses Foundry evaluations for selecting the deployed endpoint. Evaluations assess quality and safety, but they do not represent the deployment endpoint itself. Azure Monitor is also mapped to pre-release answer comparison, which is not its primary purpose in this scenario. The sequence shows common confusion between evaluation and monitoring.\n• D. This mapping assigns tracing to endpoint selection and model deployment to answer quality comparison. Tracing helps debug execution details, but it is not the model deployment target. Azure Monitor reviews operational telemetry, but it does not directly debug prompt and tool execution like tracing. Foundry evaluations are also incorrectly mapped to token usage and latency.\nObservability in Microsoft Foundry\nSet up tracing in Microsoft Foundry", "topic": "Plan and secure", "source": 41}, {"id": "542142", "stem": "A SaaS assistant receives a mixture of:\nsimple classification prompts\nshort summarization requests\ncomplex reasoning tasks\ncoding questions\nmultilingual prompts\nThe team wants to meet these requirements:\nexpose one deployment endpoint to the application\nuse less-expensive models when they can satisfy the request\nroute difficult requests to more capable models\navoid implementing model-selection logic in application code\nreduce latency and cost without materially reducing answer quality\nWhich deployment approach should the team use?", "options": ["Global Standard deployment", "Provisioned throughput deployment", "Model router deployment", "Global Batch deployment"], "answer": 2, "explanation": "Model router is specifically designed to analyze each prompt at runtime and route it to an appropriate underlying model based on characteristics such as complexity, task type, and reasoning requirements. The application calls a single model-router deployment rather than implementing its own routing layer. Microsoft positions it as a way to balance quality, latency, and cost while maintaining one deployment interface.\nWhy the other options are incorrect:\nA. Global Standard deployment provides flexible pay-as-you-go model inference but doesn’t dynamically select different underlying models for each request. The application would still need its own routing logic if it wanted easy and difficult prompts to use different models.\nB. Provisioned throughput deployment reserves predictable inference capacity. It can improve throughput predictability, but it doesn’t solve the requirement to dynamically choose among models based on prompt difficulty.\nD. Global Batch deployment is intended for asynchronous high-volume processing. It isn’t appropriate for an interactive assistant that needs request-by-request model selection.", "topic": "Plan and secure", "source": 39}, {"id": "542447", "stem": "Refer to:\nhttps://docs.google.com/document/d/1ENASvCHfdLcmLCbNaDDClGWnxkItxJw2OQHw6EpbP9M/edit-usp=sharing\nContoso must map each operational requirement to the correct Azure AI component or monitoring capability.\nMatch the following:\nRequirements:\nGround answers with approved policy content\nDetect harmful generated content\nTranslate customer text interactions\nReview token usage and latency\nChoices:", "options": ["Azure Blob Storage Azure AI Translator Azure AI Search Azure Key Vault", "Azure AI Document Intelligence Azure Monitor Azure AI Content Safety Azure AI Translator", "Azure AI Translator Azure AI Search Azure Monitor Azure AI Document Intelligence", "Azure AI Search Azure AI Content Safety Azure AI Translator Azure Monitor"], "answer": 3, "explanation": "Azure AI Search is the correct component for grounding responses with approved policy content because it indexes and retrieves enterprise documents. Azure AI Content Safety is the appropriate service family for detecting harmful or unsafe content in user-generated or AI-generated text.\nAzure AI Translator supports text translation for multilingual customer interactions. Azure Monitor is the correct destination for reviewing operational telemetry such as latency, token usage, traces, and related runtime signals when integrated with the application and AI workload.\nWhy the other options are incorrect:\n• A. This mapping incorrectly uses Azure Blob Storage as the grounding component. Blob Storage can store the source documents, but it does not provide the retrieval and ranking layer needed for grounded answers. It also maps translation and search responsibilities to the wrong requirements. Azure Key Vault stores secrets and keys, but it is not used to review token usage or latency.\n• B. This mapping incorrectly assigns Document Intelligence to grounded policy answering. Document Intelligence extracts fields and structure from documents, but it is not the retrieval layer for live grounded responses. It also assigns Azure Monitor to harmful content detection, which confuses monitoring with safety filtering. The translation and content safety entries are present, but they are mapped to the wrong requirements.\n• C. This mapping reverses several responsibilities. Azure AI Translator does not ground answers against approved enterprise documents. Azure AI Search retrieves relevant content, but it is not the harmful content detection control. Document Intelligence is useful for extraction from forms, but it does not review token usage or latency.\nAzure AI Content Safety overview\nObservability in Microsoft Foundry", "topic": "Plan and secure", "source": 44}, {"id": "542051", "stem": "A company is operating a customer-support copilot built with Foundry and Azure OpenAI.\nUsers report that responses are “slow sometimes,” and the compliance team wants evidence of blocked or harmful-output trends.\nThe operations team must be able to:\nreconstruct multi-step executions across LLM and tool calls\nanalyze prompt and completion token consumption over time\ndistinguish first-response delay from generation speed and total completion time\nmonitor harmful or blocked-request trends\nquery telemetry centrally and build dashboards\nWhich observability design is the best fit?", "options": ["Weekly offline evaluation reports", "Application Insights tracing plus Azure OpenAI metrics and safety metrics", "Azure AI Search analytics plus workbook screenshots", "Request counts, error rates, screenshots, manual transcript review, and monthly audits"], "answer": 1, "explanation": "B is the best fit because it combines the two Microsoft-native observability layers this scenario needs. Foundry observability integrates tracing with Azure Monitor Application Insights for execution visibility, while Azure OpenAI monitoring provides token, latency, request, and safety-related metrics such as Time to Response, Time to Last Byte, Blocked Volume, Harmful Volume Detected, and token usage metrics.\nIt also supports central analysis workflows. Microsoft documents diagnostic settings and Log Analytics for querying logs and metrics with KQL, and Foundry’s broader observability model explicitly calls out real-time dashboards for token consumption, latency, error rates, quality scores, and alerts on harmful outputs or threshold failures.\nWhy the other options are incorrect:\nA. Weekly offline evaluation reports. Offline evaluations are useful, but they do not replace runtime observability. The requirement includes traces, token analytics, latency breakdowns, and safety trend monitoring in production, which Microsoft treats as a monitoring and tracing problem, not just an evaluation problem. Weekly reports would also be too delayed for active troubleshooting of intermittent performance issues.\nC. Azure AI Search analytics plus workbook screenshots. Azure AI Search analytics can help with search-specific behavior, but the scenario is broader than retrieval and explicitly asks for LLM-tool execution flow, token usage, safety signals, and latency decomposition. Screenshots are not an observability pipeline, and they do not create queriable telemetry. This option misses the core Azure Monitor and Foundry tracing capabilities documented for generative AI operations.\nD. Request counts, error rates, screenshots, manual transcript review, and monthly audits. Request counts and error rates are helpful, but they are not enough to explain token economics, first-byte responsiveness, token generation speed, or blocked-content trends. Manual review and monthly audits are also too coarse for near-real-time debugging and operational tuning. Microsoft’s observability guidance emphasizes integrated metrics, traces, and alerts rather than relying on sparse aggregate counts and manual inspection.\nAzure OpenAI monitoring data reference\nMonitor Azure OpenAI in Microsoft Foundry Models", "topic": "Plan and secure", "source": 38}, {"id": "542064", "stem": "Refer to:\nhttps://docs.google.com/document/d/1wSTDGPPYkobjsp-NYn4OyjyuT_nnw1iF7VBmLnWAZYE/edit-usp=sharing\nAfter production deployment, end-to-end 95th-percentile latency increases from 3.2 seconds to 7.1 seconds. Operations staff must determine whether the delay occurs during search retrieval, model generation, or the claims API call.\nThe monitoring solution must retain durations, token usage, exceptions, dependency outcomes, and correlation identifiers. It must not retain message content, retrieved passages, claim identifiers, or tool arguments.\nWhich configuration should you use?", "options": ["Foundry tracing with production content capture", "Application Insights request logging without agent spans", "OpenTelemetry tracing with content recording disabled", "Azure Activity Log with diagnostic settings"], "answer": 2, "explanation": "Microsoft Foundry tracing uses OpenTelemetry and Application Insights to capture agent execution spans. These spans can expose the duration and outcome of retrieval, model, and tool operations, allowing operators to isolate which dependency causes the latency regression. Tracing also supports operational information such as exceptions, token consumption, timestamps, and correlated execution steps.\nContent recording must remain disabled in production. With message-content capture disabled, the solution can retain execution metadata without intentionally recording prompts, responses, and tool arguments. Aurelia Mutual should also avoid adding claim identifiers to custom span attributes, apply suitable sampling and retention policies, and use a de-identified test dataset for detailed quality evaluations.\nWhy the other options are incorrect:\nA. Production content capture can record user messages, model outputs, retrieved material, and tool-call arguments. These fields could contain claim identifiers and other customer information prohibited by C4. Although full content is useful during controlled development, it creates an unacceptable production telemetry risk here. The organisation needs execution metadata rather than complete message payloads.\nB. Standard Application Insights request logging can show the duration of the outer application request, but it does not automatically provide the complete internal agent span hierarchy. Operations staff would struggle to distinguish search latency from model latency or claims API latency. Additional manual instrumentation would effectively recreate the OpenTelemetry tracing design. This option therefore does not satisfy the diagnostic requirement with the least operational effort.\nD. Azure Activity Log records subscription-level control-plane events such as resource creation, deletion, and configuration changes. It is not intended to trace individual agent executions or measure model, retrieval, and tool-call durations. Diagnostic settings can route supported logs and metrics, but they do not turn Activity Log into an agent tracing system. This option cannot provide the required request-level dependency correlation.\nMicrosoft Foundry tracing and data handling\nConfigure tracing for AI agent frameworks", "topic": "Plan and secure", "source": 38}, {"id": "542395", "stem": "import os\nfrom openai import AzureOpenAI\nclient = AzureOpenAI(\nazure_endpoint=os.environ[“AZURE_OPENAI_ENDPOINT”],\napi_key=os.environ[“AZURE_OPENAI_API_KEY”],\napi_version=”2024-10-21″\n)\nresponse = client.chat.completions.create(\nmodel=(MISSING CONFIG),\nmessages=[\n{“role”: “system”, “content”: “Answer using approved policy content.”},\n{“role”: “user”, “content”: “Summarize the retention policy.”}\n],\ntemperature=0.2,\nmax_tokens=500\n)\nprint(response.choices[0].message.content)\nWhich value should replace (MISSING CONFIG)?", "options": ["Model family", "Account endpoint hostname", "Deployment name", "Regional quota metric"], "answer": 2, "explanation": "For Azure OpenAI calls through a deployment, the model value in the request should reference the deployment name configured in the resource, such as prod-gpt-4o-eastus. The deployment name is the application-facing identifier that routes the request to the deployed model capacity.\nQuota and TPM are associated with deployments, regions, subscriptions, and model types. The endpoint identifies the Azure OpenAI resource, but the deployment name identifies the deployed model target within that resource. Using the base model family name instead of the deployment name is a common cause of failed or misrouted requests.\nWhy the other options are incorrect:\n• A. The model family describes the underlying model capability, but it is not the configured deployment identifier used by the application request. A team might deploy the same model family multiple times with different names, quotas, or environments. The application must target the deployment that has been created and assigned capacity. Using the family name can fail if no deployment with that exact name exists.\n• B. The account endpoint hostname belongs in the client configuration, not in the per-request model field. The snippet already uses azure_endpoint when creating the client. Repeating the endpoint as the model value would not select a deployed model. This option confuses service location with deployment routing.\n• D. A regional quota metric such as TPM describes capacity and rate limits, not the deployment identifier. TPM helps determine throughput and throttling behavior, but it is not passed as the model value in the completion request. The application cannot route a request by specifying a quota metric. Capacity planning and request routing are related but separate concerns.\nManage and increase quotas for resources\nWork with Azure OpenAI models in Microsoft Foundry", "topic": "Plan and secure", "source": 43}, {"id": "542313", "stem": "A customer-service application sends approximately 6,000 tokens of shared policy instructions and examples with every request.\nRequests are currently constructed in this order:\ntenant-specific metadata\nuser-specific preferences\nshared policy instructions\nshared few-shot examples\nuser message\nThe deployed model supports Azure OpenAI prompt caching. However, monitoring shows that cached-token utilization is much lower than expected even though the policy instructions and examples are identical across most requests.\nThe team must improve cache utilization without changing the intended model behaviour or introducing an application-managed semantic cache.\nWhich change should you make?", "options": ["Generate a consistent prompt_cache_key from the shared policy content but leave the current message order unchanged", "Move the shared policy and examples before tenant-specific content and use a stable cache key for requests sharing that prefix", "Split the shared policy into several system messages while keeping tenant metadata at the beginning of the messages array", "Move the shared policy after the user message so that only the user-specific portion is evaluated before cache lookup"], "answer": 1, "explanation": "Azure OpenAI prompt caching works by matching identical content at the beginning of the prompt. Microsoft specifically recommends placing stable, reusable content first and dynamic content later, and it also recommends a consistent prompt_cache_key for requests sharing a prefix. The existing design breaks prefix reuse because tenant-specific data appears before the otherwise identical 6,000-token block.\nWhy the other options are incorrect\nA. A consistent prompt_cache_key can improve affinity for requests that already share a reusable prefix. It does not make two different prompt prefixes identical when tenant-specific data appears before the shared policy. Leaving the dynamic content first therefore preserves the main cause of the low cache-hit rate. This approach becomes useful after the reusable prefix itself has been stabilized.\nC. Splitting shared content into several system messages does not remove the requirement for repeated content to occur at the beginning. Tenant metadata would still change the initial token sequence before the reusable policy content is reached. Multiple system messages can be useful for instruction organization, but they do not inherently improve prefix identity. The cache problem therefore remains even though the message structure looks more organized.\nD. Moving the policy after the user message places reusable content even farther from the beginning of the request. Prompt caching does not search the entire prompt for arbitrary repeated blocks and then cache them independently. The model could still receive the same semantic instructions, but the repeated prefix would remain ineffective for caching. This change therefore moves the architecture in the opposite direction from Microsoft’s optimization guidance.\nAzure OpenAI latency guidance", "topic": "Plan and secure", "source": 42}, {"id": "542124", "stem": "A bank is building a compliance extraction service. The parser requires the model to always return these fields: policy_area, risk_score, escalate, and justification.\nProblem: The team needs output that always conforms to the expected field structure.\nProposed solution: In the system message, instruct the model to return JSON and set response_format to { “type”: “json_object” }.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "No is correct because Microsoft documents that JSON mode guarantees valid JSON, but it does not guarantee the output matches a specific schema. This means the model could still omit required fields, add unexpected ones, or vary the shape of the response in ways that break the parser.\nThe proposed solution is close, which is why it is a good exam distractor. The correct platform choice for a fixed field contract is structured outputs with a JSON Schema, not JSON mode plus instructions alone. Microsoft explicitly recommends structured outputs when schema guarantees matter.\nWhy the other options are incorrect:\n• A. Yes. This answer would be correct only if the requirement were limited to producing syntactically valid JSON. The problem is stricter than that because it requires a stable, exact field structure for downstream parsing. Microsoft’s JSON mode guidance makes clear that valid JSON is not the same as guaranteed schema compliance, so answering “Yes” overlooks the core requirement gap.\nHow to use structured outputs with Azure OpenAI in Microsoft Foundry Models\nAzure OpenAI in Microsoft Foundry Models REST API reference", "topic": "Plan and secure", "source": 39}, {"id": "542251", "stem": "A customer-service agent has unpredictable traffic, frequent short spikes, and a strict monthly cost ceiling.\nThe team must reduce spend risk and avoid one client consuming most of the shared quota.\nProblem:\nThe current design sends all clients directly to one standard Azure OpenAI deployment.\nProposed solution:\nMove the workload to provisioned throughput sized at twice the observed peak. Do not add gateway throttling, token limits, or budget monitoring.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "The proposed solution does not meet the goal because it addresses capacity but not cost governance or tenant fairness. Provisioned throughput can help with predictable reserved capacity, but sizing it at twice an unpredictable peak can increase fixed cost exposure instead of reducing spend risk.\nThe design also fails to prevent one client from consuming most of the shared usage. A gateway or API management layer can enforce request or token limits per consumer, while monitoring and budget controls help manage the cost footprint. Without those controls, the workload may still have unfair consumption and poor financial governance.\nWhy the other options are incorrect:\n• A. Yes is incorrect because provisioned throughput alone does not satisfy all stated requirements. It may reduce some throttling if capacity is correctly planned, but it does not enforce tenant-level fairness. It also does not create a monthly cost ceiling by itself. The proposed solution ignores token limits, gateway throttling, and cost monitoring.\nLimit Azure OpenAI API token usage\nPlan and manage costs in Microsoft Foundry", "topic": "Plan and secure", "source": 41}, {"id": "542108", "stem": "A production web app must consume a deployed Foundry chat model without storing API keys in source control.\nThe team wants keyless authentication and RBAC-based access.\nSnippet\nfrom azure.ai.inference import ChatCompletionsClient\nfrom azure.ai.inference.models import SystemMessage, UserMessage\nfrom azure.identity import DefaultAzureCredential\nclient = ChatCompletionsClient(\nendpoint=”https://contoso.services.ai.azure.com/models”,\ncredential=(MISSING CONFIG),\nmodel=”gpt-4o-mini”\n)\nresponse = client.complete(\nmessages=[\nSystemMessage(“You are a concise assistant.”),\nUserMessage(“Summarize the deployment result in one sentence.”)\n],\nmax_tokens=80\n)\nprint(response.choices[0].message.content)\nWhich value should replace (MISSING CONFIG)?", "options": ["AzureKeyCredential(api_key)", "AnonymousCredential()", "ConnectionStringCredential()", "DefaultAzureCredential()"], "answer": 3, "explanation": "DefaultAzureCredential() is correct because the stem explicitly asks for keyless authentication and RBAC-based access in production. Microsoft documents that Foundry supports Microsoft Entra ID and API keys, and it recommends Microsoft Entra ID for production workloads because it enables managed identities, least-privilege RBAC, and better auditing.\nThe snippet also matches Foundry model consumption patterns. Microsoft documents a common inference endpoint for Foundry Models and documents the Python inference client for chat completions. In that context, DefaultAzureCredential() is the correct production authentication object to pair with the client when the team wants keyless access instead of static secrets.\nWhy the other options are incorrect:\n• A. AzureKeyCredential(api_key). This would use an API key, which directly conflicts with the requirement to avoid storing API keys and to use keyless production authentication. Microsoft explicitly states that API keys are appropriate for rapid prototyping, while Entra ID is recommended for production. So this option is functional in some scenarios, but wrong for the stated security goal.\n• B. AnonymousCredential(). Anonymous access is not the model-consumption pattern documented for protected Foundry endpoints. The scenario requires authenticated production access with RBAC. This option fails both the security requirement and the documented authentication model.\n• C. ConnectionStringCredential(). Foundry’s authentication guidance in the cited product documentation discusses Microsoft Entra ID bearer tokens and API keys, not a connection-string credential pattern for this inference client scenario. Even if a different Azure service might use connection strings, that is not the production consumption path this stem describes. This choice is therefore a service-pattern mismatch.\nAuthentication and authorization in Microsoft Foundry\nConfigure keyless authentication with Microsoft Entra ID", "topic": "Plan and secure", "source": 39}, {"id": "542256", "stem": "An organization is releasing an agentic customer-support solution. The release gate requires safety evaluation results, quality evaluator scores, and auditable explanation or trace artifacts for agent decisions.\nProblem:\nThe team must implement responsible AI instrumentation before production approval.\nProposed solution:\nConfigure Azure AI Content Safety as a runtime filter and store a pass/fail flag for each response. Do not run Foundry evaluations, collect evaluator scores, or enable agent tracing.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "The proposed solution does not meet the goal because it addresses only part of the responsible AI requirement. A runtime content safety filter can help detect or block harmful content, but the release gate also requires evaluator scores and auditable explanation or trace artifacts. The proposal explicitly omits Foundry evaluations and agent tracing.\nFor AI-103, this is the difference between a runtime guardrail and a complete instrumentation strategy. Responsible AI instrumentation for generative AI and agentic systems commonly includes evaluations, safety assessments, observability, and artifacts that help teams review behavior. A filter alone is not enough when the requirement asks for measurable evaluation outputs and traceability.\nWhy the other options are incorrect:\n• A. Yes is incorrect because the proposed solution leaves two major requirements unsatisfied. It does not run quality evaluators, so there are no groundedness, relevance, or similar evaluation scores. It also does not enable agent tracing, so the organization lacks auditable visibility into tool calls and agent execution paths. The content safety filter is useful, but it is not a complete responsible AI instrumentation plan.\nBuilt-in Evaluators Reference\nAgent tracing in Microsoft Foundry", "topic": "Plan and secure", "source": 41}, {"id": "542122", "stem": "A team is building a domain extraction flow for internal audit reviews. The response must follow an exact schema containing control_id, severity, owner, and evidence_found.\nSnippet\nfrom openai import OpenAI\nclient = OpenAI()\nresponse = client.chat.completions.create(\nmodel=”gpt-4.1-mini”,\nmessages=[\n{“role”: “system”, “content”: “Extract audit findings from the text.”},\n{“role”: “user”, “content”: audit_text}\n],\nresponse_format={\n“type”: “(MISSING CONFIG)”,\n“json_schema”: {\n“name”: “audit_finding”,\n“strict”: True,\n“schema”: {\n“type”: “object”,\n“properties”: {\n“control_id”: {“type”: “string”},\n“severity”: {“type”: “string”},\n“owner”: {“type”: “string”},\n“evidence_found”: {“type”: “boolean”}\n},\n“required”: [“control_id”, “severity”, “owner”, “evidence_found”]\n}\n}\n}\n)\nWhich value should replace (MISSING CONFIG)?", "options": ["plain text", "XML string", "json_object", "json_schema"], "answer": 3, "explanation": "json_schema is correct because Microsoft’s structured outputs guidance shows response_format set to json_schema with strict: true when you want the model to follow a schema definition. The REST reference also states that setting response_format to { “type”: “json_schema”, “json_schema”: {…} } enables Structured Outputs and guarantees the model matches the supplied JSON schema.\nThat is exactly what the scenario needs: domain extraction with required fields and type validation. The presence of the json_schema block in the snippet is the clue that the response format type must activate schema enforcement rather than plain valid JSON generation.\nWhy the other options are incorrect:\n• A. plain text. Plain text would discard the schema requirement entirely. The downstream workflow expects specific fields and types, so returning unstructured text would force fragile parsing and would not meet the stated requirement. This option ignores the whole purpose of the json_schema block already present in the request.\n• B. XML string. XML is not the response-format type documented here for schema-bound structured outputs in Azure OpenAI. The official guidance for this scenario uses JSON Schema through response_format, not an XML output mode. This distractor sounds structured, but it is not the platform control shown in the docs for this task.\n• C. json_object. json_object enables JSON mode, and Microsoft says JSON mode guarantees valid JSON. However, the docs also say JSON mode does not guarantee the response matches a specific schema. Because this request needs strict fields and types, json_object is not sufficient.\nAzure OpenAI in Microsoft Foundry Models REST API reference\nHow to use JSON mode with Azure OpenAI in Microsoft Foundry Models", "topic": "Plan and secure", "source": 39}]}, {"id": "06-vision-speech", "level": 6, "rank": "Hard", "title": "Scenario lab: vision, speech, and text", "minutes": 65, "cheat": "Cheat sheet domains 3 and 4 — vision, text analysis, and speech", "blurb": "Scenarios on images, video, translation, speech, and visual safety.", "focus": ["Match the control to the modality: image, video, speech, or translation.", "A vision-enabled chat model describes images. Content Understanding extracts structured fields.", "Custom speech and a translation glossary help when the vocabulary is specific to the business.", "Filter unsafe visual content, and watch for instructions hidden inside an image."], "pool": 136, "questions": [{"id": "542033", "stem": "A learning portal needs a short, one-sentence alt attribute for standard product photos.\nWhich Azure Vision feature is the best fit?", "options": ["Dense Captions feature set", "Caption", "Read OCR output", "Smart Crops suggestions"], "answer": 1, "explanation": "The best answer is Caption. Microsoft documents that image captioning generates a one-sentence description of the whole image, and Microsoft’s alt text guidance says those AI-generated captions can be used as alt text. That makes Caption the most direct fit for short alt text on standard photos.\nThis is different from other image-analysis outputs because the goal here is a concise whole-image description, not OCR extraction, cropping, or region-by-region detail. Microsoft describes Dense Captions as more detailed region-level descriptions, while Caption describes the image contents as a whole.\nWhy the other options are incorrect:\nA. Dense Captions feature set. Dense Captions is useful when you need more detail about multiple parts of an image, because Microsoft says it can generate descriptions for up to 10 prominent regions and return bounding boxes. That is helpful for richer image understanding, but it is not the best default for a short, single alt attribute on a standard photo. It tends to solve a more detailed problem than the one in the question.\nC. Read OCR output. OCR is for extracting visible text from an image. Microsoft documents the read feature as reading visible text and outputting structured JSON, which is useful when the image contains text that must be captured, but it does not create a human-friendly image description by itself. OCR output alone is not a substitute for concise alt text describing the image’s meaning.\nD. Smart Crops suggestions. Smart Crops finds crop rectangles that preserve the area of interest. That can improve thumbnail generation or framing, but it does not generate alt text or narrative image descriptions. It changes image composition, not accessibility text.\nImage captions – Image Analysis 4.0\nOverview: Generate image alt text with Image Analysis", "topic": "Vision", "source": 37}, {"id": "542087", "stem": "A design team wants to replace only the sky in an existing product image. The bottle, label, and reflections must remain unchanged.\nWhich control should they apply?", "options": ["Mask", "Output compression", "Stream", "User ID"], "answer": 0, "explanation": "A mask is the correct control because the Azure OpenAI image edit API uses a mask to define exactly which part of the image should be edited. Microsoft documents that the editable area is identified by fully transparent pixels in the mask, which makes mask-based editing the platform control for localized changes rather than whole-image regeneration.\nThis is a better fit than generation or output controls because the requirement is not to change the entire image or alter delivery behavior. It is specifically to constrain edits to one region while preserving the rest of the image, and that is exactly what the mask parameter is designed to do.\nWhy the other options are incorrect:\n• B. Output compression. Output compression affects the generated file’s compression level, not the region that gets edited. It is relevant when tuning image delivery characteristics such as file size or compression, but it does nothing to isolate the sky from the rest of the image. Choosing it would confuse output tuning with edit scoping.\n• C. Stream. Streaming is useful when you want partial images returned during generation for faster visual feedback. It improves perceived latency, but it does not define where edits occur inside an image. This option addresses response behavior, not selective editing.\n• D. User ID. The user parameter is for tracking and monitoring usage patterns. It can help identify who made a request, but it has no effect on the edited region or the visual result. This is operational metadata, not an image editing control.\nAzure OpenAI in Microsoft Foundry Models REST API v1 preview reference\nUse the image generation tool in Foundry Agent Service", "topic": "Vision", "source": 38}, {"id": "542210", "stem": "A team built a voice assistant that speaks every response by calling the batch synthesis API. Users report that the assistant pauses too long before every spoken reply.\nWhat is the best next step?", "options": ["Enable speaker diarization", "Add SSML pauses", "Use real-time synthesis", "Switch to batch transcription"], "answer": 2, "explanation": "The best next step is to use real-time synthesis. Microsoft says real-time text-to-speech is provided through the Speech SDK or REST API, while batch synthesis is intended for long audio files and is handled asynchronously with polling rather than immediate turn-by-turn playback.\nThat means the current latency problem is architectural rather than cosmetic. In an interactive agentic workflow, each response should be synthesized for immediate playback, not submitted as a long-running batch job designed for non-real-time output.\nWhy the other options are incorrect:\n• A. Enable speaker diarization. Diarization is a speech-to-text feature for distinguishing different speakers in audio. It has no role in reducing the delay of text-to-speech output from the assistant. This option confuses an input-transcription capability with an output-synthesis latency problem.\n• B. Add SSML pauses. SSML can control voice output attributes such as pauses, pitch, speaking rate, and pronunciation. But adding pauses would shape the spoken delivery after synthesis starts; it would not solve the delay caused by using an asynchronous batch API for every reply. This would adjust speech style while preserving the same underlying latency issue.\n• D. Switch to batch transcription. Batch transcription is for prerecorded input audio and does not address how agent responses are synthesized to speech. The problem described is on the text-to-speech output side, not on the speech-to-text input side. This option moves the design farther away from a low-latency conversational workflow.\nText to speech quickstart\nWhat is Azure Speech?", "topic": "Text and speech", "source": 40}, {"id": "542304", "stem": "You are building an Azure AI Search indexing pipeline for a RAG solution. The pipeline must extract entities from text and OCR content from embedded images during indexing.\nWhich component should you configure?", "options": ["Azure Blob lifecycle policy", "Azure AI Search skillset", "Azure SQL full-text indexer", "Azure Monitor diagnostic settings"], "answer": 1, "explanation": "An Azure AI Search skillset is the correct component because skillsets define enrichment steps that run during indexing. Built-in skills can extract entities, key phrases, language, OCR text, image information, and layout-aware content depending on the pipeline design.\nThis is a core retrieval and grounding design concept. Raw storage holds the source files, but the skillset transforms the content into enriched fields that can be indexed and later retrieved for grounding generative AI responses.\nWhy the other options are incorrect:\n• A. Azure Blob lifecycle policy manages storage tiering and retention for blob data. It can help control storage costs and data lifecycle behavior. However, it does not extract text, images, entities, or layout information. It is related to source data management, not enrichment during indexing.\n• C. Azure SQL full-text indexer can support text search scenarios over relational data. It is not the Azure AI Search enrichment mechanism that applies built-in or custom AI skills. It also does not handle OCR, image enrichment, or layout-aware document processing in an Azure AI Search skillset. This distractor is plausible because it mentions indexing, but it targets a different search capability.\n• D. Azure Monitor diagnostic settings are used to collect logs and metrics from Azure resources. They help with observability and operational troubleshooting. They do not perform content enrichment or add extracted fields to a search index. Monitoring can show whether an indexer failed, but it is not the enrichment component itself.\nSkills reference for Azure AI Search\nAI enrichment in Azure AI Search", "topic": "Vision", "source": 42}, {"id": "542013", "stem": "A team uses a vision-enabled chat model in Foundry to generate extended descriptions for charts. The results are verbose but often miss the purpose of the chart and include irrelevant visual trivia.\nWhat should they change first?", "options": ["Increase max tokens", "Use task-oriented prompts", "Add smart crops", "Switch to OCR only"], "answer": 1, "explanation": "The best first change is to use task-oriented prompts. Microsoft’s vision prompt-engineering guidance says contextual specificity and task-oriented prompts improve output quality by focusing the model on the relevant aspects of the image and avoiding extraneous detail. Microsoft also recommends asking the model to describe the image in detail first before completing the specific task when you need better structured results.\nThat directly matches the problem in the scenario: the output is not focused enough for accessibility-oriented extended descriptions. Vision-enabled chat models can analyze images and produce textual responses, but prompt quality strongly affects whether the output emphasizes the chart’s purpose and communicative meaning rather than incidental detail.\nWhy the other options are incorrect:\nA. Increase max tokens. Increasing the token limit can reduce truncation, but Microsoft’s guidance here is about improving relevance and specificity, not just allowing longer output. A longer answer can still be off-target if the prompt is vague. This option treats a focus problem as a length problem.\nC. Add smart crops. Smart crops can help preserve the area of interest visually, but they do not tell the model what kind of description to generate or what accessibility outcome to optimize for. The problem described is semantic focus, not image framing. Cropping is the wrong first lever.\nD. Switch to OCR only. OCR is useful when text embedded in the chart must be extracted, but Microsoft documents vision-enabled chat models as capable of analyzing images and providing textual responses about them. OCR alone would miss non-textual relationships, trends, and purpose, which are often exactly what extended chart descriptions need to communicate.\nImage prompt engineering techniques\nGraphics, Design, and Media", "topic": "Vision", "source": 37}, {"id": "542049", "stem": "A social platform needs to screen user-uploaded images before they are published.\nThe team must classify harmful visual content into built-in safety categories and use the results in its moderation workflow.\nWhich service is the best fit?", "options": ["Azure AI Vision Image Analysis service", "Azure AI Content Safety", "Azure AI Search", "Custom Vision classifier"], "answer": 1, "explanation": "Azure AI Content Safety is the correct service because Microsoft documents it as the service that detects harmful user-generated and AI-generated content, and it includes image APIs for harmful-material detection across modalities. Microsoft also documents four built-in harm categories that apply to image moderation: hate, self-harm, sexual, and violence.\nThat makes it the strongest fit when the requirement is specifically to classify unsafe or disallowed visual content rather than to do generic image understanding. The service is purpose-built for moderation workflows, and Microsoft’s image quickstart is explicitly about image moderation with category and severity output.\nWhy the other options are incorrect:\nA. Azure AI Vision Image Analysis service. This is a plausible distractor because it is image-related, but the stem is specifically about unsafe-content classification and moderation. Microsoft’s moderation documentation points to Azure AI Content Safety image APIs for harmful-content detection and filtering, not to general image-analysis capabilities. For this scenario, choosing a general vision service would miss the built-in moderation categories and severity-based filter flow the question is asking about.\nC. Azure AI Search. Azure AI Search is a retrieval and indexing service, not the moderation service Microsoft documents for harmful-image classification. The question is not about finding or ranking content in an index; it is about deciding whether an uploaded image is unsafe or disallowed. Using Search here would solve a different problem than the one in the stem.\nD. Custom Vision classifier. A custom classifier can sound attractive because it can label images, but Microsoft’s moderation documentation already provides a dedicated service for harmful-content detection with built-in categories and severity ratings. The stem asks for unsafe/disallowed visual-content filtering, which aligns directly to Azure AI Content Safety rather than to building a separate generic classifier first. That makes Custom Vision a less direct and less exam-authentic fit for this requirement.\nHarm categories in Azure AI Content Safety\nQuickstart: Analyze image content", "topic": "Vision", "source": 38}, {"id": "542178", "stem": "A media workflow must process documents, images, audio, and video.\nThe solution must extract structured JSON that matches a defined schema and should support complex field generation for downstream automation.\nWhich component should be included?", "options": ["Azure AI Search multimodal index", "GPT-4o deployment", "Azure Content Understanding analyzer", "OCR endpoint"], "answer": 2, "explanation": "Azure Content Understanding is the best fit because Microsoft describes it as a Foundry tool that uses generative AI to process documents, images, video, and audio into a user-defined output format. Microsoft also says the final result can be returned as structured JSON matching your defined schema for automation and analytics workflows. That matches this requirement almost exactly.\nMicrosoft also says analyzers are the core building blocks of Content Understanding and combine content extraction, AI-powered analysis, and structured data output in a reusable configuration. That makes an analyzer the right component when the workflow needs schema-driven extraction rather than just a one-off multimodal answer.\nWhy the other options are incorrect:\n• A. Azure AI Search multimodal index. Azure AI Search is excellent for multimodal ingestion and retrieval, especially in RAG scenarios. But this question is about producing schema-defined structured JSON for downstream automation, which Microsoft assigns to Content Understanding and its analyzers rather than to the search index itself. Search is retrieval-centric, not the primary extraction component here.\n• B. GPT-4o deployment. A multimodal chat model can analyze images and answer questions, so this option sounds reasonable. However, Microsoft’s Content Understanding documentation specifically covers user-defined output formats, structured JSON, and analyzer-based extraction. A plain model deployment does not provide that full schema-governed extraction framework by itself.\n• D. OCR endpoint. OCR is useful for reading text from visual content. But the requirement spans documents, images, audio, and video and calls for structured JSON aligned to a defined schema. Microsoft’s Content Understanding documentation clearly goes beyond OCR and supports multimodal processing with structured outputs for automation workflows.\nWhat is a Content Understanding analyzer?\nMultimodal Search Concepts and Guidance", "topic": "Vision", "source": 40}, {"id": "542112", "stem": "A media team stores thousands of marketing images.\nThey want a Foundry Tools analyzer that generates a one-paragraph description for each image so the images can be searched and retrieved later. They do not need a custom schema.\nWhich analyzer should they use?", "options": ["Custom image analyzer", "prebuilt-imageSearch", "prebuilt-videoSearch", "Document Intelligence layout"], "answer": 1, "explanation": "prebuilt-imageSearch is the best answer because Microsoft documents it as the analyzer that analyzes images to generate descriptions and insights, produces a one-paragraph description of the image content, and extracts visual content for search and retrieval applications. The quickstart also shows prebuilt-imageSearch being used to generate an image description directly.\nThe scenario explicitly says that a custom schema is not needed. That matters because the built-in search-oriented analyzer already matches the retrieval requirement, whereas a custom analyzer would add design effort for a problem that Microsoft already covers with a prebuilt analyzer.\nWhy the other options are incorrect:\n• A. Custom image analyzer. A custom image analyzer is appropriate when you need your own business-specific fields and controlled output schema. In this scenario, the requirement is narrower: generate descriptions for search and retrieval without defining custom fields. Microsoft’s prebuilt image search analyzer already handles that use case directly.\n• C. prebuilt-videoSearch. Microsoft documents prebuilt-videoSearch for video analysis, including transcripts, segment descriptions, and meaningful video segmentation. That makes it the wrong modality for an image library. The scenario is focused on standalone images, not time-based media.\n• D. Document Intelligence layout. Document Intelligence layout is a document-processing choice, not an image-search analyzer. Microsoft’s comparison guidance places Content Understanding on the multimodal side for images and visual content, while Document Intelligence is framed around text, tables, and structured document extraction. It does not directly match the retrieval-oriented image-description requirement here.\nPrebuilt analyzers in Azure Content Understanding in Foundry Tools\nWhat is Azure Content Understanding in Foundry Tools?", "topic": "Vision", "source": 39}, {"id": "542201", "stem": "A media team already has an application that calls the Azure OpenAI images API. They now want to add reference-image editing with strong character consistency while minimizing changes to their application’s API pattern.\nWhich model should they include in the design?", "options": ["FLUX.2-pro via BFL API", "MAI-Image-2e deployment", "FLUX.1-Kontext-pro deployment", "Azure AI Content Safety"], "answer": 2, "explanation": "FLUX.1-Kontext-pro is the best choice because Microsoft documents it as supporting in-context generation and editing with character consistency. Microsoft also states that the OpenAI-compatible Image API is available for FLUX.1-Kontext-pro and FLUX-1.1-pro, which makes it a strong fit when the application already follows the Azure OpenAI images API style.\nThis combination of API compatibility and reference-aware editing is what makes it stronger than the alternatives. The team is not just looking for image generation, but for a practical implementation path that preserves existing integration patterns while adding reference-media editing behavior.\nWhy the other options are incorrect:\n• A. FLUX.2-pro via BFL API. FLUX.2-pro is strong for multi-reference image editing, and Microsoft documents support for up to eight reference images. However, Microsoft also states that the OpenAI-compatible Image API is available for FLUX.1-Kontext-pro and FLUX-1.1-pro, while FLUX.2-pro is used through the BFL provider-specific API. That means it is less aligned with the “minimal API pattern change” requirement.\n• B. MAI-Image-2e deployment. MAI-Image-2e is documented as a text-to-image model that is faster and more efficient than MAI-Image-2 for scale-oriented scenarios. But Microsoft describes MAI here as text-prompt image generation, not reference-image editing with character consistency. It is therefore a performance-focused generation option rather than the best component for this reference-media scenario.\n• D. Azure AI Content Safety. Azure AI Content Safety is useful for moderation and safety workflows, but it is not the image generation component that performs reference-aware editing. Including it might strengthen the overall safety design, yet it does not satisfy the core generation-and-editing requirement asked in the question. This distractor confuses a guardrail service with the generative model itself.\nDeploy and use MAI models in Microsoft Foundry\nMicrosoft Foundry Playgrounds", "topic": "Vision", "source": 40}, {"id": "542297", "stem": "An Azure AI Search indexer runs successfully, but the OCR skill produces no extracted text from images embedded in PDFs. The skillset uses an OCR skill with the correct image context, and the source documents contain readable scanned pages.\nWhat should you check first?", "options": ["Set imageAction to generateNormalizedImages", "Rebuild the semantic ranking profile", "Disable integrated vectorization", "Add Azure Key Vault references"], "answer": 0, "explanation": "You should check whether the indexer is configured to generate normalized images. OCR skills that process embedded images need normalized image content produced during document cracking. Without image extraction and normalization, the skill does not receive the image inputs it expects.\nThis is a common operational issue in enrichment pipelines. A correctly defined OCR skill is not enough if the indexer configuration does not prepare the image data. The enrichment pipeline must expose the images before the OCR skill can extract text from them.\nWhy the other options are incorrect:\n• B. Rebuilding the semantic ranking profile would affect how search results are ranked at query time. It would not cause the OCR skill to receive normalized images during indexing. The problem occurs before ranking because the enriched image text is missing. This option confuses retrieval ranking with enrichment execution.\n• C. Disabling integrated vectorization does not address image extraction for OCR. Integrated vectorization is related to generating embeddings during indexing or query processing. The issue is that OCR receives no usable image content. Turning off vectorization could reduce retrieval capability without fixing the enrichment problem.\n• D. Adding Azure Key Vault references may help secure credentials or secrets used by an application. It does not configure the indexer to extract embedded images from PDFs. The scenario does not describe a secret retrieval error or authentication failure. It describes a missing enrichment input problem.\nIndexer overview\nSkillset concepts", "topic": "Vision", "source": 42}, {"id": "542379", "stem": "A design team reports that an image-editing workflow changes the entire product photo instead of only the intended background area. The prompt is clear, and the model deployment supports image editing. The team expected only the masked area to change.\nWhat should you check first?", "options": ["Fix mask transparency", "Increase Search replicas and partitions", "Switch to Azure AI Vision OCR", "Add semantic ranking to retrieval pipeline"], "answer": 0, "explanation": "The first thing to check is the mask configuration, especially whether the mask correctly identifies the editable region. In mask based image editing, the mask determines where the model should apply the requested modification, so an incorrect mask can cause edits to apply too broadly or in the wrong area.\nThe scenario says the prompt is clear and the deployment supports editing, so the likely issue is not model availability or prompt capability. A poorly formed mask, wrong alpha region, incorrect upload, or inverted target area is the most relevant first troubleshooting step.\nWhy the other options are incorrect:\n• B. Increasing Azure AI Search replicas and partitions improves search capacity and availability. It has no effect on how an image-editing model interprets a mask. This is a retrieval scaling control, not an image-generation configuration fix. It would not prevent the model from changing unmasked product pixels.\n• C. Azure AI Vision OCR extracts text from images and documents. It does not troubleshoot mask boundaries or enforce where generative edits occur. OCR could identify label text in a product image, but it would not preserve the product during an edit. The issue is about edit-region targeting, not text recognition.\n• D. Semantic ranking improves the relevance order of search results in Azure AI Search. It is not part of the image edit request and does not affect masks, pixels, or prompt driven modifications. Adding semantic ranking would help a RAG solution, not a product-image inpainting workflow. This option confuses retrieval quality with visual edit control.\nTransparency Note for Azure OpenAI\nAzure OpenAI in Microsoft Foundry Models REST API", "topic": "Vision", "source": 43}, {"id": "542439", "stem": "A claims-processing app receives photos of vehicle damage. Adjusters ask questions such as “Is the rear bumper cracked?” and “Which visible panel appears most damaged?” The solution must answer only from visible image evidence and avoid inventing unseen details.\nWhich design is most appropriate?", "options": ["OCR extraction followed by keyword matching", "Image captioning stored in Blob Storage", "Vision-enabled chat with grounding instruction", "Text embeddings over adjuster questions"], "answer": 2, "explanation": "Vision-enabled chat with a grounding instruction is the best design because the application must answer natural-language questions using image evidence. The model needs to inspect the uploaded image and respond to the specific question while being instructed not to infer details that are not visible.\nThis is a visual question answering pattern rather than a general captioning or document extraction problem. Strong system instructions should constrain the answer to visible evidence, require uncertainty when evidence is insufficient, and reduce unsupported claims.\nWhy the other options are incorrect:\n• A. OCR extraction followed by keyword matching can extract visible text, such as license plates or labels, where appropriate. It cannot reliably assess bumper cracks, panels, or vehicle damage from visual features. Keyword matching also lacks the visual reasoning needed for adjuster questions. This option is plausible only if the image evidence is mostly text.\n• B. Image captioning stored in Blob Storage creates a general image description. It does not allow the adjuster to ask targeted follow-up questions grounded in the same image. A caption might omit the exact detail needed for the claim decision. Storage is also not an answering mechanism.\n• D. Text embeddings over adjuster questions can support semantic similarity or retrieval. They do not analyze the vehicle photo itself. This option might help route common question types, but it cannot determine whether the rear bumper is visibly cracked. It confuses text retrieval with visual evidence analysis.\nPrompt engineering techniques\nResponsible AI for Azure workloads", "topic": "Vision", "source": 44}, {"id": "542011", "stem": "Match the following:\nShort sentence describing the whole photo\nRegion-level detail for parts of one image\nDecorative divider image on a webpage\nComplex chart that needs more than brief alt text\nChoices:", "options": ["Caption Dense Captions alt=\"\" Linked detailed description", "Dense Captions Caption Linked detailed description alt=\"\"", "Caption Read OCR Caption Dense Captions", "Read OCR Dense Captions alt=\"\" Caption"], "answer": 0, "explanation": "Choice A is correct. Microsoft documents that Caption generates a one-sentence description of the whole image, while Dense Captions produces more detailed descriptions for up to 10 prominent image regions. Microsoft’s accessibility guidance also says decorative images should use null alt text and that complex visuals needing long text should use detailed descriptions in surrounding text or a separate linked document.\nThis mapping separates short alt text, region-level enrichment, decorative-image handling, and long-description delivery into the right layers of an accessibility-aligned multimodal workflow. It is stronger than treating every image the same way because the Microsoft guidance explicitly differentiates meaningful images, decorative images, and complex images that need extended descriptions.\nWhy the other options are incorrect:\nB. This option reverses the first two mappings and swaps the accessibility behavior for the last two items. Dense Captions is not the primary whole-image one-sentence feature, while Caption is not the region-level feature. It also incorrectly assigns linked detailed descriptions to decorative images and null alt text to complex charts, which conflicts with Microsoft’s accessibility guidance.\nC. This option incorrectly uses OCR for region-level image description and uses Caption for decorative images. Microsoft documents OCR as text extraction, not region narrative description, and decorative images should use null alt text rather than generated caption text. It also assigns Dense Captions where Microsoft guidance says a complex chart may need a detailed surrounding or linked description.\nD. This choice incorrectly uses OCR for whole-photo description and uses Caption as the answer for a complex chart needing extended explanation. OCR does not describe non-text visual meaning, and Caption is designed for a concise whole-image sentence rather than a full extended description. Microsoft’s accessibility guidance calls for a longer surrounding or linked description for complex visuals.\nAlternative text (alt text)\nGraphics, Design, and Media", "topic": "Vision", "source": 37}, {"id": "542200", "stem": "A team built a document assistant over engineering manuals.\nThe pipeline extracts text and images and stores direct image embeddings for all visuals. Users can find similar screenshots, but questions about flowcharts and wiring diagrams still return weak answers because the assistant misses the meaning of the visuals.\nWhat is the best next step?", "options": ["Increase OCR timeout", "Add image verbalization stage", "Use semantic ranker alone", "Convert images to thumbnails"], "answer": 1, "explanation": "The best next step is to add image verbalization. Microsoft says multimodal retrieval from images can follow two complementary paths: image verbalization or direct multimodal embeddings. It also says diagrams, flow charts, and other explanation-rich visuals should be verbalized so semantic information is available for RAG and AI agent grounding, while screenshots and similar visuals are often better handled with direct embeddings.\nThat matches the failure pattern in the scenario. The current design already supports similarity-style retrieval for screenshots, but it misses the meaning inside engineering diagrams. Microsoft’s guidance points to image verbalization as the way to capture that semantic content rather than relying on direct embeddings alone.\nWhy the other options are incorrect:\n• A. Increase OCR timeout. OCR can help when the problem is incomplete text extraction. But the issue here is not primarily missing text; it is missing semantic interpretation of diagrams and flowcharts. Microsoft’s multimodal search guidance points to image verbalization for explanation-rich visuals, not timeout tuning, as the relevant fix.\n• C. Use semantic ranker alone. Semantic ranker can improve retrieval quality, so it is a credible distractor. However, ranking alone does not add the missing semantic representation of the diagrams if that meaning was never verbalized during ingestion. The root problem is representation, not just ranking.\n• D. Convert images to thumbnails. Thumbnailing may reduce payload size or storage cost, but it does not solve the semantic-understanding gap. In fact, smaller images can make fine visual structure harder to analyze. The documented remedy for diagram-heavy meaning is verbalization, not image shrinking.\nHow to use vision-enabled chat models\nWhat is Azure Content Understanding in Foundry Tools?", "topic": "Vision", "source": 40}, {"id": "542184", "stem": "A moderation workflow must review both the poster artwork and any printed slogan embedded in the poster image. The team is calling the Content Safety multimodal endpoint.\nSnippet\n{\n“image”: {\n“content”: “”\n},\n“categories”: [“Hate”, “Sexual”, “Violence”, “SelfHarm”],\n“(MISSING CONFIG)”: true,\n“text”: “Launch this campaign worldwide”\n}\nWhich property should replace (MISSING CONFIG)?", "options": ["includeText", "readText", "ocrMode", "enableOcr"], "answer": 3, "explanation": "The correct property is enableOcr. Microsoft’s multimodal quickstart shows the imageWithText:analyze request using “enableOcr”: true when you want the service to analyze image content together with text extracted from the image and any provided text. That is the exact configuration needed when moderation depends on visible printed text inside the poster.\nThis is an important implementation detail because without OCR enabled, the moderation workflow would not directly include text embedded in the image as part of the multimodal evaluation path. In a visual-policy scenario, that could let harmful slogans or prohibited textual symbols inside posters slip through even if the surrounding image is analyzed.\nWhy the other options are incorrect:\n• A. includeText. This looks plausible because the request also has a text field, but Microsoft’s documented multimodal request uses enableOcr for extracting text from the image itself. The question is about reading printed text inside the poster, not merely passing an already separate text field. includeText is not the documented property for this API.\n• B. readText. This name sounds close to OCR terminology, especially because Microsoft uses “Read” for OCR capabilities in Vision and Document Intelligence. However, the multimodal Content Safety API does not use readText as the request property. The documented flag for OCR within the multimodal moderation request is enableOcr.\n• C. ocrMode. This is another believable invented property, but Microsoft’s example request does not use it. The actual documented property is enableOcr, which turns OCR extraction on for multimodal analysis. In AI-103 style, this is the kind of near-correct configuration label that you have to reject in favor of the real API contract.\nOCR – Optical Character Recognition\nWhat is Azure AI Content Safety?", "topic": "Vision", "source": 40}, {"id": "542132", "stem": "A legal team is building a grounding index for scanned contracts and reports.\nRequirements:\nExtract both text and images from the files.\nKeep image location metadata so the application can relate figures to nearby content.\nOutput tables and figures in a format that is easier for LLMs to consume.\nAvoid adding a separate Text Split skill for chunking.\nWhich design best meets the requirements?", "options": ["Azure Content Understanding skill", "OCR skill plus Text Split", "Document Layout skill with plain text", "Query-time semantic reranking"], "answer": 0, "explanation": "Azure Content Understanding skill is the strongest fit because Microsoft says this skill analyzes unstructured documents and other content types, extracts both text and images, and preserves each image’s location within the document. Microsoft also states that the skill can be used for both content extraction and chunking, so there is no need to add a Text Split skill in the same skillset.\nIt also matches the table-and-figure requirement better than the alternatives. Microsoft documents that the Azure Content Understanding skill outputs tables and figures in Markdown, can recognize cross-page tables as a single unit, and allows chunks to span multiple pages instead of forcing page-bounded chunks. Those behaviors are especially aligned to RAG and grounding workflows for rich documents.\nWhy the other options are incorrect:\n• B. OCR skill plus Text Split. OCR is useful for extracting printed and handwritten text from image files, but the requirement is broader than OCR alone. Microsoft positions the Azure Content Understanding skill as a richer content-extraction-and-chunking option that preserves image position and handles tables and figures more effectively for LLM consumption. OCR plus Text Split would usually require more pipeline assembly and still would not match the Markdown and cross-page-table advantages described by Microsoft.\n• C. Document Layout skill with plain text. This is a plausible distractor because it can parse documents, but Microsoft explicitly contrasts it with Azure Content Understanding skill and says the Content Understanding skill outputs tables and figures in Markdown while Document Layout outputs them as plain text. Microsoft also notes that Document Layout restricts chunks to a single page, which is weaker for semantic units that span pages. That makes it a less complete match to the requirements.\n• D. Query-time semantic reranking. Semantic reranking happens after indexing and improves relevance of retrieved results, but it does not extract text and images from source files, preserve location metadata, or create Markdown-rich chunks. The scenario is fundamentally about ingestion and indexing design, not about ranking after the index is built. This option therefore addresses the wrong stage of the pipeline.\nRAG in Azure AI Search\nOCR skill", "topic": "Vision", "source": 39}, {"id": "542138", "stem": "Refer to:\nhttps://docs.google.com/document/d/1KL5r5lDcN4JDa45bROfDFuAS9anguaQi4BCFAtn4_p4/edit-usp=sharing\nYou need to satisfy E1, BR1, BR2, and C2.\nA training image can contain several defect categories and multiple instances of the same defect. The production application must identify the category and location of every detected instance.\nWhich Custom Vision project configuration should you use?", "options": ["Multilabel classification, General (compact)", "Object detection, General", "Multiclass classification, General (compact)", "Object detection, General (compact)"], "answer": 3, "explanation": "Object detection is required because BR1 requires a bounding box for every visible defect instance. An object-detection model can identify several regions within one image, including multiple instances of the same trained category. Image classification would instead assign labels to the complete image without returning each defect’s location.\nThe General (compact) domain is required because E1 specifies a local ONNX runtime and BR2 requires disconnected inference. Custom Vision models trained with compact domains can be exported and run locally, including through ONNX-compatible runtimes. The non-compact General domain is intended for hosted prediction and does not meet the offline deployment requirement.\nWhy the other options are incorrect:\nA. Multilabel classification can assign several defect labels to a complete image. It does not return bounding boxes for individual defect instances. It also cannot distinguish two separate instances of the same defect by location. Although the compact domain supports export, the selected project type still fails BR1.\nB. Object detection with the General domain would identify and locate multiple defects correctly. However, the model would remain dependent on the hosted Custom Vision prediction service. It could not be exported for local ONNX execution because the selected domain is not compact. The solution would therefore fail BR2 and C2.\nC. Multiclass classification selects one primary label for the complete image. It cannot represent several defect categories occurring in the same image. It also does not return the location of any detected defect. Its export capability does not compensate for selecting the wrong computer-vision task.\nSelect a Custom Vision domain\nExport a Custom Vision model", "topic": "Vision", "source": 39}, {"id": "542385", "stem": "A team is designing speech-enabled AI workflows for different audio scenarios.\nMatch each requirement to the best Azure capability.\nMatch the following:\nLow-latency spoken interaction\nRecorded-file transcription\nSpeaker-aware transcript attribution\nStructured extraction from audio\nChoices:", "options": ["Batch transcription Voice Live API Text to speech Azure AI Search", "Search semantic ranking Document Intelligence layout Managed identity Prompt flow tracing", "Text to speech Speaker diarization Batch transcription Azure Key Vault", "Voice Live API Batch transcription Speaker diarization Content Understanding audio analyzer"], "answer": 3, "explanation": "Voice Live API is the best match for low-latency spoken interaction because it supports real-time voice experiences. Batch transcription is better for recorded files, speaker diarization identifies who spoke during the transcript, and Content Understanding audio analyzers can extract structured information from audio content.\nThis mapping reflects the AI-103 distinction between live speech interaction, file-based transcription, speaker attribution, and higher-level audio understanding. A strong implementation uses the speech or multimodal capability that matches the timing, output, and reasoning requirement.\nWhy the other options are incorrect:\n• A. This mapping reverses live and recorded-audio requirements. Batch transcription is not the best fit for low-latency spoken interaction, and Voice Live API is not primarily a batch file-processing choice. Text to speech synthesizes audio output rather than identifying speakers in a transcript. Azure AI Search can store or retrieve extracted content, but it does not perform structured audio extraction by itself.\n• B. This mapping uses components that do not directly process speech input. Search semantic ranking improves retrieval relevance, but it does not create a live audio interaction. Document Intelligence layout is for document structure, not audio transcription. Managed identity and tracing support security and observability, but neither performs speaker attribution or audio extraction.\n• C. This mapping confuses output synthesis with input understanding. Text to speech produces spoken output, but the requirement is low-latency spoken input interaction. Speaker diarization is useful for speaker attribution, not recorded-file transcription by itself. Key Vault protects secrets, but it does not extract structured fields from audio.\nReal-time diarization quickstart\nAzure Content Understanding audio overview", "topic": "Text and speech", "source": 43}, {"id": "542168", "stem": "A team wants to build a workflow that turns uploaded videos into a retrieval-ready knowledge asset by using Azure Content Understanding.\nSteps\nConfigure default model deployments for the Content Understanding resource.\nSend an analyze request to prebuilt-videoSearch with the video URL.\nPoll the analysis operation until the result succeeds.\nIngest the returned Markdown or JSON segments into the search or chat layer.\nWhat is the correct order?", "options": ["2, 1, 3, 4", "1, 2, 3, 4", "1, 3, 2, 4", "2, 3, 1, 4"], "answer": 1, "explanation": "1 is first because Microsoft’s quickstart says you must set up default model deployments for the Content Understanding resource, including the required Foundry model deployments, before running analysis requests. 2 is second because the actual video workflow begins by sending the file to prebuilt-videoSearch for analysis.\n3 is third because Microsoft says the analyze call is asynchronous and returns an Operation-Location header that you use to retrieve the results. 4 is last because Microsoft describes prebuilt-videoSearch output as an immediately usable knowledge asset packaged as Markdown and JSON for ingestion into a search index or chat agent, which naturally happens after the operation completes successfully.\nWhy the other options are incorrect:\n• A. 2, 1, 3, 4. This sequence starts analysis before the resource is prepared with the required default model deployments. Microsoft’s quickstart puts model deployment setup before running the analysis workflow, so this order skips an important prerequisite. It might look close because the later steps are reasonable, but the opening sequence is backwards.\n• C. 1, 3, 2, 4. Polling for an analysis result before the analyze request is sent is not logically valid. Microsoft’s workflow clearly shows that the asynchronous analyze call happens first, and only then do you use the returned operation reference to retrieve results. This sequence reverses the core request-and-poll pattern.\n• D. 2, 3, 1, 4. This option delays prerequisite model configuration until after the analyze request and polling steps, which conflicts with Microsoft’s setup guidance. It also assumes you can complete the full analysis loop before the resource has been properly prepared. That makes it the weakest operational sequence of the four.\nAzure Content Understanding video overview\nAzure Content Understanding prebuilt analyzers", "topic": "Vision", "source": 40}, {"id": "542098", "stem": "Match each workload to the most appropriate model type.\nMatch the following:\nGeneral conversational generation across broad business tasks\nNarrow, low-latency, lower-cost text transformation\nRepository-aware coding assistance, refactoring, and test generation\nOne request that combines prompt text and images\nChoices:", "options": ["Multimodal model General-purpose LLM Small language model Code model", "Small language model Code model Multimodal model General-purpose LLM", "General-purpose LLM Small language model Code model Multimodal model", "Code model Multimodal model General-purpose LLM Small language model"], "answer": 2, "explanation": "Choice C is correct because it aligns each workload with the model family best suited to that task. Microsoft’s guidance emphasizes selecting a model based on the capabilities required by the workload, while Foundry’s model catalog explicitly spans small language models, multimodal models, and other specialized families. Microsoft’s Codex documentation separately anchors code-centric workflows to coding-focused models.\nThe logic is task-to-capability matching. Broad conversational generation maps to a general-purpose LLM, narrow low-latency text work maps to a small language model, repository engineering tasks map to a code model, and joint text-plus-image inference maps to a multimodal model. That is the cleanest exam-authentic mapping for this dot point.\nWhy the other options are incorrect:\n• A. This choice inverts several core mappings. It incorrectly assigns multimodal capability to general business conversation and code capability to the text-plus-image workload. It also treats a small language model as the coding-specialized choice, which is not the strongest match in Microsoft’s coding guidance.\n• B. This choice puts a small language model in the broad conversational slot and a code model in the narrow text-transformation slot. Those pairings ignore the main distinctions between general capability, efficiency-focused narrow tasks, and code specialization. It also maps multimodal incorrectly away from the image-plus-text requirement.\n• D. This choice is wrong because it treats a code model as the default for broad conversational generation and a multimodal model as the right answer for narrow low-cost text transformation. It then puts the general-purpose LLM in the repository-assistance slot and the small model in the text-plus-image slot, which reverses the intended capability mapping. The entire answer choice fails the workload-to-model-family logic described in Microsoft’s guidance.\nMicrosoft Foundry Models overview\nCodex with Azure OpenAI in Microsoft Foundry Models", "topic": "Vision", "source": 38}, {"id": "542042", "stem": "A marketplace moderates seller-uploaded product images.\nThe compliance team needs the solution to do all of the following:\nclassify default harmful visual content such as sexual or violent imagery\ntune category thresholds to match company policy\nquickly detect a newly emerging prohibited emblem from example images\navoid relying on exact-text matching for image incidents\nkeep moderators involved when results are disputed\nWhich design is the best fit?", "options": ["Standard custom categories plus blocklists", "Content Safety moderation plus rapid categories", "Azure AI Search with visual severity thresholds", "Vision labels with immediate auto-deletion"], "answer": 1, "explanation": "B is the best fit because it combines the default image-moderation system with the rapid custom-category capability that Microsoft documents for emerging incidents involving text, image, or other modalities. Microsoft also notes that blocklists allow exact text matching and no image matching, which is why rapid custom categories are the stronger choice for a newly emerging prohibited emblem visible in example images.\nIt also aligns better with Microsoft’s operational guidance. Microsoft documents configurable severity filters for image moderation and recommends supporting human judgment rather than fully automating the whole process, especially when you need to handle disputed or borderline cases.\nWhy the other options are incorrect:\nA. Standard custom categories plus blocklists. Microsoft says the standard custom-categories API works on text content, not image content. Microsoft also says blocklists support exact text matching and no image matching. That means this option fails both the “example images” requirement and the “do not rely on exact-text matching” requirement in the stem.\nC. Azure AI Search with visual severity thresholds. Azure AI Search is not the moderation service Microsoft documents for harmful-image classification, and the severity-based image moderation flow is documented under Azure AI Content Safety instead. Search infrastructure does not replace built-in unsafe-visual-content classification or rapid incident detection from image samples. This option therefore confuses retrieval technology with moderation controls.\nD. Vision labels with immediate auto-deletion. Generic vision labeling is not the documented moderation mechanism for harmful-content severity classification, and immediate auto-deletion ignores Microsoft’s recommendation to support human judgment in the review loop. The stem explicitly asks for policy tuning and disputed-case handling, which requires a more governed moderation workflow than raw labels plus irreversible automated enforcement.\nQuickstart: Analyze image content\nTransparency Note and use cases for AI Content Safety", "topic": "Vision", "source": 38}, {"id": "542437", "stem": "A team is adding safety checks to a generative AI application that accepts text, images, retrieved documents, and user prompts.\nMatch each requirement to the most appropriate Azure AI Content Safety capability.\nDetect harmful text and image content\nDetect jailbreak and prompt-injection attempts\nCheck whether generated answers are supported by sources\nDetect protected text or code material\nCheck whether responses follow the assigned task\nChoices:", "options": ["Text and image moderation Prompt Shields Groundedness detection Protected material detection Task adherence checks", "Prompt Shields Groundedness detection Protected material detection Task adherence checks Text and image moderation", "Groundedness detection Text and image moderation Prompt Shields Task adherence checks Protected material detection", "Protected material detection Task adherence checks Text and image moderation Prompt Shields Groundedness detection"], "answer": 0, "explanation": "Choice A correctly maps each responsible AI requirement to the Content Safety capability that addresses it. Text and image moderation detects harmful content, Prompt Shields help detect adversarial prompt attacks, groundedness detection checks support from grounding sources, protected material detection identifies protected content, and task adherence checks whether the response stays aligned to the assigned task.\nThe key exam distinction is that these controls are safety and quality gates, not retrieval, identity, or indexing controls. They can be used together in a production AI application, but each one targets a different risk surface.\nWhy the other options are incorrect:\n• B. This option incorrectly treats Prompt Shields as general harmful-content moderation. Prompt Shields focus on jailbreak and prompt-injection style attacks, not general text and image harm categories. It also maps groundedness to prompt-attack detection, which confuses factual support with adversarial input protection.\n• C. This option starts by mapping groundedness detection to harmful content detection, which is the wrong control. Groundedness checks whether generated output is supported by grounding data, not whether the text or image is harmful. The option also assigns Prompt Shields to source support, which misses their role in detecting prompt attacks.\n• D. This option misplaces almost every safety capability. Protected material detection does not replace moderation for harmful text and images. Task adherence does not detect jailbreak attacks, and groundedness detection does not check whether an answer follows the assigned task.\nPrompt Shields in Azure AI Content Safety\nGroundedness detection", "topic": "Vision", "source": 44}, {"id": "541993", "stem": "A manufacturer has 180,000 archived support-call recordings.\nThe organization has already trained a custom speech model that substantially improves recognition of internal product numbers and component names.\nRequirements:\nAudio does not need real-time transcription.\nThe custom speech model must be used.\nProcessing should run asynchronously at scale.\nThe organization wants to avoid maintaining a hosted custom speech endpoint when it is unnecessary.\nWhich approach should you use?", "options": ["Real-time speech recognition through a hosted custom endpoint", "Batch transcription using the custom speech model", "Voice Live with default speech recognition and synthesis", "Fast transcription through a permanent custom speech endpoint"], "answer": 1, "explanation": "Batch transcription is designed for asynchronous transcription of prerecorded audio and supports custom speech models. Microsoft specifically documents that a hosted custom speech deployment endpoint is not required when a custom speech model is used with the Batch transcription API; the transcription request can reference the custom model itself.\nThat distinction makes batch transcription especially appropriate here because there is no interactive latency requirement and there is a large archive of recorded calls. The company receives the recognition benefits of its domain-specific custom model without keeping an endpoint deployed solely for this batch workload.\nWhy the other options are incorrect:\nA. Real-time speech recognition through a hosted custom endpoint. A hosted custom endpoint is appropriate when a custom speech model must serve real-time recognition requests. The recordings here are historical and explicitly do not require real-time processing. Keeping such an endpoint for a batch-only workload introduces a resource the scenario says the organization wants to avoid. Microsoft provides the batch route specifically without requiring that hosted endpoint.\nC. Voice Live with default speech recognition and synthesis. Voice Live is oriented toward interactive, low-latency conversational voice experiences. This workload consists of archived calls being processed asynchronously, and there is no requirement to synthesize spoken responses. Using default recognition would also fail the explicit requirement to use the trained custom speech model for specialized terminology. Voice Live therefore mismatches both the interaction pattern and recognition requirement.\nD. Fast transcription through a permanent custom speech endpoint. Fast transcription is useful when a recorded file needs a result quickly and synchronously or with predictable low turnaround. The scenario instead emphasizes a very large archive and asynchronous processing. More importantly, maintaining a custom hosted endpoint contradicts the requirement to avoid one where possible. Batch transcription is the service path Microsoft specifically documents for custom-model use without that deployment requirement.\nCreate a batch transcription\nDeploy a custom speech model", "topic": "Text and speech", "source": 37}, {"id": "542389", "stem": "Refer to:\nhttps://docs.google.com/document/d/11bs39zbKg115d484zEVCJ9eMwIcefpqMHboIcYOMAIg/edit-usp=sharing\nYou need to satisfy BR3 and TR3.\nThe application submits each inspection photograph to the Image Analysis 4.0 endpoint. You must complete the request so that the response contains detected text and the approximate location of recognised objects.\nPOST {endpoint}/computervision/imageanalysis:analyze\n?api-version=2024-02-01\n&(MISSING CONFIG)\nWhich configuration should replace (MISSING CONFIG)?", "options": ["features=caption,denseCaptions", "features=read,smartCrops", "features=tags,people", "features=read,objects"], "answer": 3, "explanation": "The read visual feature runs OCR and returns text detected in the inspection photograph, including location information for the recognised text. The objects feature detects supported objects and returns approximate bounding boxes. Both visual features can be requested together in one Image Analysis 4.0 call, satisfying TR3.\nRedstone does not need to make a separate OCR request followed by an object-detection request. The selected features are supplied as a comma-separated list in the features query parameter, and the synchronous response contains the requested analysis results. This provides the equipment-identifier and object-location outputs required by BR3.\nWhy the other options are incorrect:\nA. caption returns a general natural-language description of the complete image. denseCaptions produces descriptions for regions within the image. Neither feature performs the required OCR operation for equipment identifiers. They also do not return the object-detection result collection required by TR3.\nB. read would extract the printed equipment identifiers. smartCrops identifies regions suitable for thumbnail cropping while preserving the most important image content. It does not return the recognised-object collection requested by BR3. This configuration therefore satisfies the OCR requirement but not the object-detection requirement.\nC. tags returns descriptive words associated with the image but does not provide the required text extraction. people returns bounding boxes for detected people rather than common site objects generally. The combination would not extract equipment identifiers. It also narrows detection to people instead of the broader requirement in BR3.\nCall the Image Analysis 4.0 API\nAnalyze Image REST API", "topic": "Vision", "source": 43}, {"id": "542040", "stem": "A platform team is designing a visual moderation workflow.\nMatch the following:\nClassify images into built-in harm categories such as violence and sexual content\nConfigure which severity levels are accepted or rejected per category\nDetect a newly emerging prohibited visual pattern from example images quickly\nKeep humans involved for disputed or borderline cases\nChoices:", "options": ["Azure AI Content Safety image moderation Configure category severity filters Custom categories (rapid) API Human review workflow", "Custom categories (standard) API Azure AI Search scoring profile Blocklists Automatic deletion only", "Azure AI Content Safety image moderation Configure category severity filters Blocklists Automatic deletion only", "Custom categories (standard) API Configure category severity filters Custom categories (rapid) API Automatic deletion only"], "answer": 0, "explanation": "A is the only mapping that matches Microsoft’s documentation end to end. Azure AI Content Safety image moderation is the built-in service for harmful-image classification, the service lets you configure per-category severity filters, the custom categories rapid API works on both text and image content for emerging incidents, and Microsoft recommends designing the system to support human judgment rather than fully automating moderation decisions.\nThis mapping also reflects the real operational split between default moderation, policy tuning, rapid custom detection, and human escalation. Microsoft’s transparency guidance explicitly notes that severity thresholds should be tuned for your use case and that meaningful human review helps detect and resolve misidentification and other failures.\nWhy the other options are incorrect:\nB. This choice fails in multiple places. Microsoft documents that the custom categories standard API works on text content, not image content, so it is not the right answer for built-in unsafe visual classification. Azure AI Search scoring profiles are unrelated to moderation thresholds, blocklists do exact text matching rather than image matching, and “automatic deletion only” ignores Microsoft’s guidance to support human judgment in moderation workflows.\nC. The first two mappings are correct, which makes this distractor plausible. However, Microsoft explicitly notes that blocklists allow exact text matching and no image matching, so they are not the right tool for emerging prohibited visual patterns from image examples. It also ends with automatic deletion only, which is weaker than the documented recommendation to keep meaningful human review in the system.\nD. This choice gets the second and third lines partly aligned, but it still breaks the first and fourth requirements. Microsoft says the standard custom-categories API does not work on image content, so it cannot serve as the main built-in visual-classification mechanism here. It also replaces human review with automatic deletion only, which conflicts with Microsoft’s guidance on using Content Safety to support people making judgments rather than fully automating the process.\nCustom categories in Azure AI Content Safety\nTransparency Note and use cases for AI Content Safety", "topic": "Vision", "source": 38}, {"id": "542281", "stem": "A media company is building a multimodal ingestion pipeline in Content Understanding. The first workflow must process individual advertising videos and generate structured metadata, including product category, scene summary, and brand-safety notes. The workflow does not need to compare multiple files or use reference documents.\nRequirements:\n• Support video input.\n• Minimize cost and latency.\n• Produce schema-aligned structured output.\n• Avoid unnecessary multi-step document reasoning.\nWhich configuration should the engineer choose?", "options": ["Pro mode with reference documents", "Single-file Standard task", "Azure AI Document Intelligence", "Multi-input pro document task"], "answer": 1, "explanation": "A single-file Standard task is the best fit because the workflow processes each advertising video independently and needs structured output without cross-file reasoning. Standard mode supports multiple content types, including video, and is optimized for efficient schema extraction when complex multi-step document reasoning is not required.\nThe scenario deliberately includes video input to test a key distinction. Pro mode is currently aimed at advanced document scenarios, not general video pipelines. For independent multimodal content processing where one file is analyzed at a time, a single-file Standard task is the appropriate Content Understanding configuration.\nWhy the other options are incorrect:\n• A. Pro mode with reference documents is designed for advanced document reasoning scenarios. It is useful when the analyzer must compare documents, validate against reference data, or perform multi-step reasoning. The requirement explicitly says there is no need to compare multiple files or use reference documents. It also adds unnecessary complexity and does not match the video-focused workflow.\n• C. Azure AI Document Intelligence is a strong document extraction service. However, the scenario is about Content Understanding and includes advertising video input. Document Intelligence is not the best fit for configuring a multimodal Content Understanding pipeline for video metadata. It would also fail the requirement to use the Content Understanding task mode that supports this type of multimodal workflow.\n• D. Multi-input pro document task is close because it mentions pro mode and multiple inputs. However, the scenario does not need multiple input files or cross-document validation. It also involves video, while pro mode is specifically positioned for document-focused advanced reasoning. This option over-engineers the design and selects the wrong mode for the content type.\nCreate Content Understanding Standard and Pro tasks\nBest practices for Azure Content Understanding", "topic": "Vision", "source": 42}, {"id": "542076", "stem": "An application submits a Sora video-generation job and polls the job until its status is succeeded.\nThe initial job ID is used correctly for the status endpoint. The application must now download the generated MP4.\nSnippet\nif status == “succeeded”:\ngenerations = status_response.get(“generations”, [])\nif generations:\n(MISSING CONFIG)\nvideo_url = (\nf”{endpoint}/openai/v1/video/generations/”\nf”{generation_id}/content/video-api-version={api_version}”\n)\nvideo_response = requests.get(\nvideo_url,\nheaders=headers\n)\nWhich line should replace (MISSING CONFIG)?", "options": ["generation_id = job_id", "generation_id = deployment_name", "generation_id = status_response[\"status\"]", "generation_id = generations[0].get(\"id\")"], "answer": 3, "explanation": "Sora video generation is asynchronous. The initial identifier represents the job used for polling, while a successful job response contains one or more generated video objects with their own generation IDs. Microsoft’s current example obtains generations[0].get(“id”) before constructing the content-download endpoint.\nThe download URL expects a generation ID, not the job ID used for the job-status endpoint. This distinction matters because one job can produce generated-content objects that are subsequently retrieved through generation-specific API paths.\nWhy the other options are incorrect:\nA. generation_id = job_id. The job ID is valid when querying the asynchronous job status endpoint. Microsoft uses the generation object ID for the later /video/generations/{generation_id}/content/video request. Reusing the job ID therefore confuses the lifecycle object representing the render operation with the object representing its generated content.\nB. generation_id = deployment_name. The deployment name identifies the model deployment that receives generation requests. It does not identify the individual video produced by a particular asynchronous job. Reusing it in the generated-content endpoint would not select the completed video asset.\nC. generation_id = status_response[“status”]. The status field contains a lifecycle state such as queued, running, succeeded, failed, or cancelled. It indicates whether processing has completed but is not a resource identifier. A successful status tells the code when it is safe to look for the generation ID rather than replacing that ID.\nAzure OpenAI image, audio, and video REST API reference\nAzure OpenAI API version lifecycle", "topic": "Vision", "source": 38}, {"id": "542369", "stem": "pipeline:\nname: support-message-analysis\ninput:\nsource: chat-ingestion\nfield: messageText\nsteps:\n– name: sentiment\nservice: azure_ai_language\ntask: sentiment_analysis\noutput:\nfields:\n– sentiment\n– confidence_scores\n– name: sensitive_content\nservice: azure_ai_language\ntask: pii_entity_recognition\noutput:\nfields:\n– redacted_text\n– pii_entities\n– name: safety_review\nservice: azure_ai_content_safety\ntask: (MISSING CONFIG)\noutput:\nfields:\n– categories\n– severity\nrouting:\nescalate_when:\n– safety_review.severity >= 4\n– sentiment == negative\nWhich configuration should replace the missing line?", "options": ["detect_language", "extractive_summarization_with_sentence_ranking", "recognize_linked_entities", "analyze_text_harm_categories"], "answer": 3, "explanation": "analyze_text_harm_categories is the best missing configuration because Azure AI Content Safety is used to analyze text for harmful content categories and severity. The output fields in the snippet also point to this requirement because they expect category and severity results.\nThe other configured steps already cover sentiment and sensitive personal information. The missing step must therefore handle safety issues, not language detection, entity linking, or summarization.\nWhy the other options are incorrect:\n• A. detect_language identifies the language of the input text. That can be useful as a preprocessing step for multilingual pipelines, but it does not classify harmful content. It also would not produce harm categories or severity scores. This option does not match the output fields in the snippet.\n• B. extractive_summarization_with_sentence_ranking would identify important sentences from a longer document. It is not intended to detect harmful safety issues in messages. It also does not return safety categories or severity levels. This option confuses summarization with moderation.\n• C. recognize_linked_entities identifies entities and links them to a knowledge base where possible. It can help enrich text with recognized concepts, but it does not detect harm categories. It also does not satisfy the escalation rule based on safety severity. This option targets entity enrichment rather than safety review.\nAzure AI Content Safety harm categories\nAzure AI Language PII detection", "topic": "Text and speech", "source": 43}, {"id": "542047", "stem": "Match each requirement to the most appropriate translation capability or evaluation component.\nMatch the following:\nTranslate short text into several target languages in one real-time request before an LLM step.\nTranslate one uploaded file and return the translated document directly without Blob Storage.\nBuild a translation system that understands company-specific terminology from bilingual training data.\nScore an LLM-powered translation flow against human reference translations.\nChoices:", "options": ["Text translation Synchronous document translation Custom Translator BleuScoreEvaluator", "Azure Language Asynchronous document translation Text translation FluencyEvaluator", "Synchronous document translation Text translation Custom Translator BleuScoreEvaluator", "Text translation Asynchronous document translation Custom Translator FluencyEvaluator"], "answer": 0, "explanation": "Choice A is the strongest mapping. Microsoft documents text translation for real-time source-to-target translation and multiple target languages in a single request, synchronous document translation for a single file returned directly without Blob Storage, and Custom Translator for building customized neural systems that understand business-specific terminology from training data. Microsoft’s evaluation package documents BLEU as an evaluator commonly used for machine translation when you want to compare generated text with a reference.\nThis mapping also aligns well to a modern application pattern where Translator handles deterministic multilingual transformation and an LLM workflow is then evaluated with translation-aware metrics. BLEU is not a translation engine, but it is the documented evaluation component in Azure’s evaluation package for comparing translation output to ground truth.\nWhy the other options are incorrect:\n• B. This mapping incorrectly assigns Azure Language to the real-time translation scenario and Text translation to the custom-translation training scenario. Microsoft positions Azure Language for NLP understanding tasks, not as the primary translation engine, and it positions Custom Translator, not Text translation, for business-specific trained translation systems. It also assigns asynchronous document translation to a no-Blob direct-response file scenario, which conflicts with Microsoft’s synchronous document translation guidance.\n• C. This choice swaps text translation and synchronous document translation for scenarios 1 and 2. Microsoft’s text translation API is the real-time text path, while synchronous document translation is for a single file returned directly to the client. Reversing them mismatches both workload shape and response behavior.\n• D. This mapping gets scenario 1 and scenario 3 right, but it misses scenario 2 and scenario 4. Microsoft states that asynchronous document translation requires Blob Storage, so it is the wrong match for a direct-response single-file workflow, and FluencyEvaluator is about fluency rather than the translation-reference similarity use case that Microsoft explicitly ties to BLEU. Those two errors make the overall mapping incorrect.\nQuickstart: Document translation REST API\nazure.ai.evaluation package", "topic": "Text and speech", "source": 38}, {"id": "541981", "stem": "A company processes several million short support messages each month. Each message must be classified into a fixed routing category and converted into a small structured response.\nTesting on a representative evaluation dataset shows that:\nA small language model exceeds the required classification-quality threshold.\nA much larger language model improves accuracy by less than 1%.\nThe small model has substantially lower latency and estimated inference cost.\nThe workload does not require images, code generation, long-context reasoning, or multistep planning.\nThe team will continue running evaluations against production samples after deployment.\nWhich model choice should you recommend?", "options": ["Large language model with provisioned throughput and strict JSON prompting", "Small language model validated on business data", "Multimodal model with a larger context window", "Code model fine-tuned for routing labels"], "answer": 1, "explanation": "A small language model is the strongest choice because the team has already performed the most important validation: it tested candidate models against representative business data and established that the smaller model meets the required quality threshold. The larger model’s marginal accuracy improvement does not justify its higher latency and cost when the task is narrow and does not require advanced reasoning or additional modalities. Microsoft expects AI engineers to select models according to workload requirements rather than simply choose the largest available model.\nThe continued-evaluation requirement is also important. A model that meets today’s threshold should still be monitored against representative production inputs because workload characteristics and output quality can change. The correct engineering decision is therefore to use the least-complex model that demonstrably satisfies the workload while maintaining an evaluation process that can detect when that assumption stops being true.\nWhy the other options are incorrect:\nA. Large language model with provisioned throughput and strict JSON prompting. A larger language model could perform the classification task, so this is technically plausible. However, the evaluation data already shows that its quality improvement is marginal while its cost and latency are materially higher. Provisioned throughput addresses predictable capacity and latency characteristics; it does not make an unnecessarily large model a better task fit. The requirement is to minimize cost and latency while preserving the validated quality threshold, which this option fails.\nC. Multimodal model with a larger context window. A multimodal model would be appropriate if the application needed to reason over images, audio, or another supported modality alongside text. None of those capabilities are required here, and the input is explicitly short text. A larger context window also provides little value for a compact classification workload. Choosing additional capabilities that the application does not need would work against the cost and latency objectives.\nD. Code model fine-tuned for routing labels. Code-oriented models are useful when the workload centers on software development, code transformation, debugging, or similar programming tasks. The workload here is business-text classification rather than code reasoning. Fine-tuning could potentially be considered if evaluation showed that prompting or an existing model could not satisfy quality requirements, but the scenario says the small language model already passes the required threshold. Introducing a code-oriented model and a training lifecycle would therefore add complexity without solving an identified problem.\nModel benchmarks\nChoose an AI model", "topic": "Text and speech", "source": 37}, {"id": "542238", "stem": "A Python service must translate speech from an English WAV file into German, Italian, and French in one recognition workflow.\nThe developer has created the translation configuration:\nimport os\nimport azure.cognitiveservices.speech as speechsdk\ntranslation_config = speechsdk.translation.SpeechTranslationConfig(\nsubscription=os.environ[“SPEECH_KEY”],\nregion=os.environ[“SPEECH_REGION”]\n)\ntranslation_config.speech_recognition_language = “en-US”\ntargets = [“de”, “it”, “fr”]\n# (MISSING CONFIG)\nresult = recognizer.recognize_once()\nWhich implementation should replace (MISSING CONFIG)?", "options": ["Create one SpeechConfig and three separate SpeechRecognizer objects", "Add each target language, create file AudioConfig, then create TranslationRecognizer", "Create AutoDetectSourceLanguageConfig and use a standard SpeechRecognizer", "Create TranslationRecognizer using the default microphone"], "answer": 1, "explanation": "The Speech SDK supports multiple translation targets by calling add_target_language() for each language. File-based input should be supplied through AudioConfig(filename=…), and that audio configuration is then passed to TranslationRecognizer.\nThe missing code is:\nfor lang in targets:\ntranslation_config.add_target_language(lang)\naudio_config = speechsdk.audio.AudioConfig(\nfilename=”support-call.wav”\n)\nrecognizer = speechsdk.translation.TranslationRecognizer(\ntranslation_config=translation_config,\naudio_config=audio_config\n)\nWhy the other options are incorrect\nA. One translation recognizer can return multiple target translations, so separate speech recognizers are unnecessary.\nC. The source language is already known, and SpeechRecognizer is not the required translation workflow.\nD. The requirement specifies an existing WAV file, not live microphone input.\nSpeech translation quickstart\nSpeechTranslationConfig Python API", "topic": "Text and speech", "source": 41}, {"id": "542164", "stem": "A team already checked in its Foundry project, azure.yaml, and Bicep files.\nThe GitHub Actions job signs in to Azure successfully and selects the target environment.\nWhich command should replace the missing line so the job provisions and deploys the Foundry solution?\nSnippet\nname: azure-dev\non:\npush:\nbranches: [ main ]\njobs:\ndeploy:\nruns-on: ubuntu-latest\nsteps:\n– uses: actions/checkout@v4\n– name: Install Azure Developer CLI\nuses: Azure/setup-azd@v1\n– name: Azure login\nuses: azure/login@v2\nwith:\nclient-id: ${{ secrets.AZURE_CLIENT_ID }}\ntenant-id: ${{ secrets.AZURE_TENANT_ID }}\nsubscription-id: ${{ secrets.AZURE_SUBSCRIPTION_ID }}\n– name: Select environment\nrun: azd env select prod\n– name: Provision and deploy Foundry app\nrun: |\n(MISSING CONFIG)\nSelect only one answer.", "options": ["azd up", "azd pipeline config", "az deployment group create", "azd auth login"], "answer": 0, "explanation": "azd up is the best replacement because Microsoft’s Foundry azd guidance says that azd up orchestrates the deployment workflow end to end: it provisions infrastructure, deploys models, builds and pushes containers when needed, and publishes the agent or application endpoint. In other words, it is the command intended to turn a checked-in azd-based Foundry solution into a deployed environment.\nBy contrast, azd pipeline config is the setup command that creates the CI/CD pipeline configuration itself. Microsoft documents it as the command that selects the provider, configures authentication, copies pipeline files, sets secrets and variables, and pushes the pipeline definition to the repository. That is a configuration step, not the deployment command executed inside the configured pipeline job.\nWhy the other options are incorrect:\n• B. azd pipeline config. This is a real azd command, so it is a credible distractor. But Microsoft describes it as the command that creates or configures the pipeline, including provider selection, auth setup, and pipeline file creation. Once the pipeline already exists and is running, this is not the command you use for the actual deployment step.\n• C. az deployment group create. This can deploy a Bicep template at resource-group scope, so it is technically relevant. However, Microsoft’s Foundry azd workflow covers more than raw Bicep deployment by also coordinating azure.yaml, model deployment, environment handling, and application publishing. Using az deployment group create alone would bypass the broader azd orchestration the checked-in solution is built around.\n• D. azd auth login. This is used to authenticate azd, primarily in development or setup flows. In the snippet, Azure authentication has already been handled earlier in the job, and the missing line is specifically inside the deploy step. So this command would not provision or deploy the Foundry solution.\nCreate a GitHub Actions CI/CD pipeline using the Azure Developer CLI\nExplore Azure Developer CLI support for CI/CD pipelines", "topic": "Vision", "source": 40}, {"id": "542301", "stem": "An image review app must support two modes. Brief mode must return one short description for each image. Detailed mode must return a whole-image description and region-level descriptions. The app also supports galleries containing multiple images.\nProblem:\nThe current app uses Tags for every image and formats the tag list as a sentence.\nProposed solution:\nUse Caption for brief mode, Dense Captions for detailed mode, and process each gallery image separately.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because Caption is appropriate for a concise whole-image description, and Dense Captions is appropriate when detailed region-level descriptions are required. Processing each gallery image separately also ensures that every image receives the selected captioning behavior.\nThis solution also corrects the original design flaw. Tags can identify visual concepts, but they are not the same as natural-language captions. Using the captioning features directly produces outputs that better match both brief and detailed app modes.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution maps the required output modes to the correct captioning features. It also handles multiple images by applying the selected analysis to each image. There is no requirement for a single cross-image narrative comparison. The solution satisfies concise captions, detailed captions, and gallery processing.\nWhat is Image Analysis?\nCall the Image Analysis 4.0 Analyze API", "topic": "Vision", "source": 42}, {"id": "542296", "stem": "An engineer is configuring an Azure AI Search skillset. The source files are scanned PDFs that contain embedded images. The pipeline must extract readable text from normalized images so the text can be indexed for grounding.\nSnippet\n{\n“name”: “claims-enrichment-skillset”,\n“description”: “Enrich claims documents for retrieval and grounding.”,\n“skills”: [\n{\n“@odata.type”: “#Microsoft.Skills.Text.KeyPhraseExtractionSkill”,\n“context”: “/document”,\n“inputs”: [\n{\n“name”: “text”,\n“source”: “/document/content”\n}\n],\n“outputs”: [\n{\n“name”: “keyPhrases”,\n“targetName”: “keyPhrases”\n}\n]\n},\n{\n“@odata.type”: “(MISSING CONFIG)”,\n“context”: “/document/normalized_images/*”,\n“inputs”: [\n{\n“name”: “image”,\n“source”: “/document/normalized_images/*”\n}\n],\n“outputs”: [\n{\n“name”: “text”,\n“targetName”: “imageText”\n}\n]\n}\n]\n}\nWhich skill type should replace (MISSING CONFIG)?", "options": ["#Microsoft.Skills.Text.EntityRecognitionSkill", "#Microsoft.Skills.Util.ShaperSkill", "#Microsoft.Skills.Vision.ImageAnalysisSkill", "#Microsoft.Skills.Vision.OcrSkill"], "answer": 3, "explanation": "#Microsoft.Skills.Vision.OcrSkill is correct because the pipeline must extract readable text from normalized images. OCR is the built-in skill designed to detect and extract text from image content so it can be added to enriched documents and indexed.\nThe snippet already includes a text enrichment skill for key phrases. The missing skill is operating on /document/normalized_images/*, which is the expected context for image-based enrichment. Because the target output is text from images, OCR is the most direct fit.\nWhy the other options are incorrect:\n• A. #Microsoft.Skills.Text.EntityRecognitionSkill extracts named entities from text. It can identify items such as people, locations, organizations, or other entity categories depending on configuration. However, it expects text input rather than extracting text from an image. It could run after OCR, but it is not the missing image-to-text skill.\n• B. #Microsoft.Skills.Util.ShaperSkill reshapes enriched data into complex structures. It is useful when projected output needs a specific structure for indexing or knowledge storage. However, it does not perform OCR or analyze images. It could organize OCR output later, but it cannot create the image text.\n• C. #Microsoft.Skills.Vision.ImageAnalysisSkill analyzes image content and can produce visual features such as tags or captions. It is plausible because the context is normalized images. However, the required output is readable text from scanned images. OCR is the correct built-in skill when the goal is extracting text from images.\nImage Analysis skill\nExtract text from images", "topic": "Vision", "source": 42}, {"id": "542279", "stem": "A company processes support emails in a Foundry application. The output must include named entities, main topics, a three-sentence summary, and a strict JSON object that downstream automation can parse.\nProblem:\nYou need to implement language-model text analysis with structured output.\nProposed solution:\nUse Azure Language capabilities for entity and key phrase extraction, use a Foundry model prompt to generate the summary, and configure Structured Outputs with a JSON Schema for the final response.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it uses the right capability for each part of the text analysis workflow. Azure Language capabilities can support named entity and key phrase extraction, while a Foundry model prompt can generate the required summary.\nThe solution also addresses the downstream parsing requirement by using Structured Outputs with a JSON Schema. That is stronger than relying on prompt wording alone because the output must be predictable enough for automation to parse reliably.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed design satisfies all stated requirements. It extracts entities, derives topics through key phrase extraction, generates the summary, and enforces a structured JSON object. The design also separates extraction, generation, and output validation instead of forcing one capability to do everything. Normal production concerns such as monitoring, security, and testing still apply, but the core approach meets the goal.\nSummarization overview\nStructured outputs with Azure OpenAI", "topic": "Text and speech", "source": 41}, {"id": "542351", "stem": "An engineering team is building a multimodal inspection workflow. The workflow must identify objects in still images, describe localized regions when object labels are not enough, and analyze uploaded videos for object appearances over time.\nProblem:\nThe solution must support object, component, and region identification across image and video inputs.\nProposed solution:\nUse Azure AI Vision object detection for still images, dense captions for localized image regions, and Azure AI Video Indexer for video object insights.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it uses the appropriate Azure AI capability for each part of the multimodal workflow. Object detection handles still-image object localization, dense captions provide region-level descriptions, and Azure AI Video Indexer addresses video analysis over time.\nThis is a strong AI-103 design because it avoids forcing one capability to handle every modality. Still images, region descriptions, and videos have different output needs, so combining the right services produces a cleaner and more operationally realistic solution.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed design directly satisfies the stated requirements. It includes object detection for still images, dense captions for localized regions, and a video-aware service for uploaded videos. A production implementation may still need monitoring, security, storage, and cost controls, but those are outside this specific goal. The core service-selection design is correct.\nImage captions – Image Analysis 4.0\nAzure AI Video Indexer insights overview", "topic": "Vision", "source": 43}, {"id": "542429", "stem": "An enterprise knowledge assistant accepts uploaded images and screenshots. Some screenshots may contain hidden instructions that attempt to override the system prompt, and some generated images must be traceable as AI-created content.\nProblem:\nThe team must reduce harmful visual content, detect embedded prompt-injection attempts, and support traceability for generated images.\nProposed solution:\nUse image harmful-content detection and block unsafe uploads. Do not scan embedded text for prompt injection. Do not apply watermarking or provenance controls to generated images.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "The proposed solution does not meet the goal because it addresses only part of the responsible AI requirement. Harmful image detection can help block unsafe visual content, but the scenario also requires detecting indirect prompt injection from embedded text and supporting traceability for generated images.\nMultimodal responsible AI controls must cover both visual harm and cross-modal attack paths. A screenshot can contain text that attempts to manipulate the assistant, so embedded text should be inspected and handled according to policy. Generated images also require provenance or watermarking controls when traceability is a stated requirement.\nWhy the other options are incorrect:\n• A. Yes is incorrect because the proposed solution leaves two explicit requirements unmet. Blocking unsafe uploads does not detect prompt injection hidden in image text. It also does not provide watermarking or provenance controls for generated images. The answer would be yes only if harmful image detection were the sole requirement, which it is not.\nAzure AI Content Safety prompt shields\nResponsible AI for Azure workloads", "topic": "Vision", "source": 44}, {"id": "542342", "stem": "import os\nimport requests\nendpoint = os.environ[“AZURE_OPENAI_ENDPOINT”]\ndeployment = os.environ[“IMAGE_DEPLOYMENT”]\napi_key = os.environ[“AZURE_OPENAI_API_KEY”]\nurl = (\nf”{endpoint}/openai/deployments/{deployment}”\n“/images/edits-api-version=2025-04-01-preview”\n)\nheaders = {\n“api-key”: api_key\n}\nprompt = (\n“Replace the masked background with a clean studio setting. “\n“Keep the product shape, label, and lighting realistic.”\n)\nwith open(“product.png”, “rb”) as image_file:\nwith open(“product-mask.png”, “rb”) as mask_file:\nfiles = {\n(MISSING CONFIG)\n}\ndata = {\n“prompt”: prompt,\n“size”: “1024×1024”,\n“n”: “1”\n}\nresponse = requests.post(\nurl,\nheaders=headers,\ndata=data,\nfiles=files,\ntimeout=120\n)\nresponse.raise_for_status()\nprint(response.json()[“data”][0][“b64_json”][:80])\nWhich configuration should replace (MISSING CONFIG)?", "options": ["\"image\": open(\"prompt.txt\", \"rb\")", "\"image\": image_file, \"mask\": mask_file", "\"mask\": prompt, \"image\": deployment", "\"image\": image_file, \"context\": mask_file"], "answer": 1, "explanation": "The edit request must include the original image and the mask file so the service can determine which pixels should be changed. The prompt tells the model what to generate in the masked area, while the image and mask provide the visual input for the edit.\nThis is a configuration decision, not a syntax trick. In an image-editing workflow, the source image, mask, and prompt are separate inputs with different roles: the source image provides context, the mask defines the target region, and the prompt describes the requested modification.\nWhy the other options are incorrect:\n• A. This option incorrectly sends a text file as the image input. The prompt belongs in the request data, not as the binary image file. The service needs the actual source image to preserve unmasked content. Without the original image, the workflow cannot perform a targeted edit against the existing product photo.\n• C. This option mixes the prompt and deployment values into file fields. A mask must be an image input that marks the editable area, not the text prompt. The deployment name identifies the model deployment in the URL and should not be uploaded as image data. This configuration would not provide the required original image and mask pair.\n• D. This option includes the original image but uses context instead of the expected mask input. The model needs a mask field to identify where the edit should be applied. A generic context field does not tell the image-editing endpoint which region is editable. This would fail to configure a proper mask based editing workflow.\nCreate a resource and deploy a model with Azure OpenAI\nAzure OpenAI in Microsoft Foundry Models REST API", "topic": "Vision", "source": 43}, {"id": "542271", "stem": "An engineer is configuring a ticket-summary generator. The output must remain concise and stable across retries while preserving enough length for a complete summary.\nSnippet\nimport os\nfrom openai import AzureOpenAI\nclient = AzureOpenAI(\nazure_endpoint=os.environ[“AZURE_OPENAI_ENDPOINT”],\napi_key=os.environ[“AZURE_OPENAI_API_KEY”],\napi_version=”2024-10-21″,\n)\nsystem_prompt = “””\nYou summarize support tickets for escalation.\nUse concise language.\nDo not add facts that are not present in the ticket.\nReturn JSON with: issue, impact, urgency, next_action.\n“””\nticket_text = load_ticket_text()\nresponse = client.chat.completions.create(\nmodel=os.environ[“AZURE_OPENAI_DEPLOYMENT”],\nmessages=[\n{“role”: “system”, “content”: system_prompt},\n{“role”: “user”, “content”: ticket_text},\n],\n(MISSING CONFIG)\n)\nprint(response.choices[0].message.content)\nWhich configuration should replace (MISSING CONFIG)?", "options": ["temperature=0.8, top_p=0.95", "presence_penalty=2.0, max_tokens=300", "top_p=0.2, frequency_penalty=2.0", "temperature=0.1, max_tokens=600"], "answer": 3, "explanation": "temperature=0.1, max_tokens=600 is the best configuration because it lowers randomness while still allowing enough output length for a complete structured summary. The prompt already constrains the role, grounding behavior, and output shape. The missing configuration should support stability and practical response length rather than encourage creative variation.\nThe code tests generation behavior, not authentication or deployment setup. A low temperature helps make repeated runs more consistent, while max_tokens prevents the response from being cut off too early. This is a common operational tuning pattern for summarization, classification-like generation, and structured assistant responses.\nWhy the other options are incorrect:\n• A. temperature=0.8, top_p=0.95 would allow more randomness than the scenario needs. It may be appropriate for creative generation or brainstorming workloads. However, the requirement is stable ticket summarization with minimal unsupported content. This option makes the model more flexible, but not more predictable.\n• B. presence_penalty=2.0, max_tokens=300 may encourage the model to introduce new topics or avoid repeating terms. That can be harmful in ticket summarization because repeated service names or issue terms may be necessary. The lower max_tokens value may also increase the risk of incomplete JSON or truncated summaries. It does not directly solve repeatability.\n• C. top_p=0.2, frequency_penalty=2.0 changes two sampling-related behaviors in a way that can be harder to tune. A strong frequency penalty may discourage useful repetition of important ticket terms. Reducing top_p can constrain sampling, but the scenario is better served by a clear low-temperature setting and adequate output length. This option is plausible but less targeted.\nPrompt engineering techniques\nHow to use JSON mode with Azure OpenAI", "topic": "Text and speech", "source": 41}, {"id": "542392", "stem": "import os\nfrom openai import AzureOpenAI\nclient = AzureOpenAI(\nazure_endpoint=os.environ[“AZURE_OPENAI_ENDPOINT”],\napi_key=os.environ[“AZURE_OPENAI_API_KEY”],\napi_version=”2024-10-21″\n)\nticket_schema = {\n“name”: “support_ticket_analysis”,\n“schema”: {\n“type”: “object”,\n“properties”: {\n“entities”: {\n“type”: “array”,\n“items”: {“type”: “string”}\n},\n“topics”: {\n“type”: “array”,\n“items”: {“type”: “string”}\n},\n“summary”: {“type”: “string”},\n“sentiment”: {\n“type”: “string”,\n“enum”: [“positive”, “neutral”, “negative”, “mixed”]\n},\n“tone”: {“type”: “string”},\n“requiresSafetyReview”: {“type”: “boolean”}\n},\n“required”: [\n“entities”,\n“topics”,\n“summary”,\n“sentiment”,\n“tone”,\n“requiresSafetyReview”\n],\n“additionalProperties”: False\n},\n“strict”: True\n}\nresponse = client.chat.completions.create(\nmodel=os.environ[“AZURE_OPENAI_DEPLOYMENT”],\nmessages=[\n{\n“role”: “system”,\n“content”: (\n“Analyze the support message. Return only the required “\n“fields. Do not add unrequested properties.”\n)\n},\n{\n“role”: “user”,\n“content”: os.environ[“TRANSLATED_SUPPORT_MESSAGE”]\n}\n],\nresponse_format=(MISSING CONFIG),\ntemperature=0.1\n)\nprint(response.choices[0].message.content)\nWhich configuration should replace (MISSING CONFIG)?", "options": ["{\"type\": \"json_object\", \"schema\": ticket_schema, \"strict\": True}", "{\"type\": \"json_schema\", \"json_schema\": ticket_schema}", "{\"semanticConfiguration\": \"support-ticket-semantic-config\"}", "{\"content_filter_results\": \"required\", \"schema_validation\": True}"], "answer": 1, "explanation": "json_schema structured outputs are the best fit because the application needs the model response to follow a strict schema, not merely produce valid JSON. This is important when the output is consumed by downstream systems that expect fixed fields such as entities, topics, sentiment, tone, and a safety-review flag.\nThe broader solution can still use Foundry Tools and Azure AI services around the model call. Azure Translator can normalize multilingual input, Azure AI Content Safety can screen harmful or risky content, and the model prompt can perform generative extraction and summarisation. The missing configuration specifically controls schema-conforming JSON output from the model response.\nWhy the other options are incorrect:\n• A. JSON mode can help produce syntactically valid JSON, but it does not guarantee strict adherence to the supplied schema. The scenario requires reliable field structure for downstream systems, which is stronger than general JSON validity. Adding schema and strict beside json_object does not make JSON mode equivalent to structured outputs. This option is plausible because it looks schema-related, but it uses the wrong response format type.\n• C. A semantic configuration is associated with Azure AI Search semantic ranking, not model response formatting. It can improve relevance when retrieving grounding content, but it does not force an LLM response to match a JSON schema. The workload described here is text analysis output shaping, not search result ranking. This option confuses retrieval configuration with generation output control.\n• D. Content filter results are related to safety evaluation and moderation signals, not schema validation for extracted fields. Content Safety and model content filtering are important in this workflow, but they do not replace structured outputs. The model could still return unpredictable fields without a schema-constrained response format. This option mixes safety metadata with output contract enforcement.\nWhat is Azure AI Content Safety\nWhat is Azure Translator in Foundry Tools", "topic": "Text and speech", "source": 43}]}, {"id": "07-rag-extraction", "level": 7, "rank": "Harder", "title": "Scenario lab: RAG and extraction", "minutes": 70, "cheat": "Cheat sheet 2.1 and domain 5 — grounding and information extraction", "blurb": "Scenarios on hybrid search, agentic retrieval, and document analyzers.", "focus": ["Hybrid search plus semantic ranking is the usual pattern for grounded answers.", "Agentic retrieval fits when one user question needs several focused subqueries.", "Content Understanding analyzers produce structured fields or markdown that an agent can reason over.", "A wrong answer with weak sources is a retrieval problem first. Check the index before you retune the model."], "pool": 113, "questions": [{"id": "542332", "stem": "A company runs a production RAG assistant in Azure AI Foundry.\nThe team needs to detect weekly degradation in groundedness and answer quality.\nWhich capability should they use first?", "options": ["Azure AI Search indexer diagnostic logs", "Azure Storage lifecycle management policies", "Azure AI Foundry evaluations", "Azure Key Vault diagnostic access logs"], "answer": 2, "explanation": "Azure AI Foundry evaluations are the best fit because they directly assess generative AI quality signals such as groundedness, relevance, retrieval quality, and response quality. For a RAG assistant, these metrics are more meaningful than generic infrastructure logs because the risk is not just whether the system is running, but whether it is still producing grounded, useful, and safe answers.\nThis also supports drift-style monitoring because evaluation results can be compared over time against a baseline. A production assistant may still have normal latency and availability while its retrieval quality or groundedness gets worse due to changed source documents, prompts, model behavior, or retrieval configuration.\nWhy the other options are incorrect:\n• A. Azure AI Search indexer diagnostic logs are useful for troubleshooting indexing failures, document ingestion, and search service behavior. They do not directly evaluate whether generated answers are grounded in retrieved context. They also do not measure model response quality or safety behavior. They are a supporting signal, not the primary monitoring capability for this requirement.\n• B. Azure Storage lifecycle management policies control retention, tiering, and deletion behavior for stored data. They do not evaluate model performance, safety events, or grounding quality. They might affect source data availability if misconfigured, but they are not a monitoring solution for AI behavior. This option focuses on storage cost and data management rather than AI quality.\n• D. Azure Key Vault diagnostic access logs help investigate secret access, authentication, and security operations. They are relevant if the application cannot access keys or secrets. They do not measure groundedness, model drift, response relevance, or safety events. This option confuses security audit logging with AI quality monitoring.\nModel monitoring for generative AI applications\nAzure AI Foundry evaluation SDK", "topic": "Generative AI and RAG", "source": 42}, {"id": "542130", "stem": "A team stores PDFs and images in one Azure Blob Storage container.\nNew files arrive every night, and the search index must refresh automatically without custom ingestion code.\nWhich ingestion approach should they use?", "options": ["Push documents with Search Documents API", "Azure Blob indexer", "Semantic ranker", "Search explorer"], "answer": 1, "explanation": "Azure Blob indexer is the best fit because Azure AI Search documents it as the component that imports content from Azure Blob Storage and makes it searchable in a search index. Microsoft also describes indexers as the pull-model ingestion mechanism for supported data sources, which means the service can crawl the source and populate the index without you writing custom document-push code.\nThis option also matches the refresh requirement. Microsoft says indexers can run on demand or on a recurring schedule as often as every five minutes, and for blob data, change detection is automatic on later runs. That makes a blob indexer the strongest ingestion choice for recurring document and image updates in a grounding pipeline.\nWhy the other options are incorrect:\n• A. Push documents with Search Documents API. This can work when your application already has JSON documents ready to upload, but the question explicitly wants to avoid custom ingestion code. Microsoft distinguishes push from pull ingestion and explains that indexers are the pull-model option for supported sources such as Azure Blob Storage. In this scenario, using the push API would add unnecessary orchestration work.\n• C. Semantic ranker. Semantic ranker improves relevance at query time, but it is not an ingestion component. Microsoft describes it as a ranking capability, not as a tool that imports source files into a search index. Choosing it would not solve the requirement to crawl the Blob container and refresh indexed content.\n• D. Search explorer. Search explorer is a testing surface in the portal, not a pipeline component for crawling and indexing external content. It can help inspect queries, but it does not ingest data from Blob Storage or schedule refreshes. That makes it operationally unrelated to the problem the question is asking.\nIndexer overview\nIntroduction to Azure AI Search", "topic": "Generative AI and RAG", "source": 39}, {"id": "542302", "stem": "A support agent must remember a user’s preferred product line when the user starts a new conversation next month.\nThe team does not want to retrain the model or rebuild a retrieval index.\nWhich service capability should you use?", "options": ["Agent memory", "File search", "Code Interpreter", "Cosmos DB thread store"], "answer": 0, "explanation": "Agent memory is the best fit when an agent needs continuity across sessions, devices, or workflows. It is designed for long-term memory scenarios such as retaining user preferences and personalization signals beyond a single conversation.\nFile search and knowledge grounding help the agent retrieve external documents, but they are not intended to store durable user preferences. A thread store can preserve conversation history, but it is not the same as a managed memory capability that the agent can use for long-term continuity.\nWhy the other options are incorrect:\n• B. File search is used to ground an agent on uploaded or connected documents. It is useful for retrieving information from proprietary files, manuals, or reference material. It does not provide a managed long-term memory layer for remembering user preferences across independent sessions. Using it for personalization would confuse knowledge retrieval with memory.\n• C. Code Interpreter lets an agent run Python code in a sandboxed environment. It is useful for calculations, data analysis, and file-based computation. It does not persist user preferences as managed memory. It also does not solve the requirement to remember a user across future conversations.\n• D. Cosmos DB thread store can be involved in storing conversation thread data in some agent setups. That makes it relevant to persistence, but it is not the correct agent-level memory capability. Persisting raw thread messages is different from giving the agent managed long-term memory. It would also add unnecessary implementation responsibility for this requirement.\nBuild with agents, conversations, and responses\nAgent tools overview for Foundry Agent Service", "topic": "Generative AI and RAG", "source": 42}, {"id": "542131", "stem": "A team is grounding a chatbot on large technical manuals.\nThey want Azure AI Search to chunk the content and generate embeddings during indexing, and they also want vector encoding support in the query pipeline.\nWhich feature should they use?", "options": ["Semantic ranker configuration", "Knowledge store projections", "Shaper skill output", "Integrated vectorization"], "answer": 3, "explanation": "Integrated vectorization is the best answer because Microsoft defines it as an extension of both the indexing and query pipelines in Azure AI Search. It adds vector encoding during indexer-driven indexing and also during queries, which directly matches the requirement in the scenario.\nIt also fits the chunking requirement. Microsoft’s integrated-vectorization documentation states that a skillset can chunk and vectorize content from a supported data source, using Text Split or Document Layout for chunking and an embedding skill for vectorization. Microsoft’s RAG overview also notes that large documents commonly require automatic chunking and that integrated vectorization is the built-in answer for similarity search.\nWhy the other options are incorrect:\n• A. Semantic ranker configuration. Semantic ranker improves relevance by reranking results, but it does not chunk documents or generate embeddings during indexing. Microsoft positions it as a relevance feature, not as a content-ingestion and vectorization mechanism. It can complement a grounding pipeline, but it does not replace integrated vectorization.\n• B. Knowledge store projections. A knowledge store is useful for persisting enriched outputs, but it is not the feature Microsoft documents for automatic chunking and vector generation in the index pipeline. The scenario specifically asks for chunking and embeddings in Azure AI Search itself. That points to integrated vectorization instead of storage projections.\n• C. Shaper skill output. The Shaper skill helps reshape in-memory enrichments, but it is not the primary feature for end-to-end chunking and vector encoding. Microsoft’s integrated-vectorization articles center on skillsets, chunking skills, and embedding skills, not on Shaper as the main answer. Shaper can participate in some pipelines, but it does not satisfy the full requirement on its own.\nIntegrated vectorization using REST APIs\nRAG in Azure AI Search", "topic": "Generative AI and RAG", "source": 39}, {"id": "542121", "stem": "A compliance workflow extracts these fields from policy text:\nrisk_level\ncontrol_owner\ndeadline\ncitation_text\nThe downstream system rejects any response that includes missing keys, extra keys, or the wrong data types.\nWhich control should you apply?", "options": ["JSON mode", "Temperature 0", "Structured outputs", "Few-shot examples"], "answer": 2, "explanation": "Structured outputs is the correct answer because Microsoft says it makes the model follow a JSON Schema you provide as part of the inference call. The documentation explicitly says structured outputs are recommended for extracting structured data and that they guarantee the model matches the supplied schema.\nThis is stronger than asking for “JSON” in natural language because the scenario requires exact keys and types for a downstream parser. JSON mode guarantees valid JSON, but Microsoft documents that it does not guarantee the response will match a specific schema.\nWhy the other options are incorrect:\n• A. JSON mode. JSON mode is a plausible choice because it guarantees the output is valid JSON. However, Microsoft states that JSON mode does not guarantee adherence to a specific schema. Since the workflow rejects missing keys, extra keys, and wrong data types, JSON mode is not strong enough for this requirement.\n• B. Temperature 0. Lowering temperature can reduce output variability, which makes this option sound attractive. But it does not enforce required keys, field types, or schema compliance. This is a sampling control, not a schema-enforcement control.\n• D. Few-shot examples. Few-shot examples can prime the model to imitate a desired extraction pattern, and Microsoft documents them as a way to teach particular behaviors for the current inference. But few-shot prompting still does not give the strict schema guarantees described in the requirement. It improves conditioning, not enforcement.\nHow to use JSON mode with Azure OpenAI in Microsoft Foundry Models\nAzure OpenAI in Microsoft Foundry Models REST API reference", "topic": "Generative AI and RAG", "source": 39}, {"id": "542141", "stem": "A team stores PDF manuals in Azure Blob Storage. They want minimal custom code, automatic chunking during ingestion, embeddings created during indexing, and text queries converted to vectors at query time.\nWhich indexing method best fits this requirement?", "options": ["Push prechunked JSON documents nightly", "Blob indexer without embeddings pipeline", "Semantic ranker plus synonym maps", "Integrated vectorization indexer"], "answer": 3, "explanation": "An integrated vectorization indexer is the best choice because Azure AI Search supports chunking and vector generation in the indexing pipeline when you use an indexer, skillset, and supporting resources. Microsoft also states that integrated vectorization can handle text-to-vector conversion during queries through a vectorizer defined in the index schema.\nThis is a better fit than the push model because Microsoft explicitly says that if AI enrichment or integrated vectorization is required, you must use the pull model with indexers. The scenario asks for minimal custom code and built-in chunking plus embedding behavior, which points directly to indexer-based integrated vectorization.\nWhy the other options are incorrect:\n• A. Push prechunked JSON documents nightly. The push model is flexible and can ingest JSON from almost any source, but Microsoft notes that integrated vectorization and skillsets require the pull model with indexers. This option would force the team to implement more of the chunking and embedding pipeline themselves. It also does not naturally satisfy the “minimal custom code” requirement.\n• B. Blob indexer without embeddings pipeline. A plain Blob indexer can ingest content, but the scenario explicitly requires chunking plus embeddings for retrieval. Without the enrichment and vectorization pieces, the team would load content without the vector workflow needed for semantic similarity queries. That makes this incomplete rather than incorrect in principle.\n• C. Semantic ranker plus synonym maps. Semantic ranker and synonym maps can improve retrieval quality, but they are query-side relevance features rather than the ingestion pipeline asked for here. They do not create embeddings, do not chunk documents, and do not replace indexing-time vectorization. This answer confuses retrieval tuning with indexing design.\nData Import and Ingestion\nIntroduction to Azure AI Search", "topic": "Generative AI and RAG", "source": 39}, {"id": "542280", "stem": "A mortgage-processing app must analyze an application, payslip, and bank statement together. The pipeline must reason across the documents and validate whether the applicant supplied consistent information.\nWhich Content Understanding mode should you configure?", "options": ["Azure AI Search index", "Pro mode", "Single-file task", "Document Intelligence model"], "answer": 1, "explanation": "Pro mode is the best choice because the requirement involves reasoning across multiple related documents. Content Understanding pro mode is designed for advanced document scenarios that need multi-step reasoning, cross-file analysis, and validation against related information.\nA single-file task is better when each file can be processed independently with straightforward schema extraction. In this scenario, the key requirement is not simply extracting fields from one file, but comparing and validating information across multiple inputs.\nWhy the other options are incorrect:\n• A. Azure AI Search index is useful for search and retrieval workflows. It can store indexed content and support retrieval-augmented generation scenarios. However, it is not the Content Understanding pipeline mode that performs multi-document extraction and reasoning. It would typically be downstream of extracted or structured content rather than the analyzer mode itself.\n• C. Single-file task is plausible because it is a Content Understanding task type. However, it is optimized for processing one file at a time with straightforward extraction. It does not match the requirement to reason across a mortgage application, payslip, and bank statement together. Choosing it would force separate processing and leave cross-document validation to another component.\n• D. Document Intelligence model can extract fields from forms and documents. It is useful for document processing, but this question specifically asks about configuring Content Understanding pipeline modes. Document Intelligence is not the correct choice for Content Understanding pro mode behavior. It also does not directly represent the multi-input reasoning mode described in the scenario.\nCreate Content Understanding Standard and Pro tasks\nWhat is Azure Content Understanding?", "topic": "Extraction", "source": 42}, {"id": "542440", "stem": "A RAG application begins returning outdated and weakly relevant policy answers after a document refresh. The Azure AI Search indexer reports partial failures, and vector queries return fewer high-scoring matches than expected.\nWhat should the team investigate first?", "options": ["Model temperature setting", "Indexer execution history", "Content Safety threshold", "Application Insights sampling"], "answer": 1, "explanation": "Indexer execution history is the best first place to investigate because the symptoms began after a document refresh and the search indexer reports partial failures. Ingestion quality, document cracking, enrichment, chunking, embedding generation, and index population all affect the quality of retrieved grounding content.\nWeak relevance in a RAG system is often caused by stale or incomplete indexing, poor chunking, missing fields, failed enrichment, or vector field population issues. The team should verify which documents failed, which enrichment steps failed, and whether the expected searchable and vector fields were populated correctly.\nWhy the other options are incorrect:\n• A. Model temperature can affect response variability, but it does not explain indexer partial failures or fewer high-scoring vector matches. Lowering temperature might make answers more deterministic, but it would not repair missing or stale grounding content. The problem started after a document refresh, which points to ingestion and indexing. This option focuses on generation behavior rather than retrieval health.\n• C. Content Safety threshold settings can block or filter harmful content, but they do not explain stale policy answers or vector retrieval degradation. Safety controls are important for responsible AI, but the scenario provides evidence of search indexer issues. Adjusting moderation thresholds could mask symptoms without fixing the retrieval problem. The relevant issue is ingestion quality and search index health.\n• D. Application Insights sampling affects how much telemetry is collected or retained, not whether the search index has current content. Sampling might make troubleshooting harder if too much telemetry is dropped. However, it would not cause vector queries to return weaker matches. The indexer failure signal is more directly tied to the observed relevance problem.\nVector relevance and ranking in Azure AI Search\nPerformance tips for Azure AI Search", "topic": "Generative AI and RAG", "source": 44}, {"id": "542252", "stem": "A team is preparing to release a generative AI assistant in Microsoft Foundry. The assistant must be tested against a curated dataset before production, and the team needs measurable results for quality, groundedness, and unsafe output risks.\nWhich capability should the team use?", "options": ["Azure Monitor metrics", "Foundry evaluators", "Private endpoint", "Azure Key Vault secrets"], "answer": 1, "explanation": "Foundry evaluators are the best fit because they are designed to assess generative AI outputs using measurable criteria such as quality, safety, groundedness, relevance, and risk-related behaviors. For AI-103, the key distinction is that responsible AI instrumentation is not just operational monitoring; it includes evaluation mechanisms that score and analyze model or agent behavior against datasets and criteria.\nThis question tests whether you can separate runtime infrastructure controls from evaluation instrumentation. Azure Monitor, private endpoints, and Key Vault can all be part of a secure AI solution, but they do not directly evaluate generated responses for responsible AI quality or safety.\nWhy the other options are incorrect:\n• A. Azure Monitor metrics is useful for operational telemetry such as latency, availability, errors, and resource behavior. It can help observe whether an AI workload is healthy in production. However, it does not by itself score response quality, groundedness, or safety against an evaluation dataset. It is plausible because monitoring is part of responsible operations, but it is not the evaluation capability requested here.\n• C. Private endpoint is a networking control that keeps service traffic on a private network path. It helps reduce public exposure and supports secure access patterns. It does not evaluate model responses, explain behavior, or run safety assessments. It is a security control, not responsible AI instrumentation.\n• D. Azure Key Vault secrets helps protect keys, secrets, and certificates. It is important for secure AI application configuration. However, storing secrets securely does not measure whether generated content is safe, grounded, or relevant. It addresses credential protection rather than responsible AI evaluation.\nRun evaluations from the Microsoft Foundry portal\nRisk and Safety Evaluators for Generative AI", "topic": "Generative AI and RAG", "source": 41}, {"id": "542092", "stem": "An enterprise wants Foundry agents to reach Azure AI Search and Azure Storage without using the public internet.\nThey want private IP-based connectivity managed within Foundry and do not want to manage customer-side NIC exposure for those private links.\nWhich design should you use?", "options": ["Public endpoints with IP allowlists", "Service endpoints and API keys", "NAT gateway with outbound rules", "Managed virtual network with managed private endpoints"], "answer": 3, "explanation": "Managed virtual network with managed private endpoints is the best fit because Foundry can create isolated, private IP-based connections from the managed network to dependencies such as Storage and Azure AI Search. Microsoft’s Foundry networking guidance specifically states that managed private endpoints can securely reach required Azure resources without using the public internet.\nThis option also matches the operational constraint in the question because Foundry-managed private endpoints are fully managed by Microsoft and are not represented as NICs in the customer subscription. Public endpoints with IP filtering, service endpoints, or generic outbound control are not equivalent to the private-link-based isolation model described in the official Foundry networking guidance.\nWhy the other options are incorrect:\n• A. Public endpoints with IP allowlists. IP allowlists can reduce exposure, but the traffic still targets public endpoints rather than a private-link path. The question explicitly asks for private IP-based connectivity and no public internet path. That is exactly the gap private endpoints are designed to close.\n• B. Service endpoints and API keys. Service endpoints are not the same as private endpoints, and the option also falls back to key-based authentication instead of the stronger keyless security posture the dot point is about. The question asks for private connectivity managed within Foundry, which aligns with managed private endpoints instead. It also asks about broader security configuration, not just network reachability.\n• C. NAT gateway with outbound rules. A NAT gateway can shape outbound routing, but it does not create private-link access to the target Azure resource. It also does not satisfy the requirement for private IP-based service connectivity into resources like Azure AI Search and Storage. This makes it an infrastructure control, not the right answer to the security design asked here.\nHow to configure network isolation for Microsoft Foundry\nConfigure Virtual Networks for Foundry Tools", "topic": "Generative AI and RAG", "source": 38}, {"id": "542356", "stem": "A team added a self-critique prompt that asks the model to review its own answer before returning it. After release, users still receive confident but unsupported responses from a RAG assistant. Evaluation results show low groundedness but acceptable fluency.\nWhat should the team do next?", "options": ["Gate release on groundedness evaluation", "Increase model temperature for critique", "Replace retrieval with token counting", "Disable context in evaluation data"], "answer": 0, "explanation": "The best next step is to gate release on groundedness evaluation because the observed issue is unsupported responses, not poor wording or fluency. A self-critique prompt can help, but it is not a reliable operational control unless measured against grounding metrics and used as a release criterion.\nGroundedness evaluation checks whether generated answers are supported by the provided context. For a RAG assistant, this is a more relevant quality signal than fluency because a polished answer can still be wrong or unsupported.\nWhy the other options are incorrect:\n• B. Increasing temperature generally increases variability and creativity. That can make unsupported responses worse in a grounded RAG scenario. It does not address the evaluation finding that answers are not sufficiently supported by source context. The issue requires a grounding control, not more generative randomness.\n• C. Token counting can help monitor cost, context length, and prompt size. It does not verify whether the answer is supported by retrieved evidence. Replacing retrieval with token counting would remove the grounding mechanism entirely. This would make the system less capable of producing source-backed answers.\n• D. Disabling context in evaluation data would prevent groundedness evaluation from working correctly. Groundedness requires comparing the response to the source context. Removing the context would make the metric less meaningful or unusable. This would hide the problem rather than fix it.\nMonitoring evaluation metrics descriptions and use cases\nRun evaluations from the Microsoft Foundry portal", "topic": "Generative AI and RAG", "source": 43}, {"id": "542053", "stem": "A healthcare support app translates spoken consultations from English into Spanish. The team says common medical terms are translated too generically and wants the translated output to reflect domain-specific terminology already used in their bilingual documents.\nWhich component should they add?", "options": ["Phrase list", "Azure AI Search index", "Custom Translator", "Custom Speech model"], "answer": 2, "explanation": "Custom Translator is the best answer because Microsoft documents that custom translation lets you build translation systems that understand the terminology used in your own business or industry. It is specifically intended to improve translated output by using your domain-specific bilingual material.\nThat is different from improving recognition of the spoken source audio. The scenario says the translated Spanish terminology is too generic, so the problem is in translation quality and terminology adaptation, not basic speech recognition accuracy.\nWhy the other options are incorrect:\nA. Phrase list. Phrase lists help speech recognition pay extra attention to expected words or phrases during recognition. Microsoft documents them as a recognition-accuracy aid, not as the main mechanism for customizing translated target-language terminology across a domain.\nB. Azure AI Search index. Azure AI Search can support retrieval scenarios, but it is not the documented component for customizing translation output. This option could support grounding in other workloads, but it does not directly solve the translation-terminology problem described here.\nD. Custom Speech model. Custom Speech improves speech-to-text accuracy for specialized audio, jargon, or noise conditions. That is useful when transcription is wrong, but this question says the translated output is too generic, which points to translation customization instead.\nCreate and configure Azure resources for Translator\nImprove recognition accuracy with phrase list", "topic": "Extraction", "source": 38}, {"id": "542431", "stem": "A media company needs one Azure AI capability to extract structured fields from mixed content sources, including contracts, product photos, training videos, and recorded calls. The outputs must be usable by downstream automation and RAG ingestion pipelines.\nWhich capability should the company use?", "options": ["Azure AI Vision Image Analysis", "Azure AI Document Intelligence", "Content Understanding analyzer", "Azure AI Search indexer pipeline"], "answer": 2, "explanation": "A Content Understanding analyzer is the best fit because Azure Content Understanding is designed to process multiple content modalities, including documents, images, video, and audio, into structured outputs. The key requirement is not just OCR, image tagging, or indexing; it is multimodal extraction into a predictable structure.\nThis is especially relevant for AI-103 scenarios where unstructured enterprise content must become usable by agents, automation, or retrieval pipelines. A Content Understanding analyzer provides a reusable configuration for extracting insights and fields from varied content types rather than requiring separate service-specific extraction paths for each modality.\nWhy the other options are incorrect:\n• A. Azure AI Vision Image Analysis is strong for extracting visual features from images. It can support captions, object detection, OCR, and other image-specific analysis. It does not cover documents, videos, and audio as a single structured multimodal extraction capability. It is plausible for the product-photo portion, but it fails the full mixed-content requirement.\n• B. Azure AI Document Intelligence is designed for document extraction scenarios such as forms, invoices, receipts, and layouts. It is not the best single choice for videos, audio, and images together. It would address only part of the company’s content estate. The scenario needs multimodal processing rather than document-focused extraction.\n• D. An Azure AI Search indexer pipeline can ingest and enrich content for search. It is useful after extraction when building searchable indexes or RAG pipelines. However, the question asks for the capability that processes documents, images, videos, and audio into structured outputs. Search indexing is not the primary multimodal understanding layer.\nContent Understanding analyzer reference\nContent Understanding quickstart", "topic": "Generative AI and RAG", "source": 44}, {"id": "542426", "stem": "You are building a RAG ingestion flow for scanned operating manuals. The manuals contain images, headings, tables, and handwritten notes.\nSteps\nGenerate embeddings for the retrieval chunks.\nExtract OCR text and document layout.\nSplit normalized content into chunks.\nIndex text, metadata, and vectors.\nWhat is the correct order?", "options": ["3, 1, 2, 4", "2, 3, 1, 4", "1, 4, 2, 3", "4, 2, 3, 1"], "answer": 1, "explanation": "2 is first because the pipeline must extract readable text and layout from scanned documents before it can create meaningful retrieval units. OCR and layout extraction make the content usable for downstream chunking.\n3 is second because the normalized text and structure should be split into chunks that fit retrieval and embedding limits. 1 is third because embeddings are generated for those chunks. 4 is last because the search index should store the final text, metadata, and vector fields for retrieval.\nWhy the other options are incorrect:\n• A. This sequence chunks before OCR and layout extraction. That fails for scanned manuals because the raw pages may not yet contain usable text. It also creates embeddings before the content has been properly normalized.\n• C. This sequence generates embeddings before extraction and chunking. Embeddings should represent final retrieval chunks, not raw or incomplete source files. Indexing before the content pipeline runs would produce weak or missing grounding data.\n• D. This sequence indexes before extraction, chunking, and embedding. An index should receive processed content and vectors, not unprocessed files. It also leaves embedding generation until after indexing, which prevents the vector fields from being available during retrieval.\nChunk and vectorize by document layout\nIntegrated vectorization in Azure AI Search", "topic": "Generative AI and RAG", "source": 44}, {"id": "542185", "stem": "A team built a document ingestion pipeline in Azure AI Search by using the Document Layout skill. Their chatbot now misses chart meaning, loses table structure, and struggles when relevant content spans more than one page. They want outputs that are easier for LLMs to interpret and better suited for grounded RAG.\nWhat is the best next step?", "options": ["Increase chunk overlap", "Replace with Azure Content Understanding skill", "Add more OCR languages", "Use a larger chat model"], "answer": 1, "explanation": "The best next step is to replace with Azure Content Understanding skill. Microsoft documents that the Azure Content Understanding skill outputs tables and figures in Markdown, making them easier for LLMs to understand, while the Document Layout skill outputs tables and figures as plain text and can lose information. It also states that the Content Understanding skill allows chunks to span multiple pages, whereas the Document Layout skill restricts chunks to a single page.\nThat is a direct match for the symptoms in the scenario: lost table structure, missed chart meaning, and page-bound chunking problems. Switching the enrichment step is more effective than tuning overlap or model size because the core issue is the quality and structure of the extracted representation, not just retrieval tuning or downstream generation power.\nWhy the other options are incorrect:\nA. Increase chunk overlap. Overlap can sometimes help retrieval continuity, but it does not solve the documented limitations described here. If figures and tables are already being output as plain text and chunks are page-bound, more overlap will not restore lost structure or generate richer figure understanding. The extraction representation itself needs to improve first.\nC. Add more OCR languages. OCR language support matters when text recognition is failing because of language mismatch, but that is not the issue described. The problem is that the current skill outputs tables and figures in a less LLM-friendly form and constrains chunks to single pages. Microsoft’s comparison points to the Content Understanding skill, not OCR-language expansion, as the remedy.\nD. Use a larger chat model. A larger model can improve generation quality, but it does not repair weak or lossy extraction. If the grounding data reaching the model lacks structured tables, rich figure understanding, and multi-page chunk continuity, model size does not address the root cause. The bottleneck is upstream in the content-preparation layer.\nBuild a retrieval-augmented generation solution with Azure Content Understanding in Foundry Tools\nWhat is Azure Content Understanding in Foundry Tools?", "topic": "Generative AI and RAG", "source": 40}, {"id": "542024", "stem": "A company is building a compliance assistant.\nThe retrieval layer must do all of the following:\nquery multiple knowledge sources in a single request\ndecompose complex user questions into subqueries\nrun retrieval in parallel across sources\nsemantically rerank results\nexpose the pipeline to a Foundry agent through a standard tool connection\nWhich design is the best fit?", "options": ["File Search with uploaded compliance PDFs", "Foundry IQ knowledge base via MCP", "Azure AI Search tool on one index", "Web search with citations"], "answer": 1, "explanation": "A Foundry IQ knowledge base via MCP is the best fit because Microsoft documents a knowledge base as the top-level object that orchestrates agentic retrieval, defines which knowledge sources to query, and runs the configured retrieval pipeline. Microsoft also documents that an agentic retrieval pipeline can query multiple knowledge sources in a single request, generate subqueries for each source, execute them in parallel, and return unified results.\nIt also fits the agent-tool connection requirement. Microsoft’s Foundry IQ guidance says Foundry Agent Service connects to the knowledge base through MCP, and the knowledge base exposes the knowledge_base_retrieve tool so the agent can ground answers in enterprise data or web sources with source attribution. That is more aligned to the stated architecture than a single-index tool or a file-upload tool.\nWhy the other options are incorrect:\nA. File Search with uploaded compliance PDFs. File Search is useful for user-uploaded or proprietary documents, but the question asks for a retrieval layer that orchestrates across multiple knowledge sources with agentic query planning and parallel retrieval. Microsoft documents File Search as a document-search tool, not as the top-level knowledge-base orchestration layer described in the stem. It is too narrow for the required architecture.\nC. Azure AI Search tool on one index. The Azure AI Search tool is strong when a Foundry agent needs to ground on a specific Azure AI Search index and return citations. However, Microsoft explicitly states that the Azure AI Search tool can target only one index, while the scenario requires multiple knowledge sources and a richer retrieval pipeline with decomposition and orchestration. That makes it a close but insufficient choice.\nD. Web search with citations. Web search is for retrieving current public-web information and citing public sources. The scenario is about an enterprise compliance retrieval layer that orchestrates internal knowledge sources and exposes that pipeline to a Foundry agent. Public-web grounding does not satisfy the multi-source enterprise retrieval and orchestration requirements in the stem.\nAgentic Retrieval Overview\nWhat is Foundry IQ?", "topic": "Generative AI and RAG", "source": 37}, {"id": "542222", "stem": "Refer to:\nhttps://docs.google.com/document/d/10TawY6TIMYV5-pBr-XCeG5E7HBS-1NenFkfXFIct3PM/edit-usp=sharing\nTechnicians report that the mobile app sometimes uploads the same equipment photo twice after losing network connectivity. The backend processes both uploads and creates duplicate maintenance records.\nWhat should Red Hat Industries implement?\nSelect only one answer.", "options": ["Event Grid direct processing", "Queue-backed idempotent ingestion", "Service Bus sessions per technician", "Client retry without server validation"], "answer": 1, "explanation": "Queue-backed idempotent ingestion is the best answer because the workload needs reliable retry handling and duplicate protection. A queue decouples mobile upload events from downstream processing, while idempotency keys or record checks prevent the same upload from creating duplicate maintenance records.\nThe key design point is that retries are expected when connectivity is intermittent. The backend should treat repeated upload attempts as the same logical operation when they share the same asset, file, or request identifier.\nWhy the other options are incorrect:\n• A. Event Grid direct processing is useful for event-driven notifications, but it does not by itself solve duplicate processing. If the same photo is uploaded twice, direct event handling can still process both events unless the backend adds idempotency. It also does not provide the same simple work backlog pattern for retryable processing. This option is plausible for reacting to blob creation, but it is incomplete for the stated issue.\n• C. Service Bus sessions per technician could provide ordered message handling for a technician-specific stream. However, the issue is duplicate maintenance record creation, not message ordering. Sessions would add complexity without directly preventing duplicate records. This option over-engineers the problem and misses the idempotency requirement.\n• D. Client retry without server validation is the cause of the problem, not the solution. Mobile clients can lose connectivity and resend requests, so the server must not trust the client to prevent duplicates. A production ingestion design needs server-side duplicate detection or idempotency. This option fails the operational reliability requirement.\nAzure Functions Queue storage trigger\nStorage queues and Service Bus queues compared", "topic": "Extraction", "source": 41}, {"id": "542173", "stem": "A team wants to build a RAG application over PDF files in Azure Blob Storage by using integrated vectorization and minimal custom code.\nSteps\nCreate a data source connection for the blob content.\nCreate a skillset that chunks text and generates embeddings.\nCreate an index with vector fields and a vectorizer.\nRun ingestion, then query the index to ground model responses.\nWhat is the correct order?", "options": ["1, 2, 3, 4", "3, 1, 2, 4", "2, 1, 3, 4", "1, 3, 2, 4"], "answer": 0, "explanation": "1 is first because the indexing pipeline needs a source connection before content can be pulled into the enrichment flow. Microsoft’s integrated vectorization guidance starts with creating a data source connection to a supported source for indexer-based indexing.\n2 is second because chunking and embedding are part of the enrichment pipeline, so the skillset must be defined before ingestion can process content correctly. 3 is third because the index must then provide the vector fields and vectorizer used for storage and query-time vectorization. 4 is last because the application can only retrieve grounding content after the source, enrichment, and index definitions are in place and ingestion has populated the index.\nWhy the other options are incorrect:\n• B. 3, 1, 2, 4. Creating the index before the data source is possible in some workflows, but this sequence does not reflect the documented integrated vectorization setup flow Microsoft gives for indexer-based ingestion. More importantly, it places the source connection after the target index without establishing the content pipeline first. For an exam-style implementation question, that makes it the weaker sequencing choice.\n• C. 2, 1, 3, 4. A skillset is meant to operate on ingested content and is tied to the indexing workflow. Defining enrichment before the source connection reverses the normal setup logic and makes the pipeline harder to reason about. Microsoft’s documented order begins with the data source, not with the chunking skillset.\n• D. 1, 3, 2, 4. This sequence gets the source connection first, which is reasonable, but it places the index definition before the skillset that performs chunking and vector creation. Microsoft’s integrated vectorization guidance explicitly places the skillset step before the index step in the standard flow it documents. That is why this sequence is close, but still not the best answer.\nText Split skill\nRetrieval augmented generation (RAG) and indexes", "topic": "Generative AI and RAG", "source": 40}, {"id": "542375", "stem": "You are designing a text analysis pipeline for a support platform. Customer messages arrive from web chat, email, and mobile app feedback.\nThe pipeline must:\n• classify sentiment for reporting\n• identify tone for escalation routing\n• detect harmful safety issues\n• find sensitive personal data before storage\n• keep the design service-specific and maintainable\nWhich design best satisfies the requirements?", "options": ["Translator, language detection, Blob lifecycle policies", "Azure AI Search, semantic ranker, index projections", "Sentiment analysis, LLM tone classifier, PII, Content Safety", "Key Vault logging, Azure Policy, Monitor alerts"], "answer": 2, "explanation": "This design best satisfies the requirements because each type of analysis is mapped to the right capability. Sentiment analysis handles customer attitude, a language-model-based classifier can categorize tone when a custom tone taxonomy is required, PII detection identifies sensitive personal data, and Content Safety detects harmful content categories.\nThe important AI-103 distinction is that sentiment, tone, sensitive data, and safety are not the same signal. A message can be negative but safe, polite but contain PII, or neutral but still contain harmful instructions. A strong implementation separates these detection responsibilities so routing, storage, and moderation decisions can be made correctly.\nWhy the other options are incorrect:\n• A. Translator and language detection can help with multilingual preprocessing, but they do not satisfy the main detection requirements. Blob lifecycle policies manage storage tiering and retention, not text classification. This option would not detect harmful content or PII before storage. It also does not provide a meaningful tone classification strategy.\n• B. Azure AI Search and semantic ranking are useful for retrieval and relevance ranking. They do not directly classify incoming messages for sentiment, tone, safety issues, or sensitive content. Index projections can shape indexed content, but they do not replace analysis services. This option confuses searchable indexing with message risk classification.\n• D. Key Vault logging, Azure Policy, and Monitor alerts are governance and operations controls. They help secure and observe resources but do not analyze the meaning or safety of message text. They cannot identify customer sentiment or detect sensitive personal information in message bodies. This option would be useful around the pipeline, not as the pipeline itself.\nAzure AI Language PII detection\nAzure AI Content Safety text moderation", "topic": "Generative AI and RAG", "source": 43}, {"id": "542250", "stem": "You need to choose the correct Content Understanding task configuration for each workflow.\nMatch the following:\nExtract fields from one receipt image\nAnalyze one call recording for summary fields\nValidate invoice details against a contract\nCompare mortgage documents for consistency\nChoices:", "options": ["Pro mode Pro mode Single-file Standard task Azure AI Search", "Single-file Standard task Single-file Standard task Pro mode Pro mode", "Azure AI Search Document Intelligence model Single-file Standard task Pro mode", "Document Intelligence model Pro mode Azure AI Search Single-file Standard task"], "answer": 1, "explanation": "Choice B is correct because single-file Standard tasks are appropriate for straightforward extraction from individual files, including receipt images and call recordings. Pro mode is appropriate when the workflow must reason across documents, validate consistency, or use related documents to make a decision.\nThe important distinction is not whether the input is “AI content,” but whether the pipeline needs cross-file reasoning. Single-file Standard tasks handle independent content analysis across supported content types. Pro mode is reserved for advanced document workflows that need multi-step reasoning, multiple inputs, or reference data.\nWhy the other options are incorrect:\n• A. This mapping incorrectly uses pro mode for simple single-file extraction tasks. Pro mode adds complexity for scenarios that do not need cross-document reasoning. It also assigns single-file Standard processing to invoice-versus-contract validation, which is exactly where pro mode is more appropriate. Azure AI Search is not the Content Understanding task mode for comparing mortgage documents.\n• C. This mapping confuses downstream indexing and separate document services with Content Understanding task configuration. Azure AI Search can support retrieval after content is extracted or indexed, but it is not the correct task mode for a receipt image. Document Intelligence can process documents, but the question asks for Content Understanding pipeline configuration. The mapping partially identifies pro mode for mortgage comparison, but the other assignments are misaligned.\n• D. This mapping overuses unrelated or misplaced services. Document Intelligence may extract fields from documents, but it is not the Content Understanding single-file task configuration requested here. Pro mode is not the right choice for one call recording because pro mode is focused on advanced document reasoning. Assigning a single-file Standard task to mortgage document comparison misses the need for cross-document consistency reasoning.\nWhat is Azure Content Understanding?\nCreate Content Understanding Standard and Pro tasks", "topic": "Extraction", "source": 41}, {"id": "542408", "stem": "A team is selecting evaluation metrics for a grounded customer-support assistant.\nMatch the following:\nMeasures whether the answer is supported by retrieved context\nMeasures whether the answer addresses the user query\nMeasures harmful or unsafe content risk\nMeasures invented unsupported claims\nChoices:", "options": ["Groundedness Relevance Safety Fabrication", "Relevance Coherence Groundedness Fluency", "Safety Fabrication Relevance Groundedness", "Coherence Groundedness Fluency Similarity"], "answer": 0, "explanation": "Groundedness evaluates whether an answer is supported by the supplied or retrieved context, which is critical for RAG and grounded assistants. Relevance checks whether the response actually addresses the user query, while safety checks for harmful categories and fabrication targets unsupported invented content.\nThis mapping tests the difference between quality, safety, relevance, and grounding signals. These metrics are related, but they are not interchangeable; a response can be fluent and still ungrounded, or relevant and still unsafe.\nWhy the other options are incorrect:\n• B. This mapping incorrectly places relevance where groundedness belongs. Coherence and fluency are quality dimensions, but they do not directly prove that retrieved context supports the answer. Groundedness is also misplaced under harmful content risk. The option sounds plausible because all labels are evaluation-related, but the mappings do not match the evaluation goals.\n• C. Safety is not the metric for checking support from retrieved context. Fabrication is also not the same as query relevance, even though fabricated answers can appear responsive. Relevance and groundedness are reversed in effect across the mapping. This option confuses risk categories with retrieval-support and answer-fit metrics.\n• D. Coherence and fluency assess readability and logical flow, not context support or unsafe content risk. Similarity may be useful in some evaluation scenarios, but it is not the direct metric for detecting fabricated unsupported claims. The mapping fails the core grounded-assistant requirements. It emphasizes surface quality rather than the requested evaluation dimensions.\nEvaluating generative AI applications", "topic": "Generative AI and RAG", "source": 44}, {"id": "542442", "stem": "Refer to:\nhttps://docs.google.com/document/d/1ENASvCHfdLcmLCbNaDDClGWnxkItxJw2OQHw6EpbP9M/edit-usp=sharing\nContoso needs generated responses to use approved policy documents and product guides as grounding data. Customer service agents must receive responses with relevant source references, and the retrieval layer must support keyword and semantic matching across policy wording variations.\nWhich component should Contoso include in the design?", "options": ["Azure Blob index tags", "Azure SQL full-text search", "Azure AI Search", "Azure Container Apps ingress"], "answer": 2, "explanation": "Azure AI Search is the best fit because Contoso needs a retrieval layer that can index enterprise documents and support grounded generative AI responses. It can support full-text, vector, and hybrid retrieval patterns, which are important when users ask questions that do not exactly match the wording in policy documents.\nBlob Storage is still useful as the document source, but it is not the retrieval engine for grounded question answering. The case study specifically requires approved enterprise documents, hybrid retrieval, vector search, and source references, which aligns directly with Azure AI Search.\nWhy the other options are incorrect:\n• A. Azure Blob index tags are useful for basic object metadata and lifecycle organization, but they do not provide semantic retrieval for grounded AI answers. They cannot perform hybrid search across document chunks. They also do not provide ranking, vector similarity, or retrieval features needed for RAG-style responses. This option confuses storage metadata with a searchable grounding layer.\n• B. Azure SQL full-text search can search structured or relational content, but it is not the best fit for indexing mixed policy documents, PDFs, and product guides from Blob Storage for generative AI grounding. It does not provide the same native AI search capabilities for vector and hybrid retrieval. It would also add unnecessary data movement and schema design overhead for document-heavy content. This option is plausible only if the data were primarily relational.\n• D. Azure Container Apps ingress controls how traffic reaches containerized workloads. It does not index documents or retrieve grounding passages for a model. It might host the backend API, but it is not responsible for document ranking, semantic matching, or source retrieval. This option confuses application hosting with search and retrieval.\nHybrid search in Azure AI Search\nVector search in Azure AI Search", "topic": "Generative AI and RAG", "source": 44}, {"id": "542034", "stem": "A global support assistant uses Azure AI Search as its grounding store. The engineering lead wants a monitoring design that meets all of the following requirements:\nDetect failed or skipped documents during scheduled ingestion\nAlert when search latency or throttling increases\nLet engineers inspect user query strings and identify long-running searches\nUse managed Azure capabilities with minimal custom code\nWhich design best meets the requirements?", "options": ["Frontend console logs and weekly Search Explorer reviews", "Azure Monitor alerts plus Log Analytics diagnostics", "Customer-managed keys and service tags", "Blob versioning with manual index rebuilds"], "answer": 1, "explanation": "Azure Monitor alerts plus Log Analytics diagnostics is the best answer because Microsoft documents that Azure AI Search integrates with Azure Monitor for metrics and alerts, including search latency and throttled search queries percentage. Microsoft also documents that, for longer retention and for operational analysis such as query strings and long-running queries, you should enable diagnostic logging and route the data to a Log Analytics workspace.\nThis design also aligns with ingestion-quality monitoring. Indexer run status, warnings, and failed document visibility come from indexer monitoring surfaces, while platform metrics and diagnostic logs provide the broader operational view needed for index health and relevance-performance investigation. Together, these services satisfy the full requirement set with minimal custom instrumentation.\nWhy the other options are incorrect:\nA. Frontend console logs and weekly Search Explorer reviews. This approach is too manual and too incomplete for production monitoring. Console logs from the frontend do not provide Azure AI Search platform metrics, ingestion execution history, or centralized operational analysis of service telemetry. Weekly manual reviews also fail the requirement for timely detection and alerting.\nC. Customer-managed keys and service tags. These are useful security and network-governance concepts, but they do not provide observability for ingestion failures, throttling, latency, or query-string analysis. The question is about monitoring coverage, not encryption or traffic classification. This option strengthens security posture without satisfying the operational monitoring requirements.\nD. Blob versioning with manual index rebuilds. Blob versioning can help protect source content, but it does not provide direct monitoring of indexer health, search latency, throttling, or query diagnostics. Manual rebuilds are also reactive and operationally expensive compared with native monitoring plus alerting. This choice addresses recovery mechanics more than ongoing health monitoring.\nMonitor queries in Azure AI Search\nMonitor indexer status and results", "topic": "Generative AI and RAG", "source": 37}, {"id": "542310", "stem": "Refer to:\nhttps://docs.google.com/document/d/1OOAvXtRkR0_VHHsLi486CG0AFxyqZVTDWRz1Kfq2KK0/edit-usp=sharing\nYou need to satisfy BR4 and C3.\nA single technician report can describe a hydraulic leak, an electrical warning, and a procedural breach. The classification output must contain every applicable category. Most training reports are in English, but the same project must process Japanese and French reports.\nWhich project configuration should you create?", "options": ["Custom named entity recognition", "Multilingual custom single-label classification", "Multilingual custom multi-label classification", "Conversational language understanding"], "answer": 2, "explanation": "Custom multi-label text classification permits more than one class to be assigned to the same document. This is required because a single report can describe several unrelated safety issues. A single-label project would force the model to select one category and discard other applicable classifications.\nPinnacle should enable the multilingual option when the project is created and select the language used by most training documents as the project language. Multilingual custom text classification enables one project to process supported languages rather than requiring one project per language. Pinnacle can add representative Japanese and French training examples if evaluation identifies language-specific performance gaps.\nWhy the other options are incorrect:\nA. Custom named entity recognition extracts labelled text spans such as identifiers, component names, or locations. It does not assign one or more document-level safety categories to an entire report. Pinnacle could use it to identify aircraft registrations or part numbers, but that is not BR4. The required task is document classification.\nB. Multilingual custom single-label classification supports one project across languages. However, it returns one classification for each report. Reports containing several issue types would lose valid categories or require artificial combined classes. That design would not satisfy the multi-category requirement.\nD. Conversational language understanding predicts intents and extracts entities from conversational utterances. It is useful for routing commands or interpreting user requests. The input in this scenario is a complete technician report that requires multiple document-level labels. CLU is therefore not the correct project type.\nCreate a custom classification project\nDesign a classification schema", "topic": "Extraction", "source": 42}, {"id": "542370", "stem": "You are preparing a procurement assistant for a controlled pilot. The assistant answers questions from contract PDFs, summarizes supplier terms, and recommends next actions.\nThe release board requires evidence that the app has been tested for:\n• answers unsupported by source documents\n• poor response quality\n• unsafe generated content\n• repeatable scoring against a fixed test dataset\n• comparison between two model deployments\nWhich approach should you recommend?", "options": ["Application Insights availability tests", "Azure AI Search semantic ranker", "Manual review of random chats", "Foundry evaluation with built-in evaluators"], "answer": 3, "explanation": "Foundry evaluation with built-in evaluators is the strongest choice because it supports repeatable testing against datasets and can measure quality, RAG behavior, and safety. It can be used to compare model or application outputs before release rather than relying on subjective sampling.\nThe requirements include multiple evaluation dimensions: fabrication detection, quality, safety, and comparison between deployments. Built-in evaluators in Foundry are designed for this kind of structured pre-production assessment.\nWhy the other options are incorrect:\n• A. Application Insights availability tests can confirm that an endpoint responds and meets basic availability expectations. They do not determine whether the assistant fabricated a supplier clause or summarized a contract incorrectly. They also do not provide built-in model-quality or safety scoring. This option addresses operational uptime, not generative AI evaluation quality.\n• B. Azure AI Search semantic ranker can improve the ranking of retrieved search results. It is valuable in a RAG pipeline, especially when retrieval quality affects grounding. However, it is not an evaluation framework for measuring generated output quality or safety. It also does not compare model deployments against a fixed test dataset by itself.\n• C. Manual review of random chats can provide useful human feedback, but it is not the best answer for the stated requirements. Random review is hard to reproduce and does not provide consistent evaluator scoring across model deployments. It can miss edge cases and safety risks if the sampled conversations are too narrow. Manual review may supplement evaluation, but it should not replace structured Foundry evaluation.\nRisk and Safety Evaluators for Generative AI\nRetrieval-augmented Generation evaluators", "topic": "Extraction", "source": 43}, {"id": "542265", "stem": "You are designing a procurement assistant for a large enterprise. The agent must answer questions from a curated corpus of contracts, policy PDFs, and supplier documents.\nRequirements:\n• Store the searchable corpus in an organization-managed index\n• Support vector retrieval and keyword retrieval\n• Use semantic ranking where appropriate\n• Refresh the grounding content from a nightly ingestion pipeline\n• Avoid using public web grounding\nWhich knowledge integration service should you choose?", "options": ["File search vector store", "Azure AI Search", "Agent memory", "Web search tool"], "answer": 1, "explanation": "Azure AI Search is the strongest fit for an enterprise-managed retrieval index that supports vector search, keyword search, and semantic ranking. It is commonly used as the grounding knowledge store for RAG-style applications when the organization needs control over indexing, ingestion, and retrieval behavior.\nFile search is useful when an agent needs to search uploaded files or a managed vector store with less custom retrieval infrastructure. This scenario requires a more controlled enterprise search index with nightly ingestion and hybrid retrieval, which aligns better with Azure AI Search.\nWhy the other options are incorrect:\n• A. File search vector store is plausible because it can ground an agent on documents. It works well for uploaded files and agent-managed document retrieval. However, the scenario asks for an organization-managed index with hybrid retrieval and semantic ranking control. Azure AI Search gives stronger indexing and retrieval control for this enterprise corpus.\n• C. Agent memory is for retaining useful long-term context such as user preferences or prior interaction signals. It is not the right place to store a large searchable procurement corpus. Memory does not replace an enterprise retrieval index. Using memory here would mix personalization with knowledge grounding.\n• D. Web search tool is intended for grounding on public web content. The requirement explicitly says to avoid public web grounding. It also does not provide an organization-managed private index. It would fail both the privacy and retrieval-control requirements.\nBaseline Microsoft Foundry Chat Reference Architecture\nUse your own resources in Foundry Agent Service", "topic": "Generative AI and RAG", "source": 41}, {"id": "547637", "stem": "{\n“name”: “manuals-indexer”,\n“dataSourceName”: “manuals-blob-datasource”,\n“targetIndexName”: “manuals-rag-index”,\n“skillsetName”: “manuals-rag-skillset”,\n“parameters”: {\n“configuration”: {\n“dataToExtract”: “contentAndMetadata”,\n(MISSING CONFIG)\n}\n},\n“fieldMappings”: [\n{\n“sourceFieldName”: “metadata_storage_path”,\n“targetFieldName”: “source_url”\n}\n],\n“outputFieldMappings”: [\n{\n“sourceFieldName”: “/document/merged_text”,\n“targetFieldName”: “content”\n}\n]\n}\nWhich configuration should replace (MISSING CONFIG)?", "options": ["\"parsingMode\": \"jsonArray\"", "\"queryType\": \"semantic\"", "\"imageAction\": \"generateNormalizedImages\"", "\"scoringProfile\": \"ocrBoostProfile\""], "answer": 2, "explanation": "Correct\nOption C.\n\"imageAction\": \"generateNormalizedImages\"\nThis is correct because when configuring an indexer in Azure Cognitive Search, the\nimageAction\nparameter defines how images are processed. Setting it to\n\"generateNormalizedImages\"\nensures that images are normalized and included in the index. This is a valid configuration option under the\nparameters.configuration\nsection, alongside\ndataToExtract\n.\nIncorrect\nOption A.\n\"parsingMode\": \"jsonArray\"\nNot correct because\nparsingMode\napplies to JSON document parsing, not to blob content extraction in this context. It is not relevant for extracting content and metadata from blob storage.\nOption B.\n\"queryType\": \"semantic\"\nNot correct because\nqueryType\nis a search query parameter, not an indexer configuration setting. It belongs to query execution, not indexer setup.\nOption D.\n\"scoringProfile\": \"ocrBoostProfile\"\nNot correct because scoring profiles are defined at the\nindex level\nto influence ranking, not within the indexer configuration.", "topic": "Generative AI and RAG", "source": 43}, {"id": "541985", "stem": "An enterprise is building eight specialized agents for legal, finance, HR, procurement, and engineering teams.\nThe knowledge architecture must:\nAllow several agents to reuse the same retrieval layer.\nCombine multiple enterprise knowledge sources.\nSupport query decomposition for complex questions.\nProvide citation-backed retrieval.\nPreserve source-level security restrictions where supported.\nAvoid maintaining a separate duplicate vector store for every agent.\nWhich component should form the reusable retrieval layer?", "options": ["Shared File Search vector store for every agent", "Azure AI Search agentic-retrieval knowledge base", "Azure AI Search tool attached separately per agent", "Fine-tuned model containing synchronized knowledge snapshots"], "answer": 1, "explanation": "An Azure AI Search knowledge base is designed as a top-level reusable object for agentic retrieval. A knowledge base can reference one or more knowledge sources and orchestrate query-time retrieval, including query planning and decomposition for complex conversational requests. Microsoft also positions Azure AI Search as the foundation behind Foundry IQ’s reusable enterprise knowledge layer.\nThis architecture keeps knowledge retrieval separate from the individual agent definitions. Agents can consume the managed retrieval layer rather than each carrying independent copies of the same data, improving maintainability and allowing retrieval configuration to evolve independently of agent prompts. The current Azure AI Search agentic-retrieval API provides generally available knowledge-base capabilities programmatically, although some broader portal and source integrations remain preview.\nWhy the other options are incorrect:\nA. Shared File Search vector store for every agent. File Search can ground agents on uploaded files and can be appropriate for straightforward private-document scenarios. It does not provide the same multi-source knowledge-base orchestration and query-planning model described in the requirements. Replicating or tightly coupling vector-store content across many agents also increases knowledge-management overhead. The scenario is specifically asking for a reusable enterprise retrieval layer rather than agent-local document grounding.\nC. Azure AI Search tool attached separately per agent. The Azure AI Search agent tool is useful for grounding an individual agent against a Search index and can return citations. Microsoft currently notes that the direct tool targets one index, which makes it less suitable for the stated multi-source managed-knowledge requirement. Repeating tool configuration independently across eight agents also does not provide the central reusable knowledge-base abstraction described in the stem. A knowledge base is therefore the stronger architectural fit.\nD. Fine-tuned model containing synchronized knowledge snapshots. Fine-tuning changes model behavior and can improve performance on particular patterns, but it is not a substitute for retrieval of current enterprise knowledge. Updating source documents would require another model-training lifecycle rather than simply refreshing the retrieval source. Fine-tuning also does not naturally provide document citations or source-level retrieval controls. The scenario calls for RAG-style reusable knowledge, not knowledge baked into model weights.\nAzure AI Search features and capabilities\nRetrieval-augmented generation and indexes", "topic": "Generative AI and RAG", "source": 37}, {"id": "542214", "stem": "A developer is testing a hybrid query for a grounding pipeline.\nThe team wants semantic reranking plus extractive captions and answers from the returned chunks.\nSnippet\n{\n“search”: “reset a leaked service principal credential”,\n“vectorQueries”: [\n{\n“kind”: “vector”,\n“fields”: “contentVector”,\n“vector”: [0.018, -0.044, 0.012, 0.009],\n“k”: 50\n}\n],\n“captions”: “extractive|highlight-true”,\n“answers”: “extractive|count-3”,\n“select”: “title, content, source”,\n(MISSING CONFIG)\n}\nWhich missing configuration best completes the query?", "options": ["\"queryType\":\"semantic\",\"semanticConfiguration\":\"grounding-config\"", "\"orderBy\":\"lastUpdated desc\"", "\"search\":\"*\"", "\"suggest\":\"reset\""], "answer": 0, "explanation": "This is the correct completion because Microsoft says semantic ranking queries need semantic parameters, and examples show queryType set to semantic together with semanticConfiguration. Microsoft also documents that captions and answers are returned as part of semantic ranking requests, not plain hybrid retrieval without semantic setup.\nThe existing snippet is already close to a valid hybrid grounding query because it includes both search and vectorQueries. Adding semantic query settings is what enables semantic reranking and the extractive caption and answer behavior the team wants. Microsoft’s hybrid examples also show k of 50 when semantic ranker is used so the reranker has enough input candidates.\nWhy the other options are incorrect:\n• B. “orderBy”:”lastUpdated desc”. Microsoft says explicit ordering on specific fields overrides relevance scores and is incompatible with semantic ranking. If you apply semantic ranking over ordered results, Azure AI Search returns an HTTP 400 error. So this option actively conflicts with the goal of semantic grounding quality.\n• C. “search”:”*”. Microsoft states that search=* or an empty search string bypasses relevance scoring and therefore cannot be semantically ranked. Semantic ranking requires plain-text query input that can be evaluated for relevance. This would break the intended semantic behavior instead of enabling it.\n• D. “suggest”:”reset”. Suggest functionality is for suggestion-style experiences, not semantic reranking in a search request. Microsoft’s semantic query documentation and hybrid query examples do not use suggest to enable semantic captions, answers, or reranking. It is unrelated to the missing grounding configuration here.\nCreate a Hybrid Query – Azure AI Search\nCreate a Vector Query – Azure AI Search", "topic": "Generative AI and RAG", "source": 40}, {"id": "542444", "stem": "Refer to:\nhttps://docs.google.com/document/d/1ENASvCHfdLcmLCbNaDDClGWnxkItxJw2OQHw6EpbP9M/edit-usp=sharing\nContoso needs to extract loan applicant details, income fields, document identifiers, and supporting evidence values from scanned and digital application documents. The extraction process must be validated before it is used by the production review workflow.\nSteps\nReview extraction accuracy and improve labels.\nLabel representative loan documents.\nTrain a custom extraction model.\nAnalyze production documents from the backend API.\nWhat is the correct order?", "options": ["3, 2, 1, 4", "2, 1, 3, 4", "2, 3, 4, 1", "2, 3, 1, 4"], "answer": 3, "explanation": "2 is first because Contoso must provide representative loan documents and label the fields that the model needs to extract. A custom extraction model depends on labeled examples so the service can learn the target schema and field locations.\n3 is second because the labeled examples are used to train the custom extraction model. 1 is third because Contoso must evaluate the model’s extraction quality and refine labels or examples before production use. 4 is last because the backend API should call the validated model only after the model has been trained and reviewed.\nWhy the other options are incorrect:\n• A. This sequence trains the model before the documents are labeled. That does not match the custom extraction workflow because the model needs labeled examples first. Training before labeling would not provide the service with the target fields to learn. The later validation and production analysis steps are reasonable, but the first two steps are reversed.\n• B. This sequence reviews extraction accuracy before the model is trained. There is no trained extraction model to evaluate at that point. Reviewing labels before training can be part of quality control, but that is not the same as validating model output. The sequence delays training until after a review step that depends on training results.\n• C. This sequence runs production document analysis before reviewing extraction accuracy. That creates operational risk because incorrect field extraction could enter the loan review workflow. The business goal is to reduce manual review time, but not by skipping validation. Production use should follow model evaluation and refinement.\nBuild a custom Document Intelligence mode\nTrain a custom extraction model", "topic": "Extraction", "source": 44}, {"id": "542432", "stem": "{\n“description”: “Extract invoice data for downstream agent validation.”,\n“scenario”: “document”,\n“fieldSchema”: {\n“fields”: {\n“invoiceNumber”: {\n“type”: “string”,\n“description”: “The invoice identifier printed on the document.”\n},\n“vendorName”: {\n“type”: “string”,\n“description”: “The legal name of the vendor.”\n},\n“invoiceTotal”: {\n“type”: “number”,\n“description”: “The final invoice amount including tax.”\n},\n“lineItems”: {\n“type”: “array”,\n“description”: “Purchased items, quantities, unit prices, and totals.”\n}\n}\n},\n(MISSING CONFIG)\n}\nWhich configuration best supports the requirement?", "options": ["\"output\": \"plainText\"", "\"structuredOutput\": true", "\"imageFeatures\": [\"caption\", \"objects\", \"tags\"]", "\"chunkingMode\": \"fixedSizeMarkdownSegments\""], "answer": 1, "explanation": "Structured output is the best configuration goal because the downstream agent and automation steps need predictable fields such as invoiceNumber, vendorName, invoiceTotal, and lineItems. JSON-like structure enables validation, exception routing, and deterministic workflow decisions more reliably than a free-form text response.\nFor RAG and automation workloads, clean structured outputs reduce post-processing complexity. The field schema tells the analyzer what information to extract, while structured output ensures the extracted data is returned in a machine-readable form that downstream systems can reason over.\nWhy the other options are incorrect:\n• A. Plain text may be readable by a person, but it is not ideal for validation and workflow routing. The agent would need additional parsing logic to recover invoice fields. That increases fragility and makes failures harder to detect. It is plausible for summarization, but not for predictable automation.\n• C. Image features such as captions, objects, and tags are useful for visual analysis. They do not directly produce invoice-specific fields such as invoice number, vendor name, total, and line items. The scenario is document extraction into a schema, not general image description. This option confuses visual enrichment with structured business-field extraction.\n• D. Fixed-size Markdown chunking can be useful for RAG ingestion and text segmentation. It does not by itself guarantee structured JSON fields for automation. Chunked Markdown may help retrieval, but it is weaker for deterministic validation and routing. The requirement emphasizes clean structured output rather than chunk size.\nContent Understanding best practices\nContent Understanding analyzer reference", "topic": "Extraction", "source": 44}, {"id": "542327", "stem": "An Azure AI Search indexer processes documents through:\ndocument cracking\nOCR\nText Split\na custom Web API skill\noutput field mappings into the search index\nThe indexer reports Success, but a known test document still produces an empty customerId.\nThe engineer must:\nexecute the enrichment pipeline against that specific source document\ninspect intermediate nodes in the enriched document tree\ninspect the inputs and outputs of individual skills\nmodify an annotation path or skill mapping experimentally\nvalidate the change before committing it to the production skillset\nWhat should the engineer do first?", "options": ["Start an Azure AI Search Debug Session against the affected document", "Set maxFailedItems=0, rerun the production indexer, and inspect its execution history", "Query the resulting index with debug=all to inspect the missing enrichment contribution", "Clone the skillset and index, then execute the complete indexer against the full data source"], "answer": 0, "explanation": "A Debug Session is a cached indexer and skillset execution scoped to a single document. Microsoft designed it specifically for interactive examination of the enrichment tree, skill inputs and outputs, annotation paths, and experimental skillset changes before those changes are committed back to the production skillset.\nWhy the other options are incorrect\nB. Reducing maxFailedItems can make an indexer run fail more aggressively when document-level errors occur, and execution history is valuable for identifying warnings or failures. However, the indexer is already succeeding and the requirement is to inspect the actual intermediate enrichment state for one known document. Execution history does not provide the same interactive enriched-document tree and editable skill mappings as a Debug Session. This option improves failure visibility but not the detailed single-document skill debugging required here.\nC. Query-level debug functionality is useful when engineers need to inspect search relevance, including ranking contributions in retrieval scenarios. The missing customerId was produced during indexing and skillset enrichment rather than query-time ranking. No amount of query score decomposition can reveal an intermediate OCR or custom-skill annotation path that never mapped correctly. This option uses a valid Search debugging capability at the wrong stage of the pipeline.\nD. A cloned test environment could eventually be used to validate a revised skillset without touching production resources. However, executing the entire data source is considerably broader than necessary when the failure is already reproducible with one known source document. It also doesn’t inherently provide the interactive visual enriched-tree inspection and node-level editing experience requested by the scenario. This option can support later integration testing but is not the best first diagnostic action.\nSkillset Concepts and Enrichment Trees\nReference Enriched Nodes During Skillset Execution", "topic": "Extraction", "source": 42}, {"id": "542241", "stem": "A Content Understanding custom document analyzer must produce three fields from insurance policies.\nRequirements:\npolicyNumber must reproduce the literal identifier appearing in the source document\nriskClass must be selected from low, medium, or high\nrationale must be newly written from the evidence in the document rather than copied verbatim\nThe field schema contains:\n{\n“fieldSchema”: {\n“fields”: {\n“policyNumber”: {\n“type”: “string”,\n“method”: “(METHOD 1)”\n},\n“riskClass”: {\n“type”: “string”,\n“enum”: [\n“low”,\n“medium”,\n“high”\n],\n“method”: “(METHOD 2)”\n},\n“rationale”: {\n“type”: “string”,\n“method”: “(METHOD 3)”\n}\n}\n}\n}\nWhich mapping should you use?", "options": ["generate, extract, classify", "classify, generate, extract", "extract, generate, classify", "extract, classify, generate"], "answer": 3, "explanation": "Content Understanding supports three field-generation methods. Extract is for values that appear directly in the source, classify is for selecting from predefined categories, and generate is for newly inferred or summarized values. The three requirements therefore map directly to extract, classify, and generate.\nThe completed schema is:\n{\n“fieldSchema”: {\n“fields”: {\n“policyNumber”: {\n“type”: “string”,\n“method”: “extract”\n},\n“riskClass”: {\n“type”: “string”,\n“enum”: [\n“low”,\n“medium”,\n“high”\n],\n“method”: “classify”\n},\n“rationale”: {\n“type”: “string”,\n“method”: “generate”\n}\n}\n}\n}\nWhy the other options are incorrect\nA. It would generate the literal identifier, attempt extraction for an enum classification, and classify the free-form rationale.\nB. The identifier is not a category, the enum should not be freely generated, and the rationale does not need to appear verbatim.\nC. The identifier is correct, but riskClass and rationale have their methods reversed.", "topic": "Extraction", "source": 41}, {"id": "542004", "stem": "A team runs a nightly document summarization pipeline for EU customers. The job is asynchronous, can complete any time within 24 hours, and the company wants the lower-cost batch option while keeping processing within the EU data zone.\nSnippet\nresource account ‘Microsoft.CognitiveServices/accounts@2024-10-01’ existing = {\nname: ‘contoso-foundry’\n}\nresource deployment ‘Microsoft.CognitiveServices/accounts/deployments@2024-10-01’ = {\nname: ‘nightly-eu-batch’\nparent: account\nsku: {\nname: ‘(MISSING CONFIG)’\n}\nproperties: {\nmodel: {\nformat: ‘OpenAI’\nname: ‘gpt-4.1-mini’\nversion: ‘2025-04-14’\n}\nversionUpgradeOption: ‘OnceNewDefaultVersionAvailable’\nraiPolicyName: ‘Microsoft.Default’\n}\n}\nWhich value should replace (MISSING CONFIG)?", "options": ["DataZoneBatch", "GlobalBatch", "DataZoneProvisionedManaged", "DataZoneStandard"], "answer": 0, "explanation": "DataZoneBatch is correct because the scenario asks for asynchronous processing, allows up to 24 hours for completion, and requires processing to remain inside the EU data zone. Microsoft’s deployment type documentation describes Data Zone Batch as the data-zone equivalent of Global Batch, including the large async job pattern and 50% cost savings relative to standard online processing.\nThe other data-zone deployment SKUs serve different workload shapes. DataZoneStandard is for online pay-per-token requests, and DataZoneProvisionedManaged is for reserved-capacity online traffic where throughput predictability matters more than batch economics.\nWhy the other options are incorrect:\n• B. GlobalBatch. GlobalBatch is a valid batch deployment type, so it is a realistic distractor. However, Microsoft states that global deployment types can process inferencing data in any Azure region, which conflicts with the requirement to keep processing within the EU data zone. The batch pattern is right, but the processing boundary is wrong.\n• C. DataZoneProvisionedManaged. This SKU is the provisioned data-zone option, which is designed for reserved model capacity and predictable online throughput. It does not represent the batch deployment type needed for asynchronous overnight processing. Choosing it would solve a different problem and would likely increase cost without matching the workload pattern.\n• D. DataZoneStandard. DataZoneStandard keeps processing within the correct zone, but it is still an online standard deployment type. The scenario specifically wants the lower-cost batch option and accepts non-real-time turnaround, which maps to DataZoneBatch instead. This option misses the cost-and-pattern requirement even though it satisfies the data boundary.\nAzure OpenAI in Microsoft Foundry Models quotas and limits\nMicrosoft Foundry Models overview", "topic": "Extraction", "source": 37}, {"id": "542061", "stem": "Refer to:\nhttps://docs.google.com/document/d/1wSTDGPPYkobjsp-NYn4OyjyuT_nnw1iF7VBmLnWAZYE/edit-usp=sharing\nThe Azure AI Search service uses its system-assigned managed identity to read the approved storage container. A shared private link provides private outbound connectivity from the search service to the storage account.\nThe indexer currently runs only when an administrator starts it. You must satisfy BR2 with minimal operational overhead.\nSnippet\n{\n“name”: “policy-document-indexer”,\n“dataSourceName”: “approved-policy-storage”,\n“targetIndexName”: “policy-knowledge-index”,\n“parameters”: {\n“configuration”: {\n“dataToExtract”: “contentAndMetadata”,\n“parsingMode”: “default”\n}\n},\n“schedule”: {\n(MISSING CONFIG)\n}\n}\nWhich configuration should replace (MISSING CONFIG)?", "options": ["\"interval\": \"PT1M\"", "\"interval\": \"PT5M\"", "\"interval\": \"PT30M\"", "\"interval\": \"PT15M\", \"disabled\": true"], "answer": 1, "explanation": "An Azure AI Search indexer can be scheduled as frequently as every five minutes. Azure Storage provides built-in change detection based on source changes, so each scheduled execution can process new and modified documents rather than rebuilding the complete index. A five-minute interval gives sufficient time for indexing to finish within the 15-minute business target under normal operating conditions.\nThe data-source connection can identify the storage account by resource ID and use the search service’s managed identity instead of an account key. When the storage account is private, a shared private link enables the indexer’s outbound connection to remain on a private path. This design meets the freshness, private-networking, and credential-free requirements without introducing an Event Grid and Azure Functions ingestion pipeline.\nWhy the other options are incorrect:\nA. One minute is below the minimum supported Azure AI Search indexer schedule interval. The configuration would not be accepted as a valid schedule. Reducing the interval below the service limit is therefore not a valid way to meet BR2. A supported five-minute schedule provides adequate time for several attempts within the business window.\nC. A 30-minute schedule cannot guarantee that a document becomes searchable within 15 minutes. A document committed immediately after an indexer run could wait almost 30 minutes before the next execution even begins. Indexing time would add further delay. This option therefore fails BR2 despite being operationally simple.\nD. The 15-minute interval is theoretically close to the business limit, but setting disabled to true suspends scheduled execution. The indexer would not run automatically after the configuration is saved. Even without the disabled property, a document could wait almost 15 minutes before indexing begins. The design leaves no allowance for processing duration or a transient failed run.\nConnect Azure AI Search to Storage using managed identity\nMake outbound connections through a shared private link", "topic": "Extraction", "source": 38}, {"id": "542436", "stem": "A team is building a new support copilot for complex, conversational troubleshooting questions. Users often ask multi-part questions, require citation-backed answers, and benefit from query decomposition. There is no strict GA-only requirement.\nProblem:\nThe team needs the retrieval approach with the strongest relevance for complex conversational questions and citation-oriented responses.\nProposed solution:\nUse agentic retrieval instead of classic RAG.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "Yes. Agentic retrieval is designed for complex conversational RAG scenarios where an LLM can break a user request into focused subqueries, retrieve relevant information, and return structured results that are useful for grounded generation. The scenario specifically asks for stronger relevance, multi-part question handling, and citation-oriented responses, which aligns with agentic retrieval.\nClassic RAG is still a good choice when simplicity, speed, GA-only requirements, or fine-grained orchestration control are more important than advanced retrieval planning. Those constraints are not the dominant requirements in this scenario. Because the team is building a new support copilot and does not require GA-only features, agentic retrieval is the better fit.\nWhy the other options are incorrect:\n• B. Choosing No would be reasonable if the scenario required GA-only functionality, maximum speed, or preserving existing custom query orchestration. It would also be reasonable if the questions were simple lookups where classic hybrid retrieval was sufficient. However, the stated requirements emphasize complex conversational questions, query decomposition, and citation-oriented answers. Those requirements match the strengths of agentic retrieval.\nRetrieval Augmented Generation in Azure AI Search\nQuickstart: Agentic retrieval", "topic": "Generative AI and RAG", "source": 44}, {"id": "542443", "stem": "import os\nfrom azure.identity import DefaultAzureCredential\nfrom azure.search.documents import SearchClient\nsearch_endpoint = os.environ[“SEARCH_ENDPOINT”]\nindex_name = os.environ[“SEARCH_INDEX_NAME”]\ndef create_search_client() -> SearchClient:\ncredential = (MISSING CONFIG)\nreturn SearchClient(\nendpoint=search_endpoint,\nindex_name=index_name,\ncredential=credential\n)\ndef search_policy_chunks(query: str):\nclient = create_search_client()\nresults = client.search(\nsearch_text=query,\ntop=5,\nselect=[“title”, “chunk”, “sourceUri”]\n)\nreturn [\n{\n“title”: result[“title”],\n“chunk”: result[“chunk”],\n“source”: result[“sourceUri”]\n}\nfor result in results\n]\nWhich configuration should replace the missing configuration?", "options": ["AzureKeyCredential from app settings", "DefaultAzureCredential()", "ClientSecretCredential from environment variables", "InteractiveBrowserCredential with user prompt"], "answer": 1, "explanation": "DefaultAzureCredential is the correct choice because it can use the managed identity assigned to the production workload when the application runs in Azure. This satisfies the requirement to avoid stored secrets and API keys in application configuration.\nThe application must still be granted the appropriate Azure role permissions for Azure AI Search. The code change alone does not grant access, but it enables the application to request Microsoft Entra tokens using the managed identity instead of a static secret.\nWhy the other options are incorrect:\n• A. AzureKeyCredential from app settings uses an API key stored in configuration. That directly violates the case study constraint that production workloads must not store secrets or API keys. It might technically authenticate to Azure AI Search, but it does not satisfy Contoso’s security requirement. This option is a common shortcut that fails the identity design constraint.\n• C. ClientSecretCredential from environment variables uses an application registration and client secret. That still requires storing a secret somewhere in the runtime environment. It also creates secret rotation and operational management overhead that managed identity avoids. This option is plausible for some service-to-service authentication scenarios, but not for this case study.\n• D. InteractiveBrowserCredential with user prompt is not appropriate for a production backend service. It expects interactive user authentication and is mainly useful in development or local tooling scenarios. A Container Apps backend should authenticate non-interactively. This option fails the production automation requirement.\nConfigure managed identities for Azure AI Search\nAzure Identity client library for Python", "topic": "Extraction", "source": 44}, {"id": "542282", "stem": "An engineer is creating a Content Understanding analyzer for invoice validation. The analyzer must compare an invoice with a related purchase order and use a supplier policy document as reference data.\nSnippet\n{\n“analyzerId”: “invoice_validation_pro”,\n“description”: “Validate invoice consistency against purchase order and supplier policy.”,\n“scenario”: “document”,\n“analysisMode”: “(MISSING CONFIG)”,\n“fieldSchema”: {\n“fields”: {\n“invoiceNumber”: {\n“type”: “string”,\n“description”: “Invoice number shown on the submitted invoice.”\n},\n“purchaseOrderMatch”: {\n“type”: “boolean”,\n“description”: “Whether invoice totals and PO totals are consistent.”\n},\n“reviewReason”: {\n“type”: “string”,\n“description”: “Reason the invoice should be sent for manual review.”\n}\n}\n},\n“referenceData”: [\n{\n“name”: “supplier_policy”,\n“source”: “supplier_policy.pdf”\n}\n]\n}\nWhich value should replace (MISSING CONFIG)?", "options": ["\"standard\"", "\"pro\"", "\"prebuilt-image\"", "\"documentSearch\""], "answer": 1, "explanation": "“pro” is the correct configuration because the analyzer must use reference data and reason across related documents. The scenario is not asking for simple extraction from a single invoice; it requires validation between an invoice, purchase order, and supplier policy.\nThis question tests whether you recognize when Content Understanding pro mode is required. Pro mode is designed for complex document workflows that need multi-step reasoning, reference data, and multi-input document analysis. Standard mode is better for straightforward extraction or schema-aligned processing when each file can be handled independently.\nWhy the other options are incorrect:\n• A. “standard” would be appropriate for a single-file extraction task or simpler schema-aligned processing. It is cost-effective and lower latency for straightforward workflows. However, this analyzer must reason across an invoice, purchase order, and reference policy. Standard mode does not satisfy the reference-data and cross-document reasoning requirement.\n• C. “prebuilt-image” is associated with image analyzer selection, not pro-mode document reasoning. It is plausible in a multimodal Content Understanding context because Content Understanding can process images. However, the input here is a document validation workflow involving invoices, purchase orders, and reference documents. It does not configure pro mode or enable the required reasoning behavior.\n• D. “documentSearch” is related to document search-oriented analyzer behavior, not the analysis mode value for this pro scenario. It may sound plausible because invoices and purchase orders are documents. However, the requirement is not to prepare content for search; it is to validate consistency against related documents and reference data. This option does not select the pro mode pipeline.\nCreate Content Understanding Standard and Pro tasks\nCreate a custom analyzer", "topic": "Extraction", "source": 42}, {"id": "542335", "stem": "A company deploys a customer-service generative AI application that uses Azure AI Search for grounding. The application must be monitored for latency regressions, unsafe response events, and weakening grounding quality over time.\nProblem:\nThe team needs production monitoring that covers both operational health and AI response quality.\nProposed solution:\nSend application traces and dependency telemetry to Azure Monitor, capture safety-filter outcomes, and run scheduled Azure AI Foundry evaluations for groundedness, relevance, and retrieval quality.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it combines operational monitoring with AI-quality evaluation. Azure Monitor and tracing help detect latency regressions, dependency failures, and runtime issues, while safety outcomes capture unsafe prompt or response events.\nScheduled Foundry evaluations address the AI-specific part of the requirement by measuring groundedness, relevance, and retrieval quality over time. That makes the design suitable for detecting drift-like degradation even when the application remains available and responsive.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution covers all stated monitoring areas. It includes operational telemetry for latency and dependencies. It includes safety-filter outcomes for unsafe response events. It also includes scheduled evaluations for grounding and retrieval-quality degradation over time.\nAzure AI Content Safety harm categories\nAzure AI Foundry RAG evaluators", "topic": "Generative AI and RAG", "source": 42}, {"id": "542295", "stem": "A claims application receives PDF claim packets that contain forms, tables, scanned pages, diagrams, and supporting notes. A downstream agent must reason over the packet and must also receive structured values such as claim number, claimant name, incident date, and policy type.\nProblem:\nYou need to implement analyzers that generate structured and Markdown outputs for downstream reasoning.\nProposed solution:\nCreate a Content Understanding custom analyzer based on prebuilt-document, define a fieldSchema for the required fields, enable OCR and layout, configure Markdown-friendly table output, enable figure description where needed, and pass the analyzer result’s Markdown and fields to the downstream agent.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it uses a Content Understanding analyzer to produce both structured fields and a reasoning-friendly document representation. The field schema gives the downstream system predictable extracted values, while OCR, layout, Markdown table output, and figure description improve the agent’s ability to understand the full claim packet.\nThe design also keeps responsibilities separated correctly. Content Understanding handles document extraction and structured output, while the downstream agent uses those outputs for reasoning. That is stronger than asking the agent to infer everything from raw PDFs or unstructured OCR text.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution directly addresses both required output types. It defines structured fields through the analyzer schema and produces Markdown-oriented document content for downstream reasoning. It also accounts for scanned pages, tables, and figures through analyzer configuration. Normal production checks such as validation, confidence review, monitoring, and security are still needed, but the core design satisfies the goal.\nContent Understanding analyzer reference\nQuickstart: Use Content Understanding REST API", "topic": "Extraction", "source": 42}]}, {"id": "08-agents-evaluation", "level": 8, "rank": "Expert", "title": "Scenario lab: agents and evaluation", "minutes": 75, "cheat": "Cheat sheet 2.2 and 2.3 — agents, tools, tuning, and evaluation", "blurb": "The hardest scenarios: tool use, multi-step agents, safeguards, and how you prove quality.", "focus": ["Give an agent a role, a goal, and a tool schema before you give it side effects.", "Use approval for actions that change data. Fully automatic side effects need a strong reason.", "Score retrieval, groundedness, and relevance separately. A fluent answer can still be ungrounded.", "Tracing shows which tool ran, what it returned, and where the time went."], "pool": 150, "questions": [{"id": "542368", "stem": "model_deployment = “gpt-4o-mini-eval”\ntesting_criteria = [\n{\n“type”: “azure_ai_evaluator”,\n“name”: “groundedness”,\n“evaluator_name”: “builtin.groundedness”,\n“initialization_parameters”: {\n“deployment_name”: model_deployment\n},\n(MISSING CONFIG)\n}\n]\nevaluation_job = {\n“display_name”: “weekly-grounding-regression-check”,\n“description”: “Detect grounding quality drift from sampled production traffic.”,\n“testing_criteria”: testing_criteria,\n“data”: “azureml://datastores/workspaceblobstore/paths/eval/weekly.jsonl”\n}\nWhich configuration should replace the missing line?", "options": ["\"data_mapping\": {\"query\": \"{{item.query}}\"}", "\"data_mapping\": {\"context\": \"{{item.context}}\", \"response\": \"{{item.response}}\"}", "\"data_mapping\": {\"connection\": \"{{project.connection}}\", \"index\": \"{{search.index}}\"}", "\"data_mapping\": {\"prompt\": \"{{item.prompt}}\", \"deployment\": \"{{model.name}}\", \"latency\": \"{{run.ms}}\"}"], "answer": 1, "explanation": "The groundedness evaluator needs the generated response and the grounding context to determine whether the answer is supported by the retrieved material. Mapping context and response gives the evaluator the two key pieces needed to judge whether the model fabricated unsupported information.\nThe query can improve some evaluation scenarios, but the core groundedness check is about consistency between the response and its supporting context. This is why the best missing configuration maps the retrieved context and generated response from the evaluation dataset.\nWhy the other options are incorrect:\n• A. Mapping only the query does not provide the generated response or the retrieved context. The evaluator cannot determine whether the answer is grounded if it cannot inspect the answer. It also cannot compare the answer to supporting source material. This option captures user intent but misses the evidence needed for groundedness evaluation.\n• C. Mapping a project connection and search index points to infrastructure configuration, not evaluation sample fields. The groundedness evaluator works on evaluation records, not on the index definition alone. A search index might provide source material, but the evaluator still needs the retrieved context used for each answer. This option confuses system configuration with evaluation data mapping.\n• D. Mapping prompt, deployment, and latency captures operational metadata. That information may help with tracing or performance analysis, but it does not prove whether a response is grounded. Latency is especially unrelated to factual support. This option monitors execution behavior rather than answer-context consistency.\nAzure AI Foundry evaluation SDK\nModel monitoring for generative AI applications", "topic": "Evaluation", "source": 43}, {"id": "541983", "stem": "A developer accesses a Microsoft Foundry environment through the organization’s private network. Network connectivity succeeds, and the developer can view the Foundry resource.\nAttempts to create and test agents inside an existing project fail with an authorization error.\nThe developer currently has:\nReader on the Foundry resource\nNo Foundry data-plane role on the project\nThe developer must:\nBuild and test agents\nUse existing deployed models and connections\nNot deploy models\nNot assign roles\nReceive the minimum additional privileges required\nWhich role should you assign?", "options": ["Contributor on the resource group", "Foundry Project Manager on the resource", "Foundry User on the project", "Foundry Agent Consumer on the project"], "answer": 2, "explanation": "Foundry User is the least-privilege role Microsoft identifies for developers who need to build and test within a Foundry project. It provides the project data actions needed for development while not granting model-management or role-assignment capabilities. Microsoft specifically gives the enterprise mapping of Reader on the Foundry resource plus Foundry User on the project for ordinary development team members.\nThis question also distinguishes authorization from networking. The developer can already reach and view the environment, so assigning a broader infrastructure role or changing private networking would not address the missing project data actions appropriately. The correct remediation is the narrow Foundry project role matching the developer’s actual duties.\nWhy the other options are incorrect:\nA. Contributor on the resource group. Contributor is a powerful Azure control-plane role and can manage many resources within its assigned scope. Microsoft Foundry’s role table does not use Contributor as the normal role for project-level build-and-develop data actions. It would also grant substantially broader infrastructure management rights than this developer needs. The requirement explicitly asks for the minimum privileges required, making Contributor inappropriate.\nB. Foundry Project Manager on the resource. Foundry Project Manager can build and develop, so it would resolve the access problem. However, the role also includes project management functions and conditional ability to assign Foundry User to other principals. The developer specifically must not manage access or perform those broader management duties. Foundry User is therefore the more appropriate least-privilege assignment.\nD. Foundry Agent Consumer on the project. Foundry Agent Consumer is deliberately narrower than Foundry User and is intended for principals that only need to interact with agent endpoints. It does not provide the development data actions required to create or modify agents. The developer needs to build and test, not merely invoke existing agents. Assigning this role would leave the original authorization failure unresolved.\nAuthentication and authorization in Microsoft Foundry\nAdd a new connection to your project", "topic": "Agents and tools", "source": 37}, {"id": "542072", "stem": "A procurement workflow can research suppliers, retrieve contract terms, calculate order totals, and prepare purchase orders.\nThe organization requires:\nOrders below AUD $10,000 may be submitted automatically.\nOrders of AUD $10,000 or more must stop before submission.\nAn authorized employee must explicitly approve or reject high-value orders.\nThe workflow may remain paused for several hours while approval is pending.\nAfter approval, processing should resume from the suspended workflow state.\nThe approval decision must be auditable.\nWhich design best satisfies the requirements?", "options": ["Prompt-only approval instruction with trace logging", "Automatic execution followed by manual exception review", "Content Safety block with post-execution audit log", "Conditional workflow with human approval checkpoint"], "answer": 3, "explanation": "This is a semiautonomous workflow: low-impact operations can proceed automatically, while a high-impact action requires explicit human intervention. Microsoft Agent Framework workflows support human-in-the-loop interactions, including approval-required tools that pause execution until approval or rejection is supplied.\nThe monetary condition belongs in workflow logic so the application determines whether the approval checkpoint is required. For high-value orders, the workflow should suspend before the side effect occurs, preserve state, capture the human decision, and then resume appropriately. That provides a stronger control boundary than relying on model instructions to police its own behavior.\nWhy the other options are incorrect:\nA. Prompt-only approval instruction with trace logging. Instructions can tell an agent when approval is expected, and tracing can later record what the agent did. Neither mechanism guarantees that execution physically stops before a high-value purchase is submitted. The requirement calls for an enforceable human decision point rather than a behavioral suggestion followed by observation.\nB. Automatic execution followed by manual exception review. Post-execution review can identify undesirable actions, but it cannot prevent an irreversible purchase from being submitted. The scenario specifically says high-value orders must stop before submission. This design detects problems after the required control point has already been bypassed.\nC. Content Safety block with post-execution audit log. Content Safety is designed to identify content and agentic risks, not to represent business authorization for a valid procurement transaction. A purchase order can be completely safe in content terms while still requiring a human’s financial approval. The scenario needs business-process governance at the action boundary rather than content moderation.\nUsing function tools with human-in-the-loop approvals\nAgentic Workflows Task Adherence", "topic": "Agents and tools", "source": 38}, {"id": "542069", "stem": "A team has initialized a hosted agent by using:\nazd ai agent init –infra=bicep\nThe generated azure.yaml and infra/ Bicep files are committed to Git.\nThe agent:\nRuns correctly locally.\nHas already been deployed successfully with azd up.\nMust be promoted through development, test, and production.\nMust use GitHub Actions or Azure DevOps rather than manual portal deployments.\nSnippet\nazd ai agent init –infra=bicep\ngit add azure.yaml infra/\ngit commit -m “Add hosted agent infrastructure”\n(MISSING CONFIG)\nWhich command should replace (MISSING CONFIG) to configure the deployment pipeline?", "options": ["azd provision --from-portal --manual-sync", "az agent create --manual --no-pipeline", "azd deploy --skip-infra --environment production", "azd pipeline config"], "answer": 3, "explanation": "Microsoft documents azd pipeline config as the Azure Developer CLI command for configuring continuous delivery for hosted agents. It detects the Git provider, creates the CI/CD authentication identity, sets repository variables or secrets, and generates the appropriate GitHub Actions or Azure Pipelines workflow.\nUsing –infra=bicep during initialization also materializes the agent infrastructure into an infra/ directory so it can be version controlled and customized. Together, the committed azure.yaml, Bicep infrastructure, and generated deployment workflow support repeatable environment promotion instead of relying on portal drift.\nWhy the other options are incorrect:\nA. azd provision –from-portal –manual-sync. azd provision is associated with provisioning infrastructure, but the additional flags in this option do not represent the documented pipeline-configuration workflow. Provisioning resources once does not create GitHub Actions or Azure DevOps automation. The requirement is to configure CI/CD rather than manually synchronize portal state.\nB. az agent create –manual –no-pipeline. This command does not represent the documented Azure Developer CLI hosted-agent pipeline workflow. The requirement explicitly calls for automated source-controlled deployment rather than manual agent creation. Even if an agent were successfully created manually, the promotion mechanism across environments would remain missing.\nC. azd deploy –skip-infra –environment production. An azd deployment can participate in a delivery process, but running a deployment command locally is not the same as configuring the repository’s CI/CD integration. Skipping infrastructure would also undermine the requirement to keep the Bicep-defined environment synchronized when infrastructure changes. The documented command that establishes the pipeline is azd pipeline config.\nHosted agent infrastructure with Azure Developer CLI\nazure.yaml reference for hosted agents", "topic": "Agents and tools", "source": 38}, {"id": "542233", "stem": "An engineer uses az rest to list Hosted agents.\nThe Foundry account, project name, API version, user authentication, and feature header are correct.\nACCOUNT_NAME=”contoso-foundry”\nPROJECT_NAME=”production-ai”\nBASE_URL=”https://${ACCOUNT_NAME}.services.ai.azure.com/api/projects/${PROJECT_NAME}”\naz rest \\\n–method GET \\\n–url “${BASE_URL}/agents-api-version=v1” \\\n–headers “Foundry-Features=HostedAgents=V1Preview”\nThe request fails during Microsoft Entra authentication because Azure CLI cannot derive the correct token audience from the data-plane URL.\nWhich configuration should be added?", "options": ["--scope https://ai.azure.com/.default", "--resource https://management.azure.com", "--resource https://search.azure.com", "--resource https://ai.azure.com"], "answer": 3, "explanation": "Microsoft’s Hosted-agent REST guidance explicitly requires the –resource argument for az rest calls against Agent Service data-plane endpoints and defines the resource as\nhttps://ai.azure.com\n. Without it, az rest cannot derive the required Entra audience from the URL.\nThe corrected command is:\nACCOUNT_NAME=”contoso-foundry”\nPROJECT_NAME=”production-ai”\nBASE_URL=”https://${ACCOUNT_NAME}.services.ai.azure.com/api/projects/${PROJECT_NAME}”\naz rest \\\n–method GET \\\n–url “${BASE_URL}/agents-api-version=v1” \\\n–resource “https://ai.azure.com” \\\n–headers “Foundry-Features=HostedAgents=V1Preview”\nWhy the other options are incorrect\nA. az rest uses the –resource parameter for this documented pattern rather than the –scope syntax shown.\nB.\nhttps://management.azure.com\nis the Azure Resource Manager audience, not the Foundry data-plane audience.\nC.\nhttps://search.azure.com\nis the Azure AI Search audience and would produce a token for the wrong target service.\nManage Hosted agent sessions\nHosted agents in Foundry Agent Service", "topic": "Agents and tools", "source": 41}, {"id": "542137", "stem": "Refer to:\nhttps://docs.google.com/document/d/1KL5r5lDcN4JDa45bROfDFuAS9anguaQi4BCFAtn4_p4/edit-usp=sharing\nYou need to satisfy E4, BR3, TR3, and C4.\nThe agent already uses Azure AI Search to retrieve approved maintenance procedures. You must enable the agent to retrieve the current state of a work order directly from the existing REST API.\nThe agent must select the appropriate API operation, supply the required parameters, and authenticate by using the Foundry managed identity. Meridian must not implement another service to execute the API request.\nWhich tool should you add to the agent?", "options": ["OpenAPI tool", "Azure AI Search tool", "Function tool", "MCP tool"], "answer": 0, "explanation": "An OpenAPI tool enables a Foundry agent to discover and invoke operations described by an OpenAPI 3.0 or 3.1 specification. The agent can select the appropriate work-order operation, construct its parameters, invoke the endpoint, and use the returned current state in its response. This directly uses the API described in E4 without requiring Meridian to write a separate dispatch service.\nOpenAPI tools support managed-identity authentication for APIs protected by Microsoft Entra ID. Meridian must configure the work-order API’s Application ID URI as the audience and grant the Foundry identity the required API access. This meets TR3 while avoiding API keys, client secrets, and custom orchestration.\nWhy the other options are incorrect:\nB. Azure AI Search retrieves indexed content from a search index. It is appropriate for maintenance manuals, but it does not invoke arbitrary operations from the work-order API specification. Indexing the work-order data would also create a delay between an operational change and the agent’s response. That would not reliably satisfy BR3’s requirement for the current work-order state.\nC. A function tool allows an agent to request execution of a function defined by the application. Meridian would still need to host code that receives the tool request, calls the work-order API, and returns the result. This adds custom orchestration that C4 requires the implementation team to minimise. The existing OpenAPI specification makes that additional function layer unnecessary.\nD. An MCP tool connects the agent to capabilities exposed by a Model Context Protocol server. Meridian does not have an MCP server in the case-study environment. Introducing one solely to wrap the existing REST API would add another hosted component and security boundary. It would not be the most direct solution under C4.\nFoundry Agent Service tool catalogue\nSecure OpenAPI calls from Foundry Agent Service", "topic": "Agents and tools", "source": 39}, {"id": "542290", "stem": "A developer is configuring a Foundry support agent. The agent must ground answers in uploaded policy files and call a custom function when the user asks to open a service request.\nSnippet\nagent:\nname: policy-support-agent\nmodel: gpt-4.1\ninstructions: |\nAnswer using internal policy documents when possible.\nIf the user asks to open a service request, collect the required fields.\nUse the ticket function only after the required fields are available.\ntools:\n(MISSING CONFIG)\nruntime:\nconversation:\nmode: stateful\ncarry_forward_context: true\nWhich configuration should replace (MISSING CONFIG)?", "options": ["File Search tool and function schema", "Web Search tool and prompt cache", "Code Interpreter and batch endpoint", "Blob container and Search indexer schedule"], "answer": 0, "explanation": "File Search tool and function schema is correct because the agent needs two different capabilities: retrieval from uploaded policy files and the ability to request an external business action. In Foundry agents, File Search is used to retrieve relevant information from documents, while function calling defines callable functions that your application executes and returns to the agent.\nThe stateful conversation setting handles the follow-up context, but it does not replace retrieval or function definition. Conversation state helps the agent remember prior turns, while tools let it use external knowledge and perform external actions. A complete agent design must configure all three parts deliberately.\nWhy the other options are incorrect:\n• B. Web Search tool and prompt cache is plausible if the agent needs current public information. However, the requirement is to use uploaded internal policy files, not public web grounding. A prompt cache may reduce repeated prompt-processing cost, but it is not the same as conversation memory or a function definition. This option also fails to provide a callable service-request function.\n• C. Code Interpreter and batch endpoint is plausible for data analysis or long-running offline processing. However, Code Interpreter is not the right tool for grounding support answers in policy documents. A batch endpoint also does not represent an interactive function call from the agent during a conversation. This option solves the wrong workload shape.\n• D. Blob container and Search indexer schedule is plausible because documents often start in storage and can be indexed. However, that configuration alone does not expose a Foundry File Search tool to the agent. It also does not define the ticket-creation function schema. Storage and indexing infrastructure are not sufficient by themselves for agent tool integration.\nFile search tool for agents\nUse function calling with Microsoft Foundry agents", "topic": "Agents and tools", "source": 42}, {"id": "542066", "stem": "A company is creating a common AI platform for legal, HR, finance, and engineering agents.\nThe platform must:\nSupport tool-using agents.\nAllow multiple agents to consume the same enterprise knowledge layer.\nCombine knowledge from multiple governed data sources.\nSupport permission-aware retrieval.\nSupport query planning and retrieval for complex questions.\nReturn grounded answers with source attribution.\nKeep model inference available through managed Foundry deployments.\nAvoid creating a separate duplicate vector store for every agent.\nWhich architecture best satisfies the requirements?", "options": ["Agent Service + per-agent File Search + duplicated vector stores", "Agent Service + Search knowledge base + model deployment", "Prompt flow + Azure SQL retrieval + hosted model endpoint", "Azure Functions + Blob Storage + shared model deployment"], "answer": 1, "explanation": "Microsoft Foundry Agent Service provides the agent execution layer, while a Foundry IQ knowledge base backed by Azure AI Search provides a reusable enterprise knowledge layer. Microsoft describes Foundry IQ as turning enterprise content into reusable, permission-aware knowledge bases that agents can consume, while Azure AI Search knowledge bases can orchestrate retrieval across knowledge sources.\nThis separation is important architecturally. Agent definitions can focus on behavior, tools, and workflows while the knowledge base centrally manages grounding and retrieval. Model deployments then provide the inference capability used by the agents and retrieval orchestration, avoiding unnecessary duplication of knowledge storage across every individual agent.\nWhy the other options are incorrect:\nA. Agent Service + per-agent File Search + duplicated vector stores. File Search is a valid grounding mechanism for files uploaded to an agent and can automatically handle parsing, chunking, embeddings, and retrieval. It is less appropriate when the organization specifically wants a reusable, centrally governed knowledge layer shared across many agents and multiple enterprise sources. Duplicating vector stores for each agent also increases synchronization and lifecycle overhead.\nC. Prompt flow + Azure SQL retrieval + hosted model endpoint. Azure SQL can store structured enterprise information and could participate in a larger retrieval solution. This design does not naturally provide the reusable permission-aware knowledge-base abstraction, agent-focused query planning, or multi-source retrieval model described in the requirements. It also substitutes a flow-oriented architecture for the explicit tool-using agent requirement.\nD. Azure Functions + Blob Storage + shared model deployment. Blob Storage is suitable for storing source documents, and Azure Functions could implement custom orchestration code. Neither component by itself provides vector retrieval, hybrid search, query decomposition, citations, or reusable permission-aware knowledge management. The organization would have to build much of the required retrieval platform itself instead of using the Foundry and Search capabilities designed for it.\nCreate a knowledge base in Azure AI Search\nStudy guide for Exam AI-103", "topic": "Agents and tools", "source": 38}, {"id": "542345", "stem": "You are designing infrastructure for an internal HR assistant built with Foundry Agent Service. The assistant must answer questions from company policy documents and must not expose the agent endpoint, search index, or Foundry management plane directly to the public internet.\nThe solution must meet these requirements:\n• Use private connectivity where possible\n• Use identity-based access to Azure AI Search\n• Keep the agent inside a managed Foundry-based environment\n• Support future projects for other departments\n• Minimize custom hosting infrastructure\nWhich architecture should you recommend?", "options": ["Public Foundry project with API keys", "Foundry project with private endpoints", "App Service with embedded search keys", "Blob storage with static agent files"], "answer": 1, "explanation": "A Foundry project with private endpoints is the strongest fit because it keeps the solution aligned to Foundry infrastructure while supporting network isolation. Foundry organizes workloads through resources and projects, and private endpoints help secure communication to Foundry and connected services.\nFor an agent-based solution that retrieves from Azure AI Search, private networking and managed identity are important design choices. This approach avoids public exposure and avoids embedding keys in application code while still using the managed Foundry Agent Service platform.\nWhy the other options are incorrect:\n• A. A public Foundry project with API keys might be faster to configure for a development prototype. However, it does not meet the requirement to avoid public exposure of the management plane, agent endpoint, or connected services. API keys also create secret-management risk and are not the preferred approach for a private, identity-based enterprise design. This option fails both the networking and authentication requirements.\n• C. App Service can host an application front end or orchestration layer, but embedding search keys is a poor infrastructure design for this requirement. It increases secret exposure risk and does not use project managed identity for Search access. It also shifts the design away from a managed Foundry Agent Service pattern. The requirement asks to minimize custom hosting infrastructure, not expand it.\n• D. Blob storage is suitable for holding source documents, but it does not provide agent runtime, tool orchestration, model deployment, or secure retrieval. Static files alone cannot replace Azure AI Search indexing or Foundry Agent Service. This option confuses raw document storage with searchable, grounded agent infrastructure. It would not satisfy the agent-based solution requirements.\nSet up private networking for Foundry Agent Service\nBaseline Microsoft Foundry chat reference architecture", "topic": "Agents and tools", "source": 43}, {"id": "542136", "stem": "Refer to:\nhttps://docs.google.com/document/d/1KL5r5lDcN4JDa45bROfDFuAS9anguaQi4BCFAtn4_p4/edit-usp=sharing\nYou need to satisfy TR1 and TR2.\nThe evaluation team has generated responses from both candidate language models by using the same representative Meridian dataset. The JSONL file contains the engineering question, retrieved context, generated response, approved reference response, latency, and token usage for every test case.\nThe team must apply quality and safety evaluators to the existing responses without invoking either candidate model again.\nWhich evaluation target should you select in Microsoft Foundry?", "options": ["Benchmark evaluation", "Continuous evaluation", "Dataset evaluation", "Trace-based agent evaluation"], "answer": 2, "explanation": "Dataset evaluation is designed for evaluating pre-existing model or agent outputs stored in a CSV or JSONL dataset. Meridian can map the question, generated response, retrieved context, and approved reference response to the fields required by evaluators such as groundedness, relevance, response completeness, and safety. Neither candidate model needs to be invoked again because the generated outputs already exist.\nLatency and token usage recorded in the dataset can be analysed alongside the evaluator scores. This allows Meridian to determine whether any quality improvement from the larger model justifies its additional latency and consumption. Using the same dataset and evaluator configuration for both models also provides the controlled comparison required by TR1 and TR2.\nWhy the other options are incorrect:\nA. Benchmark evaluation uses standard benchmark datasets and scoring methods to compare general model capabilities. It can help Meridian identify candidate models before workload testing. It does not directly evaluate the existing responses against Meridian’s approved engineering answers and retrieved maintenance context. The organisation still requires a dataset evaluation using its representative data.\nB. Continuous evaluation is used to monitor application or agent quality after deployment by evaluating production interactions or sampled operational data. Meridian is making a predeployment model-selection decision and does not yet have production traffic. Continuous evaluation would therefore occur too late to satisfy TR1. It also would not make direct use of the prepared response dataset as the evaluation target.\nD. Trace-based agent evaluation analyses historical agent executions captured through Application Insights. It is appropriate when Meridian needs to inspect tool selection, agent decisions, or previously recorded conversations. The current task compares existing model responses rather than complete agent executions. No agent traces are required to score the prepared JSONL data.\nBuilt-in evaluators in Microsoft Foundry\nView evaluation results", "topic": "Evaluation", "source": 39}, {"id": "542212", "stem": "A team is validating workflow quality for a deployed agent. The agent is allowed to take extra helper steps, but all required actions must still appear in the correct order.\nSnippet\ntesting_criteria = [\n{\n“type”: “azure_ai_evaluator”,\n“name”: “workflow_path_check”,\n“evaluator_name”: “builtin.task_navigation_efficiency”,\n“initialization_parameters”: {\n“matching_mode”: “(MISSING CONFIG)”\n},\n“data_mapping”: {\n“actions”: “{{item.actions}}”,\n“expected_actions”: “{{item.expected_actions}}”\n}\n}\n]\nexpected_actions = [\n“identify_tools_to_call”,\n“call_tool_A”,\n“call_tool_B”,\n“response_synthesis”\n]\nWhich value should replace (MISSING CONFIG)?", "options": ["exact_match mode", "any_order_match mode", "unordered sequence validation mode", "in_order_match mode"], "answer": 3, "explanation": "The correct value is in_order_match. Microsoft documents three matching modes for Task Navigation Efficiency: exact_match, in_order_match, and any_order_match. It explains that in_order_match requires all ground-truth steps to appear in the agent’s trajectory in the correct order while still allowing extra steps, which matches this scenario exactly.\nThis is a useful operational distinction. If you chose exact_match, helper steps would incorrectly cause failures even when the core path is valid. If you chose any_order_match, the evaluator would no longer enforce the sequence requirement, which is a key part of the stated quality bar.\nWhy the other options are incorrect:\nA. exact_match mode. exact_match is stricter than the requirement because it expects the agent trajectory to match the ground truth exactly in both content and order. That would fail runs where the agent includes extra helper steps, even though the scenario says extra steps are allowed. It is too rigid for the stated monitoring goal.\nB. any_order_match mode. any_order_match allows all ground-truth steps to appear in any order. That directly conflicts with the requirement that the required actions still appear in the correct order. It would be too permissive for detecting workflow-order regressions.\nC. unordered sequence validation mode. This is not one of the documented Task Navigation Efficiency matching modes in Microsoft Foundry. Microsoft documents exact_match, in_order_match, and any_order_match. Using an invented value would not satisfy the evaluator configuration.\nEvaluate your AI agents\nObservability in Generative AI", "topic": "Agents and tools", "source": 40}, {"id": "542343", "stem": "from azure.ai.evaluation import GroundednessEvaluator, evaluate\nmodel_config = {\n“azure_endpoint”: “https://contoso-foundry.openai.azure.com/”,\n“azure_deployment”: “gpt-4.1-mini”,\n“api_version”: “2024-10-21”\n}\ngroundedness = GroundednessEvaluator(model_config=model_config)\nresult = evaluate(\ndata=”evaluation_dataset.jsonl”,\nevaluators={\n“groundedness”: groundedness\n},\nevaluator_config={\n“groundedness”: {\n“column_mapping”: {\n(MISSING CONFIG)\n}\n}\n}\n)\nprint(result.metrics)\nWhich mapping should replace (MISSING CONFIG)?", "options": ["\"query\": \"${data.query}\", \"model\": \"${data.model}\"", "\"response\": \"${data.answer}\", \"category\": \"${data.risk}\"", "\"response\": \"${data.answer}\", \"context\": \"${data.context}\"", "\"deployment\": \"${data.deployment}\", \"index\": \"${data.index}\""], "answer": 2, "explanation": "Groundedness evaluation requires the generated response and the grounding context used to support that response. The evaluator compares claims in the response against the provided context to determine whether the output is grounded.\nThe key issue is not whether the model can produce fluent text, but whether the answer can be verified from the retrieved material. Mapping both response and context gives the evaluator the generated answer and the source content needed to detect fabrications.\nWhy the other options are incorrect:\n• A. The query can help some evaluators, but this mapping omits the response and context pairing required to verify grounding. A model name does not provide the evidence used to judge whether the answer was fabricated. This option would not let the evaluator compare claims to source material. It focuses on metadata rather than the actual evaluation inputs.\n• B. The response is included, but the risk category is not the grounding source. Risk categories are more relevant to safety classification than factual support against retrieved documents. Without context, the evaluator cannot determine whether the response is supported by source material. This option confuses safety assessment inputs with groundedness inputs.\n• D. Deployment and index values identify infrastructure elements, not the content being evaluated. They do not contain the generated answer or the retrieved context. The evaluator needs data-row fields that represent the response and supporting material. This mapping would not test fabrication against source evidence.\nGroundednessEvaluator class\nRetrieval-augmented Generation evaluators", "topic": "Evaluation", "source": 43}, {"id": "542017", "stem": "A team is integrating a partner order API into a Foundry-based agent. The API key is already stored in a Foundry project connection, and the code already resolved the connection ID.\nSnippet\nfrom azure.ai.projects.models import PromptAgentDefinition\nopenapi_connection = project.connections.get(OPENAPI_CONNECTION_NAME)\nconnection_id = openapi_connection.id\norders_tool = {\n“type”: “openapi”,\n“openapi”: {\n“name”: “get_orders”,\n“spec”: orders_spec,\n“auth”: (MISSING CONFIG)\n}\n}\nWhich value should replace (MISSING CONFIG)?", "options": ["{\"type\": \"anonymous\"}", "{\"type\": \"managed_identity\", \"security_scheme\": {\"audience\": \"https://orders.contoso.com\"}}", "{\"type\": \"project_connection\", \"security_scheme\": {\"project_connection_id\": OPENAPI_CONNECTION_NAME}}", "{\"type\": \"project_connection\", \"security_scheme\": {\"project_connection_id\": connection_id}}"], "answer": 3, "explanation": "Option D is correct because the Microsoft OpenAPI tool example for API-key-based authentication retrieves the connection object from project.connections.get(…), reads its id, and then uses auth.type = “project_connection” with security_scheme.project_connection_id = connection_id. That is the documented configuration pattern when the secret is stored in a Foundry project connection.\nThis also matches Microsoft’s requirement that API-key authentication for OpenAPI tools use a project connection, with the connection carrying the secret rather than embedding credentials in code or prompts. It is the cleanest and most secure fit for integrating a key-protected external API into a Foundry-based generative workflow.\nWhy the other options are incorrect:\n• A. {“type”: “anonymous”}. Anonymous authentication is for public APIs that do not require credentials. In this scenario, the API key is already stored in a project connection, so using anonymous auth would discard the required secret and the downstream request would fail. It ignores the connector pattern the scenario explicitly established.\n• B. {“type”: “managed_identity”, “security_scheme”: {“audience”: “https://orders.contoso.com”}}. Managed identity is appropriate for Azure services or Microsoft Entra-protected APIs that accept Entra tokens and support the required access model. The scenario says the partner API is already secured with an API key in a project connection, which points to project-connection auth rather than managed identity. Using managed identity here would change the authentication model instead of correctly consuming the configured connector.\n• C. {“type”: “project_connection”, “security_scheme”: {“project_connection_id”: OPENAPI_CONNECTION_NAME}}. This is close, but the documented example uses the connection ID, not the connection name, inside project_connection_id. Microsoft explicitly shows retrieving the connection and then assigning openapi_connection.id into the auth block. Using the connection name here would not match the documented configuration shape.\nAzure AI Projects client library for Python\nAdd a new connection to your project", "topic": "Agents and tools", "source": 37}, {"id": "542400", "stem": "{\n“agent”: {\n“name”: “procurement-triage-agent”,\n“model”: “gpt-4.1-mini”,\n“description”: “Triage purchase requests and submit complete requests.”,\n“instructions”: “(MISSING CONFIG)”,\n“tools”: [\n{\n“type”: “function”,\n“function”: {\n“name”: “submit_purchase_request”,\n“description”: “Submit a validated purchase request.”,\n“parameters”: {\n“type”: “object”,\n“properties”: {\n“category”: { “type”: “string” },\n“amount”: { “type”: “number” },\n“businessJustification”: { “type”: “string” }\n},\n“required”: [\n“category”,\n“amount”,\n“businessJustification”\n]\n}\n}\n}\n]\n},\n“conversation”: {\n“tracking”: “reuse conversation id for follow-up messages”\n}\n}\nWhich instruction best completes the configuration?", "options": ["Answer procurement questions using the shortest possible response", "Call the purchase tool before asking follow-up questions", "Store all approval state inside the tool description", "Use the tool after collecting required purchase fields"], "answer": 3, "explanation": "The missing instruction should define the agent’s behavior in relation to the tool schema. The function requires category, amount, and business justification, so the agent should collect those fields before calling the tool.\nConversation tracking preserves follow-up context, but it does not replace clear agent instructions. The agent still needs role and goal guidance that tells it when the tool should be used and when it should ask clarifying questions instead.\nWhy the other options are incorrect:\n• A. Short responses can be useful, but this option does not define the agent’s role, goal, or tool-use boundary. It ignores the required function parameters in the schema. A concise answer can still be incomplete or unsafe if the agent calls the tool without collecting required fields.\n• B. Calling the tool before asking follow-up questions violates the schema-driven workflow. If required fields are missing, the function call would be incomplete or would force downstream validation failures. The agent should ask for missing information before submitting the request.\n• C. Tool descriptions explain what a tool does, but they should not be used as the main state store for approvals or conversation progress. State and context should be handled through the conversation and application workflow. This option also fails to tell the agent when it should call the function.\nUse function calling with Microsoft Foundry agents\nAgent tools overview for Foundry Agent Service", "topic": "Agents and tools", "source": 44}, {"id": "542268", "stem": "An IT helpdesk agent must look up ticket status from an internal ticketing API. The agent should decide when to request the lookup, but the application must execute the backend call and return the result.\nSnippet\n{\n“agent”: {\n“name”: “helpdesk-ticket-agent”,\n“model”: “gpt-4.1”,\n“instructions”: “Help users check ticket status and explain next steps.”,\n“tools”: [\n{\n“type”: “(MISSING CONFIG)”,\n“name”: “get_ticket_status”,\n“description”: “Retrieve the current status of a support ticket.”,\n“parameters”: {\n“type”: “object”,\n“properties”: {\n“ticketId”: {\n“type”: “string”,\n“description”: “The support ticket identifier.”\n}\n},\n“required”: [“ticketId”]\n}\n}\n]\n}\n}\nWhich missing configuration should you use?", "options": ["File search tool", "Code Interpreter", "Function tool", "Agent memory"], "answer": 2, "explanation": "A function tool is the correct choice when the agent needs to request an external business operation and the application is responsible for executing that operation. The agent can identify the need for get_ticket_status, provide the required argument, and wait for the application to return the tool output.\nThis is different from document retrieval or sandboxed computation. The requirement is not to search files or run Python analysis; it is to connect the agent to controlled business logic through a tool contract.\nWhy the other options are incorrect:\n• A. File search tool is used to retrieve relevant information from uploaded or indexed documents. It would be appropriate for searching helpdesk manuals or troubleshooting PDFs. It does not call an internal ticketing API. It also does not let the application execute controlled backend business logic.\n• B. Code Interpreter allows an agent to run Python in a sandbox. It is useful for calculations, data analysis, and working with files inside that sandbox. It should not be used as the primary integration path for a governed enterprise ticketing system. The scenario needs a controlled API action, not ad hoc code execution.\n• D. Agent memory helps retain useful context across sessions. It may remember a user’s support preferences or prior interaction signals. It does not define a callable backend operation. It also does not execute the ticket lookup or return live ticket status.\nAgent tools overview for Foundry Agent Service\nTool best practices for Microsoft Foundry Agent Service", "topic": "Agents and tools", "source": 41}, {"id": "542074", "stem": "A compliance agent has system instructions stating that it must never approve an unverified bank-account change.\nThe team already added a self-critique step before each final response. The outputs now sound more careful, but held-out test traces show that the agent occasionally violates the instruction.\nThe CI pipeline must evaluate whether the agent follows its assigned rules before a new version is released.\nSnippet\ntesting_criteria = [\n{\n“type”: “azure_ai_evaluator”,\n“name”: “policy_compliance”,\n“evaluator_name”: “(MISSING CONFIG)”,\n“initialization_parameters”: {\n“deployment_name”: model_deployment\n},\n“data_mapping”: {\n“query”: “{{item.query}}”,\n“response”: “{{item.response}}”\n}\n}\n]\nWhich value should replace (MISSING CONFIG)?", "options": ["\"builtin.intent_resolution\"", "\"builtin.tool_call_success\"", "\"builtin.task_adherence\"", "\"builtin.task_navigation_efficiency\""], "answer": 2, "explanation": "Microsoft’s current agent-evaluator configuration uses builtin.task_adherence to assess whether an agent follows the rules and constraints defined for its task. The documented configuration requires query and response data plus a judge-model deployment, which is exactly the structure shown in the question.\nThis is stronger than trusting an agent’s own self-critique as the release gate. A separate evaluation run over held-out cases provides external evidence that the behavior satisfies the policy and allows the pipeline to enforce a measurable acceptance threshold before promotion.\nWhy the other options are incorrect:\nA. “builtin.intent_resolution”. Intent Resolution evaluates whether the agent correctly identifies and addresses what the user intends. A response can accurately understand a bank-account-change request and still violate the prohibition against approving an unverified change. The failure being tested concerns adherence to constraints, not intent recognition.\nB. “builtin.tool_call_success”. Tool Call Success focuses on whether tool invocations execute without technical errors or exceptions. A forbidden approval tool could run perfectly successfully and still represent a severe policy violation. Technical success is therefore almost the opposite of what needs to be measured in this scenario.\nD. “builtin.task_navigation_efficiency”. Task Navigation Efficiency compares an agent’s actions with an expected sequence and can determine whether required steps occurred in an expected order. The requirement does not define a trajectory or action sequence; it defines a behavioral rule that must not be violated. Task Adherence is therefore the evaluator aligned to the stated control.\nEvaluate your AI agents\nCreate an evaluation dataset and evaluators", "topic": "Agents and tools", "source": 38}, {"id": "542090", "stem": "A developer has already deployed a model in Foundry and is now creating an agent by using the Python SDK. The agent must target that deployed model.\nSnippet\nimport os\nfrom azure.identity import DefaultAzureCredential\nfrom azure.ai.agents import AgentsClient\nagents_client = AgentsClient(\nendpoint=os.environ[“PROJECT_ENDPOINT”],\ncredential=DefaultAzureCredential(),\n)\nagent = agents_client.create_agent(\nmodel=os.environ[“(MISSING CONFIG)”],\nname=”ops-agent”,\ninstructions=”Summarize deployment alerts and recommend next steps.”,\n)\nprint(agent.id)\nWhich value should replace (MISSING CONFIG)?", "options": ["MODEL_NAME", "AGENT_ENDPOINT", "MODEL_DEPLOYMENT_NAME", "PROJECT_RESOURCE_GROUP"], "answer": 2, "explanation": "MODEL_DEPLOYMENT_NAME is correct because the Azure AI Agents Python documentation shows create_agent() using model=os.environ[“MODEL_DEPLOYMENT_NAME”]. That reflects how the agent is bound to a deployed model configuration rather than to an abstract catalog label or unrelated project metadata.\nThis matters because agent creation is downstream from model deployment. You first make the model available in Foundry, then the agent references that deployment when it is created. Using the deployment name keeps the agent pointed at an actual callable model endpoint configuration.\nWhy the other options are incorrect:\n• A. MODEL_NAME. A model name sounds plausible because users browse models by name in the catalog. However, the agent SDK example does not use a raw model catalog name here; it uses the model deployment name. In practice, deployments are the operational object the app targets for inference.\n• B. AGENT_ENDPOINT. The endpoint argument belongs to the client connection, not the model field passed to create_agent(). Confusing project or service endpoint configuration with model selection is a common mistake, but they solve different problems. One connects the SDK to the project, and the other identifies which deployed model the agent should use.\n• D. PROJECT_RESOURCE_GROUP. A resource group is an Azure management boundary, not a model identifier for agent creation. It has no role in the model= parameter shown in the SDK example. Selecting it would mix infrastructure organization metadata with runtime model binding.\nMicrosoft Foundry quickstart\nDeploy Microsoft Foundry Models in the Foundry portal", "topic": "Agents and tools", "source": 38}, {"id": "542104", "stem": "A team is building a tool-enabled agent for purchase approvals.\nThey want the tool call to pause and require human approval before execution.\nSnippet\nfrom typing import Annotated\nfrom agent_framework import tool\n@tool(\nname=”submit_purchase_order”,\ndescription=”Creates a purchase order in the ERP system”,\napproval_mode=(MISSING CONFIG),\n)\ndef submit_purchase_order(\namount: Annotated[float, “Purchase amount”],\nvendor: Annotated[str, “Vendor name”],\njustification: Annotated[str, “Business reason”]\n) -> str:\nreturn f”Submitted order for {vendor} at ${amount}: {justification}”\nWhich value should replace (MISSING CONFIG)?", "options": ["\"auto\"", "\"required\"", "\"manual\"", "\"always_require\""], "answer": 3, "explanation": "“always_require” is correct because Microsoft’s human-in-the-loop approval tutorial states that when you use the @tool decorator, you make a function require human approval by setting the approval_mode parameter to “always_require”. That is the exact documented control for pausing a tool call until a person approves it.\nThis also fits the exam objective because it implements a semiautonomous workflow rather than a fully autonomous one. The agent can reason about when to use the tool, but the execution of that tool is gated by an approval control before the action proceeds.\nWhy the other options are incorrect:\n• A. “auto”. Microsoft’s documented example does not use “auto” as the approval-mode value for required approvals. The tutorial is explicit that “always_require” is the setting that marks the function for approval before execution. Even if “auto” sounds plausible, it is not the documented control in the published pattern.\n• B. “required”. This option sounds semantically close, which makes it a strong distractor, but the article does not describe it as the decorator value for approval-gated tools. The documented behavior is tied to the literal “always_require” value. In implementation questions, those exact configuration values matter because the runtime expects the published setting.\n• C. “manual”. A human approval flow is conceptually manual, but the tutorial does not define “manual” as the configuration value for the decorator. The question is asking for the specific setting that implements the approval pattern, not just a general English description of the behavior. That makes this option plausible in wording but incorrect in configuration.\nStudy guide for Exam AI-103\nBuild a workflow in Microsoft Foundry", "topic": "Agents and tools", "source": 39}, {"id": "542029", "stem": "A team created a knowledge base in Azure AI Search and a project connection in Foundry.\nThey want a Foundry agent to call that knowledge base through MCP.\nSnippet\nfrom azure.ai.projects import AIProjectClient\nfrom azure.ai.projects.models import MCPTool\nfrom azure.identity import DefaultAzureCredential\nproject = AIProjectClient(\nendpoint=project_endpoint,\ncredential=DefaultAzureCredential(),\n)\nmcp_kb_tool = MCPTool(\nserver_label=”knowledge-base”,\nserver_url=mcp_endpoint,\nrequire_approval=”never”,\nproject_connection_id=project_connection_name,\nallowed_tools=(MISSING CONFIG)\n)\nWhich value should replace (MISSING CONFIG)?", "options": ["[\"file_search\"]", "[\"retrieve\"]", "[\"azure_ai_search\"]", "[\"knowledge_base_retrieve\"]"], "answer": 3, "explanation": "[“knowledge_base_retrieve”] is the correct value. Microsoft’s Foundry IQ connection guidance says Azure AI Search knowledge bases expose the knowledge_base_retrieve MCP tool for agent integration, and it notes that this is the supported tool for use with Foundry Agent Service in that flow.\nThis is the direct bridge between the knowledge-base retrieval pipeline and the agent tool surface. The agent uses that MCP tool to invoke query planning, decomposition, retrieval across configured knowledge sources, and result synthesis through the knowledge base.\nWhy the other options are incorrect:\nA. [“file_search”]. File Search is a separate built-in Foundry tool for searching uploaded files or proprietary documents through the file-search flow. It is not the MCP tool name exposed by an Azure AI Search knowledge base. Using this value would confuse two different retrieval integration models.\nB. [“retrieve”]. The retrieve action is the name of the workflow/API method used to query a knowledge base directly from an application. Microsoft does not document it as the MCP tool name that an agent allow-list should use. For MCP integration, the documented tool name is knowledge_base_retrieve.\nC. [“azure_ai_search”]. This sounds plausible because the retrieval infrastructure is Azure AI Search, but it is not the documented MCP tool identifier exposed by the knowledge base. Microsoft distinguishes between the Azure AI Search tool for direct index grounding and the MCP tool used by a knowledge base. The configuration in this snippet is specifically the knowledge-base MCP path.\nQuery a knowledge base using the retrieve action or MCP endpoint\nCreate a knowledge base", "topic": "Agents and tools", "source": 37}, {"id": "542272", "stem": "A team is preparing a documentation assistant for production. The assistant must produce concise answers, avoid speculation, and behave consistently across common support questions.\nProblem:\nThe team needs to tune generation behavior before release.\nProposed solution:\nUse the Microsoft Foundry playground to test prompt variants, add explicit system instructions for uncertainty handling, set temperature to 0.2, and run evaluations on representative prompts before deployment.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it combines prompt engineering, parameter tuning, and evaluation before deployment. Explicit system instructions help control behavior such as uncertainty handling and response style. A lower temperature supports more focused and consistent answers for a documentation assistant.\nThe solution is also operationally appropriate because it tests prompt variants and validates them against representative prompts before release. That matters because prompt and parameter changes should be measured, not guessed. For AI-103, this is the expected pattern: tune the prompt and model settings, then evaluate behavior before production rollout.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution directly addresses the stated requirements. It includes prompt instructions for speculation control, a lower temperature for consistency, and evaluation before release. Those are the relevant controls for tuning generation behavior. A different solution might add more monitoring or safety controls, but the proposed solution satisfies the specific goal.\nPrompt engineering techniques\nRun evaluations from the Microsoft Foundry portal", "topic": "Evaluation", "source": 41}, {"id": "542022", "stem": "A team is building a writer-reviewer solution. They need the writer and reviewer to iteratively refine the same answer, keep a shared conversation history, and stop after a limited number of review cycles if quality criteria are not met.\nProblem:\nThe orchestration must support iterative collaboration with shared context and controlled refinement loops.\nProposed solution:\nUse a handoff orchestration between the writer and reviewer and let each agent transfer control when needed.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "The proposed solution does not fully meet the goal. Microsoft describes handoff orchestration as dynamic delegation between specialized agents based on context, which is useful for routing and transfer scenarios, but it is not the pattern Microsoft highlights for iterative shared-thread collaboration.\nFor iterative refinement with shared context, Microsoft’s guidance points to group chat orchestration and specifically to maker-checker loops. Microsoft states that group chat keeps a shared conversation history and that maker-checker loops use iterative review with feedback, acceptance criteria, and an iteration cap to avoid endless refinement.\nWhy the other options are incorrect:\nA. Yes. This answer would be correct only if handoff were the recommended pattern for shared-thread collaboration and review loops, but Microsoft distinguishes those scenarios from dynamic delegation. Handoff is appropriate when the task should transfer to the most suitable specialist based on context, often one at a time. The requirement here is iterative collaborative refinement with shared context, which is better aligned to group chat and maker-checker behavior.\nWorkflow orchestrations in Agent Framework\nGroup Chat orchestration", "topic": "Agents and tools", "source": 37}, {"id": "542257", "stem": "An agent must collect a shipment ID, call an internal logistics API, and use the returned delivery status in its final answer. The application code must execute the API call after the model requests it.\nSnippet\n{\n“agent”: {\n“name”: “shipment-status-agent”,\n“instructions”: “Help users check shipment status and explain next steps.”,\n“model”: “gpt-4.1”,\n“tools”: [\n{\n“type”: “(MISSING CONFIG)”,\n“name”: “get_shipment_status”,\n“description”: “Retrieve live shipment status from the logistics API.”,\n“parameters”: {\n“type”: “object”,\n“properties”: {\n“shipment_id”: {\n“type”: “string”,\n“description”: “The shipment identifier supplied by the user.”\n},\n“include_events”: {\n“type”: “boolean”,\n“description”: “Whether to include tracking event history.”\n}\n},\n“required”: [“shipment_id”]\n}\n}\n],\n“runtime”: {\n“tool_invocation”: “application_executes_tool_call”,\n“response_style”: “grounded_in_tool_output”\n}\n}\n}\nWhich missing configuration should you use?", "options": ["file_search", "code_interpreter", "function", "web_search"], "answer": 2, "explanation": "The correct missing configuration is function because the agent needs to request a custom business operation that the application executes. Function calling lets the model identify the tool, provide structured arguments, and continue the conversation after the application returns the result.\nThis supports a tool-augmented flow without giving the model direct unrestricted access to the internal logistics system. The application remains responsible for authentication, validation, execution, error handling, and returning trusted data back to the agent.\nWhy the other options are incorrect:\n• A. file_search is used when the agent needs to retrieve information from documents or indexed files. It is a knowledge-grounding tool, not a live API action tool. It would not call the logistics system or return current shipment status. It is plausible only if shipment policies or manuals needed to be searched.\n• B. code_interpreter allows the agent to run Python in a sandboxed environment. It is useful for data analysis, calculations, and working with files. It is not the right integration pattern for calling a governed internal logistics API. Using sandboxed code for business-system access would weaken control over the workflow boundary.\n• D. web_search is for retrieving information from the public web. The requirement is to call an internal logistics API, not search public sources. Web grounding would not reliably access private shipment data. It also would not satisfy the requirement that application code execute the backend call.\nAgent tools overview for Foundry Agent Service\nTool best practices for Microsoft Foundry Agent Service", "topic": "Agents and tools", "source": 41}, {"id": "542247", "stem": "You have an Azure subscription named Sub1.\nSub1 contains a Microsoft Foundry project named Project1.\nProject1 contains an agent named Agent1.\nAgent1 must support tool use, runtime troubleshooting, evaluation, and controlled approval for high-impact actions.\nYou need to recommend the correct Microsoft Foundry capability or configuration for each requirement.\nRequirements\n1. Allow Agent1 to request a custom operation that is executed by the application and returned to the agent.\n2. Review agent execution details, including inputs, outputs, tool usage, retries, latency, and cost.\n3. Run a test dataset against Agent1 to measure quality, safety, task completion, and tool-call behavior.\n4. Pause a high-impact agent workflow until a user or reviewer approves the action.\nAnswer bank\nA. Agent tracing\nB. Azure AI Search index\nC. Function calling tool\nD. Human approval workflow\nE. Model catalog benchmark\nF. Agent evaluation\nG. Code Interpreter tool\nH. Content Understanding analyzer\nWhich mapping should you use?", "options": ["C = Requirement 1 F = Requirement 2 A = Requirement 3 D = Requirement 4", "C = Requirement 1 A = Requirement 2 F = Requirement 3 D = Requirement 4", "G = Requirement 1 A = Requirement 2 F = Requirement 3 D = Requirement 4", "C = Requirement 1 A = Requirement 2 E = Requirement 3 F = Requirement 4"], "answer": 1, "explanation": "A function calling tool satisfies Requirement 1 because Microsoft Foundry agents can request custom functions that are executed by the application and returned to the agent. This allows the agent to perform custom operations, call business logic, or retrieve real-time data from external systems instead of relying only on generated text.\nAgent tracing satisfies Requirement 2 because Microsoft Foundry tracing captures execution details such as inputs, outputs, tool usage, retries, latency, and costs. Agent evaluation satisfies Requirement 3 because evaluations can run test datasets against agents and measure quality, safety, task completion, and tool behavior. A human approval workflow satisfies Requirement 4 because high-impact semiautonomous actions should pause for review before execution.\nWhy the other options are incorrect:\n• A. This mapping correctly uses function calling for Requirement 1 and human approval workflow for Requirement 4, but it reverses tracing and evaluation. Agent evaluation is used to run test datasets and measure agent behavior. Agent tracing is used to inspect what happened during execution, including tool calls, retries, latency, and costs.\n• C. This mapping incorrectly uses Code Interpreter for Requirement 1. Code Interpreter allows an agent to run Python code in a sandboxed environment, which is useful for data analysis and file-based computation. The requirement asks for a custom operation executed by the application and returned to the agent, which aligns better with function calling.\n• D. This mapping correctly uses function calling and tracing for the first two requirements, but it incorrectly uses a model catalog benchmark for Requirement 3. Benchmarks help compare models, but the requirement is to evaluate a specific agent against a test dataset. It also incorrectly maps agent evaluation to Requirement 4; evaluation measures quality and behavior, while approval workflow controls execution of high-impact actions.\nWhat is Microsoft Foundry Agent Service?\nUse function calling with Microsoft Foundry agents", "topic": "Agents and tools", "source": 41}, {"id": "542355", "stem": "from azure.ai.evaluation import (\nGroundednessEvaluator,\nRelevanceEvaluator,\nCoherenceEvaluator,\nevaluate\n)\nmodel_config = {\n“azure_endpoint”: os.environ[“AZURE_OPENAI_ENDPOINT”],\n“azure_deployment”: os.environ[“AZURE_OPENAI_EVAL_DEPLOYMENT”],\n“api_version”: “2024-10-21”\n}\nevaluators = {\n“groundedness”: GroundednessEvaluator(model_config),\n“relevance”: RelevanceEvaluator(model_config),\n“coherence”: CoherenceEvaluator(model_config)\n}\nresult = evaluate(\ndata=”eval_dataset.jsonl”,\nevaluators=evaluators,\nevaluator_config={\n“default”: {\n“query”: “${data.query}”,\n“response”: “${data.response}”,\n“context”: “${data.context}”\n}\n},\n(MISSING CONFIG)\n)\nprint(result)\nWhich missing configuration best supports reviewable chain-of-thought-style evaluation explanations?", "options": ["logging_enable=False", "response_timeout=1", "random_seed=None", "output_path=\"eval_results.json\""], "answer": 3, "explanation": "Writing evaluation output to a results file is the strongest option because the pipeline needs reviewable evaluation artifacts. For chain-of-thought-style evaluation review, the team needs persisted results that can include evaluator scores, explanations, and per-row details for later inspection.\nThe important AI-103 concept is not exposing private application reasoning to users, but operationalizing evaluation evidence for controlled review. A CI pipeline should preserve evaluation outputs so engineers can compare model or prompt changes and inspect why the evaluator assigned a score.\nWhy the other options are incorrect:\n• A. Disabling logging does not help preserve evaluator reasoning or review evidence. It can reduce diagnostic information that would otherwise help troubleshoot evaluation failures. The requirement is to make evaluator outputs reviewable, not to suppress operational signals. This would work against the goal of operationalizing evaluation.\n• B. Setting a one-second response timeout is not an evaluation artifact strategy. It may cause unnecessary failures when evaluators call model endpoints. Timeouts are useful reliability controls, but an unrealistically low timeout does not preserve evaluator reasoning. This option addresses execution behavior, not reviewability.\n• C. A random seed can improve repeatability in some workflows, but setting it to None does not help review explanations. It may make results less reproducible depending on the evaluation path. Reproducibility is useful, but it is not the missing configuration that stores evaluation outputs. The requirement specifically asks for reviewable evaluation evidence.\nAzure AI Evaluation SDK package\nHow to run an evaluation in Azure DevOps", "topic": "Evaluation", "source": 43}, {"id": "542163", "stem": "A developer is defining a function tool for an agent that checks order status.\nThe tool must require an order_id argument and should not accept unexpected extra fields.\nSnippet\nfrom azure.ai.projects.models import PromptAgentDefinition, Tool, FunctionTool\nfunc_tool = FunctionTool(\nname=”lookup_order”,\nparameters={\n“type”: “object”,\n“properties”: {\n“order_id”: {\n“type”: “string”,\n“description”: “Customer order identifier”\n}\n},\n(MISSING CONFIG)\n},\ndescription=”Get order status for a specific order.”,\nstrict=True,\n)\ntools: list[Tool] = [func_tool]\ndefinition = PromptAgentDefinition(\nmodel=”gpt-4.1-mini”,\ninstructions=”You are a support agent that checks order status when needed.”,\ntools=tools,\n)\nWhich missing configuration best completes the tool schema?", "options": ["\"required\": [], \"additionalProperties\": True", "\"required\": [\"order_id\"], \"additionalProperties\": False", "\"items\": [\"order_id\"], \"type\": \"array\", \"minItems\": 1", "\"required\": [\"order_id\"], \"type\": \"string\", \"nullable\": False"], "answer": 1, "explanation": "This is the best completion because Microsoft’s function-calling documentation shows function tools defined with a name, parameters, and description, and the example schema marks the needed property as required while setting additionalProperties to False. That documented pattern matches a schema where order_id is mandatory and unexpected extra arguments are rejected.\nThe same Microsoft example also uses strict=True, which reinforces the intent that the tool schema should be explicit and constrained. In Foundry, the agent can request function calls based on the defined schema, and your application then executes the function and returns the output. A precise schema improves reliability because the model sees exactly which fields are expected.\nWhy the other options are incorrect:\n• A. “required”: [], “additionalProperties”: True. This makes order_id optional even though the scenario says it must be required. It also allows unexpected extra arguments, which conflicts with the stated goal of a tightly defined tool schema. That is the opposite of the pattern shown in Microsoft’s example, where required fields are explicitly listed and extra properties are disallowed.\n• C. “items”: [“order_id”], “type”: “array”, “minItems”: 1. Microsoft’s example defines function parameters as an object with named properties, not as an array of items. This option changes the top-level schema shape away from the documented pattern for a function call that expects a named argument such as order_id. It therefore does not model the intended function input cleanly.\n• D. “required”: [“order_id”], “type”: “string”, “nullable”: False. This conflicts with the documented object-based schema pattern because the parameters container is already defined as an object with properties. Replacing that with a top-level string type would not align with the example Microsoft provides for function definitions. The result would no longer express a structured function schema with named inputs.\nTool best practices for Microsoft Foundry Agent Service\nQuickstart: Create a prompt agent", "topic": "Agents and tools", "source": 40}, {"id": "542372", "stem": "A healthcare organization deploys an appointment-triage agent that retrieves policy content and can create escalation tickets. The organization must support post-incident review of agent actions, grounding evidence, and human approvals.\nProblem:\nThe solution must audit agent runs, preserve source lineage, and require approval before high-impact actions.\nProposed solution:\nInstrument the agent with trace logging, attach provenance metadata for retrieved sources, and require an approval workflow before escalation-ticket creation.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it includes all three required audit controls. Trace logging records the agent execution path, provenance metadata preserves the source lineage, and the approval workflow controls high-impact actions before they occur.\nThis is a strong responsible AI design for agentic systems because it supports both prevention and review. The approval workflow reduces uncontrolled automation risk, while trace and provenance records give auditors evidence after the fact.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution directly addresses each stated requirement. The system records agent runs through trace logging, preserves source lineage through provenance metadata, and gates high-impact actions through approval. A stronger implementation might add retention policies, access control, and monitoring alerts, but those are not required by this specific goal. The proposed solution satisfies the stated audit requirement.\nBuild a workflow in Microsoft Foundry\nTransparency Note for Azure Agent Service", "topic": "Agents and tools", "source": 43}, {"id": "542253", "stem": "A company is designing two Content Understanding workflows. One workflow analyzes individual product images and returns schema-aligned fields. The second workflow validates a package of related loan documents against underwriting reference documents.\nProblem:\nThe company must configure the correct Content Understanding task modes for both workflows.\nProposed solution:\nUse a single-file Standard task for the product image workflow. Use pro mode for the loan-document workflow because it needs multi-document reasoning and reference data.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "Yes, the proposed solution meets the goal. A single-file Standard task is appropriate for analyzing individual product images and returning structured, schema-aligned fields. It avoids unnecessary pro-mode complexity when there is no cross-file reasoning requirement.\nPro mode is appropriate for the loan-document workflow because it requires reasoning across related documents and reference data. This is the core distinction tested by this dot point: choose the simpler single-file task for independent multimodal processing, and choose pro mode when document workflows require multi-step reasoning or cross-document validation.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution maps each workflow to the appropriate Content Understanding mode. Product image analysis is a single-file multimodal extraction scenario, so Standard mode fits. Loan-document validation requires reasoning across inputs and reference data, which is why pro mode fits. Rejecting the proposed solution would incorrectly treat both workloads as requiring the same pipeline mode.\nCreate Content Understanding Standard and Pro tasks\nBest practices for Azure Content Understanding", "topic": "Agents and tools", "source": 41}, {"id": "542357", "stem": "An organization wants to operationalize a model reflection process for a customer-service agent. The process must evaluate generated responses, capture evaluator explanations for internal review, and block deployment when quality thresholds fail.\nProblem:\nThe release pipeline must support self-critique-style assessment and prevent low-quality prompt versions from reaching production.\nProposed solution:\nRun Foundry evaluations in the pipeline, persist evaluation results with explanations, and require threshold checks before deployment.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it turns model reflection into an operational release control. Foundry evaluations assess model outputs, persisted explanations support internal review, and threshold checks prevent weak prompt or model changes from reaching production.\nThis is stronger than simply asking the model to critique itself at runtime. A pipeline-based evaluation loop creates repeatable evidence and a promotion gate, which is what AI-103 expects for operationalizing generative AI systems.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed design directly satisfies all stated requirements. It evaluates responses, captures reviewable evidence, and blocks deployment when quality fails. The solution could be expanded with production monitoring, tracing, and safety alerts, but those are not required by this specific goal. The stated goal is about release-time reflection and quality gating, which the proposed solution covers.\nRun evaluations from the Microsoft Foundry portal\nObservability in Generative AI", "topic": "Evaluation", "source": 43}, {"id": "542393", "stem": "A finance department wants a semiautonomous agent workflow for vendor payments. The agent may draft payment actions, but payments above 5,000 USD or payments to new vendors must be approved by a human before execution.\nProblem:\nThe workflow must include approval controls, safeguards, and human oversight before high-impact actions.\nProposed solution:\nConfigure Content Safety filtering and allow the agent to execute payment API calls directly whenever its confidence score is above 0.80. Store only the final assistant response for audit review.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "The proposed solution does not meet the goal because content filtering is not the same as approval control. Content safety can help reduce harmful or policy-violating outputs, but it does not create a mandatory human approval step before a payment API executes.\nThe solution also fails the audit and oversight requirement because it stores only the final assistant response. A semiautonomous workflow should capture enough tool input, decision, approval, and execution context to review what happened before a side-effecting action occurred.\nWhy the other options are incorrect:\n• A. Yes is incorrect because the proposed design allows the agent to execute high-impact payment actions without human approval. A confidence score does not satisfy a business approval requirement, especially for new vendors or high-value payments. Content Safety is a safeguard, but it does not replace workflow-level approval gates and human oversight.\nBuild a workflow in Microsoft Foundry\nTool best practices for Microsoft Foundry Agent Service", "topic": "Agents and tools", "source": 43}, {"id": "542425", "stem": "A healthcare organization is deploying an agent that can summarize patient intake notes and create follow-up tasks. The agent must not call billing APIs, must escalate uncertain cases, and must require clinician review before creating care-plan tasks.\nProblem:\nThe agent needs governed behavior with restricted tools, operating constraints, oversight, and human escalation.\nProposed solution:\nConfigure an allowlist of clinical tools, deny billing tool access, add instructions for escalation thresholds, and require clinician approval before task creation.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it combines tool-access control, behavioral constraints, oversight, and human-in-the-loop review. The allowlist and denial of billing access constrain what the agent can do, while escalation instructions and clinician approval reduce risk before side-effecting actions.\nThis is stronger than relying on prompt wording alone. Governance for agent behavior should define what tools are available, when the agent must escalate, and which actions require human approval before execution.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed design addresses each required governance element. It restricts tools, defines escalation behavior, and adds human approval for care-plan task creation. The design could still require implementation details, but the proposed controls match the stated goal.\nTool best practices for Microsoft Foundry Agent Service\nTransparency Note for Azure Agent Service", "topic": "Agents and tools", "source": 44}, {"id": "542354", "stem": "A company is building a Foundry agent for procurement users. The agent must answer supplier-policy questions, extract line items from uploaded invoices, check purchase-order status through an API, and run custom approval logic.\nProblem:\nThe design must integrate the correct tools for retrieval, content extraction, API access, and custom business logic.\nProposed solution:\nUse Azure AI Search for supplier-policy grounding, Content Understanding for invoice extraction, an OpenAPI tool for purchase-order status, and an Azure Functions tool for approval logic.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because each requirement is mapped to the right tool category. Azure AI Search provides grounded retrieval from indexed enterprise knowledge, Content Understanding extracts structured fields from invoices, the OpenAPI tool invokes the purchase-order API, and Azure Functions supports custom business logic.\nThis is a strong agentic design because it avoids forcing one tool to handle unrelated responsibilities. In Foundry agent scenarios, search, extraction, action execution, and custom functions should be separated so each integration can be secured, monitored, and maintained independently.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution satisfies all stated requirements. The knowledge retrieval requirement is covered by Azure AI Search. The invoice extraction requirement is covered by Content Understanding. The API and custom approval requirements are covered by OpenAPI and Azure Functions tool integration.\nWhat is Azure Content Understanding in Foundry Tools?\nIntegrate Azure Functions with Foundry Agents", "topic": "Agents and tools", "source": 43}, {"id": "541987", "stem": "A Foundry agent calls an application-owned inventory function. The application executes the function successfully, but the agent must correlate the result with the specific function call that requested it before generating its final response.\nSnippet\nimport json\nfrom azure.ai.projects.models import FunctionCallOutput\ninput_list = []\nfor item in response.output:\nif item.type == “function_call”:\nif item.name == “check_inventory”:\narguments = json.loads(item.arguments)\nresult = check_inventory(\nsku=arguments[“sku”],\nwarehouse=arguments[“warehouse”]\n)\ninput_list.append(\nFunctionCallOutput(\ntype=”function_call_output”,\ncall_id=(MISSING CONFIG),\noutput=json.dumps(result)\n)\n)\nfinal_response = openai.responses.create(\nconversation=conversation.id,\ninput=input_list\n)\nWhich value should replace (MISSING CONFIG)?", "options": ["response.id", "item.id", "item.name", "item.call_id"], "answer": 3, "explanation": "Function output must be correlated to the tool call that requested it, so the application returns the result using the function-call item’s call_id. Microsoft’s current Foundry function-calling example constructs a FunctionCallOutput using call_id=item.call_id, allowing the model runtime to associate the returned output with the outstanding function invocation.\nThe lifecycle is important: the model requests a function call, application code performs the external operation, the application submits a function-call output containing the matching call ID, and the agent then continues generating its response. Without that correlation identifier, the runtime cannot reliably know which outstanding tool request the returned payload satisfies.\nWhy the other options are incorrect:\nA. response.id. The response ID identifies the broader model response that contained one or more output items. It does not identify the individual function call requiring the returned tool result. A single response can contain multiple items, making response-level identity insufficient for precise function-call correlation. Using it would confuse the response container with the particular tool invocation.\nB. item.id. A function-call output item can have identifiers used to represent the item itself, making this choice appear plausible. Microsoft nevertheless documents a dedicated call_id for correlating the result with the original function request. The output schema specifically expects the call identifier rather than a generic item identifier. Supplying item.id would therefore use the wrong identity relationship.\nC. item.name. The function name tells the application which function should execute, such as check_inventory. Multiple calls to the same function can occur with different arguments during a single agent interaction. The name therefore cannot uniquely associate an output with one particular invocation. call_id exists specifically to preserve that one-to-one relationship.\nTypes of tools in Foundry Agent Service\nQuickstart: Get started with Microsoft Foundry SDK", "topic": "Agents and tools", "source": 37}, {"id": "542344", "stem": "A team is moving a healthcare FAQ assistant from prototype to pilot. The assistant uses retrieved clinical policy summaries as grounding context, and the team must evaluate response quality and safety before exposing it to staff.\nProblem:\nThe release criteria require detecting unsupported claims, measuring whether answers address prompts, and identifying unsafe generated content.\nProposed solution:\nRun a Foundry evaluation against a curated test dataset by using groundedness, relevance, quality, and risk and safety evaluators. Review failed rows before approving the pilot.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the goal because it uses structured Foundry evaluation against a curated dataset and includes evaluators aligned to the stated risks. Groundedness addresses unsupported claims, relevance checks whether answers address prompts, quality evaluators assess response quality, and risk and safety evaluators detect unsafe content.\nReviewing failed rows before release is also appropriate because evaluation scores should guide decision-making and remediation. Automated evaluation helps identify issues consistently, while review of failures helps the team understand whether prompts, retrieval, model choice, or safety controls need improvement.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed solution directly maps to each release criterion. It includes groundedness for fabrication risk, relevance for query fit, and risk and safety evaluators for unsafe content. The curated dataset supports repeatable testing before the pilot. The review step also strengthens the process rather than weakening it.\nRisk and Safety Evaluators for Generative AI\nGroundedness detection in Azure AI Content Safety", "topic": "Evaluation", "source": 43}, {"id": "541992", "stem": "An application directly uses the Azure OpenAI Responses API through a Foundry project. It does not use Foundry Agent Service for this operation.\nEach customer message must produce an object matching the following schema. Downstream processing rejects renamed properties, missing fields, or unexpected object structures.\nSnippet\nfrom pydantic import BaseModel\nfrom typing import List\nclass CaseAnalysis(BaseModel):\ncase_id: str\nentities: List[str]\ntopics: List[str]\nsentiment: str\nsummary: str\nopenai = project.get_openai_client()\nresponse = openai.responses.parse(\nmodel=”gpt-5-mini”,\ninput=”””\nCase INC-2941:\nThe customer reports intermittent authentication failures\nafter yesterday’s identity policy update.\n“””,\n(MISSING CONFIG)\n)\nanalysis = response.output_parsed\nWhich configuration should replace (MISSING CONFIG)?", "options": ["response_format={\"type\": \"json_object\"}", "parallel_tool_calls=True", "text_format=CaseAnalysis", "metadata={\"schema\": \"CaseAnalysis\"}"], "answer": 2, "explanation": "For the Responses API, Microsoft’s current structured-outputs guidance shows responses.parse accepting a Pydantic model through the text_format parameter. The SDK converts that model into the required JSON Schema representation and exposes the parsed result through output_parsed.\nStructured outputs are specifically stronger than older JSON mode when the downstream application requires adherence to a defined schema. JSON mode can ensure syntactically valid JSON but does not provide the same guarantee that property names and object structure conform to the supplied schema. The scenario therefore calls for structured outputs rather than merely requesting JSON-shaped text.\nWhy the other options are incorrect:\nA. response_format={“type”: “json_object”}. JSON mode is useful when the primary requirement is obtaining syntactically valid JSON. Microsoft distinguishes that from structured outputs because JSON mode does not guarantee conformance to a detailed supplied schema. The application explicitly rejects property changes and missing fields, so schema adherence matters. The Responses API structured-output pattern uses text_format with responses.parse for this scenario.\nB. parallel_tool_calls=True. Parallel tool calls control whether multiple tools can be invoked concurrently and do not define the structure of a model’s text output. No function-calling requirement exists in this scenario. Microsoft also notes restrictions around combining structured outputs with parallel function calls in function-calling scenarios. Enabling this setting would therefore solve a different problem and would not enforce the CaseAnalysis schema.\nD. metadata={“schema”: “CaseAnalysis”}. Metadata can be useful for associating application-defined information with requests or responses where supported. Supplying a schema name as metadata does not cause the model to enforce a Pydantic or JSON Schema definition. The inference layer must receive the schema through the structured-output configuration itself. This option labels the request rather than constraining its output.\nResponses API in Azure OpenAI\nStudy guide for Exam AI-103", "topic": "Agents and tools", "source": 37}, {"id": "542014", "stem": "A company is deploying an HR agent that answers handbook questions and can also submit leave-management requests through an MCP-connected back-end.\nProblem:\nThe company wants the agent to keep handbook Q&A efficient, but it does not want the agent to execute sensitive back-end actions without oversight. It also wants tighter governance than broad shared access for sensitive connections.\nProposed solution:\nConfigure the MCP server with all exposed tools, set require_approval to never, use shared cross-project connection credentials, and rely on instructions telling the model to “be careful with leave actions.”\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 1, "explanation": "No. The proposed design removes the explicit oversight control for sensitive actions and keeps a broad shared-access posture for a sensitive connection. Microsoft recommends requiring approval for high-risk operations, using allowed_tools as an allow list, and using project-scoped connections with Entra passthrough for sensitive workloads instead of default shared cross-project access.\nIt is reasonable to keep low-risk handbook Q&A efficient, but that should be done with targeted governance, not by disabling approvals globally and exposing the full tool surface. Responsible AI governance in Foundry emphasizes controls and checkpoints across the lifecycle, including operational controls that reduce unsafe actions and improve accountability.\nWhy the other options are incorrect:\nA. Yes. This answer would be correct only if instructions alone were sufficient to govern sensitive actions, but Microsoft’s tooling guidance provides explicit technical controls for this purpose. The proposal disables approvals, keeps broad shared credentials, and does not restrict exposed tools, so it fails the goal of stronger oversight and constrained access. In practice, “be careful” instructions are weaker than approval gates, allow lists, and tighter connection scoping.\nConnect agents to Model Context Protocol servers\nMicrosoft Foundry Rollout Across My Organization", "topic": "Agents and tools", "source": 37}, {"id": "542292", "stem": "An AI engineer is building a nightly evaluation job for a generative AI application. The job already measures groundedness and relevance, but it must also evaluate whether responses contain violent harmful content.\nSnippet\nimport os\nfrom azure.ai.evaluation import (\nevaluate,\nGroundednessEvaluator,\nRelevanceEvaluator,\nViolenceEvaluator,\n)\nmodel_config = {\n“azure_endpoint”: os.environ[“AZURE_OPENAI_ENDPOINT”],\n“azure_deployment”: os.environ[“EVAL_MODEL_DEPLOYMENT”],\n“api_key”: os.environ[“AZURE_OPENAI_API_KEY”],\n}\nevaluators = {\n“groundedness”: GroundednessEvaluator(model_config=model_config),\n“relevance”: RelevanceEvaluator(model_config=model_config),\n“violence”: (MISSING CONFIG),\n}\nresult = evaluate(\ndata=”nightly_eval_dataset.jsonl”,\nevaluators=evaluators,\noutput_path=”nightly_eval_results.json”,\n)\nprint(result)\nWhich configuration should replace (MISSING CONFIG)?", "options": ["Azure Monitor workbook", "Application Insights trace exporter", "ViolenceEvaluator(model_config=model_config)", "Responsible AI dashboard scorecard"], "answer": 2, "explanation": "ViolenceEvaluator(model_config=model_config) completes the evaluator dictionary with a safety evaluator that specifically checks generated responses for violent harmful content. The snippet is using the Azure AI evaluation package to run multiple evaluators against a dataset, so the missing configuration must be another evaluator object, not an observability or reporting component.\nThe important AI-103 skill is recognizing implementation intent from the code. The job is not trying to visualize operational telemetry or produce a model governance report; it is trying to add a safety evaluation to the same evaluation run that already includes groundedness and relevance.\nWhy the other options are incorrect:\n• A. Azure Monitor workbook can visualize operational telemetry and dashboard metrics. It is useful after telemetry is collected from an application or service. However, it is not an evaluator object and would not fit inside the evaluators dictionary. It also does not directly score violent content in generated responses.\n• B. Application Insights trace exporter is relevant for observability and distributed tracing. It can help capture requests, dependencies, latency, and execution flow. However, the code is building an evaluation run, not exporting traces. Adding a trace exporter would not provide a violence safety score for the dataset.\n• D. Responsible AI dashboard scorecard is associated with responsible AI reporting and model assessment workflows. It can be useful for governance and stakeholder communication. However, it is not the correct object for a Foundry generative AI evaluation job. It would not replace the missing evaluator configuration in this Python snippet.\nRisk and Safety Evaluators for Generative AI\nBuilt-in Evaluators Reference", "topic": "Evaluation", "source": 42}, {"id": "542283", "stem": "A generative text analysis app must return a fixed JSON structure that includes entities, topics, summary, and risk category. The downstream workflow rejects responses when required properties are missing.\nSnippet\nimport os\nfrom openai import AzureOpenAI\nclient = AzureOpenAI(\nazure_endpoint=os.environ[“AZURE_OPENAI_ENDPOINT”],\napi_key=os.environ[“AZURE_OPENAI_API_KEY”],\napi_version=”2024-10-21″\n)\nschema = {\n“type”: “object”,\n“properties”: {\n“entities”: {\n“type”: “array”,\n“items”: {“type”: “string”}\n},\n“topics”: {\n“type”: “array”,\n“items”: {“type”: “string”}\n},\n“summary”: {\n“type”: “string”\n},\n“riskCategory”: {\n“type”: “string”,\n“enum”: [“low”, “medium”, “high”]\n}\n},\n“required”: [“entities”, “topics”, “summary”, “riskCategory”],\n“additionalProperties”: False\n}\nresponse = client.chat.completions.create(\nmodel=os.environ[“MODEL_DEPLOYMENT”],\nmessages=[\n{\n“role”: “system”,\n“content”: “Extract entities, topics, summary, and risk category.”\n},\n{\n“role”: “user”,\n“content”: “Customer says Contoso delayed shipment 4471 and requests escalation.”\n}\n],\n(MISSING CONFIG)\n)\nprint(response.choices[0].message.content)\nWhich missing configuration should you use?", "options": ["JSON Schema response format", "JSON mode response format", "Function tool registration", "Key phrase extraction tool"], "answer": 0, "explanation": "JSON Schema response format is the correct configuration because the downstream workflow requires a fixed structure with required properties. Structured outputs with a schema are designed to make the model adhere to the supplied JSON Schema, not merely return valid JSON text.\nThis matters because a prompt such as “return JSON” can still produce missing fields, extra fields, or inconsistent structures. JSON mode improves syntactic validity, but structured outputs are the stronger choice when the application must enforce a schema contract.\nWhy the other options are incorrect:\n• B. JSON mode response format is plausible because it helps ensure the model returns valid JSON. However, JSON mode does not guarantee that the output follows a specific schema with required fields. The scenario explicitly says the downstream workflow rejects missing properties. That makes schema enforcement more important than JSON validity alone.\n• C. Function tool registration is used when the model should call a tool or external function with structured arguments. It is not the right missing configuration for forcing the final model response to match a JSON schema. A function could be part of a broader pipeline, but the snippet is configuring the response format. This option confuses tool invocation with output-shape enforcement.\n• D. Key phrase extraction tool can help identify topics or important phrases from text. It does not enforce the structure of the final response. It also does not produce the complete object containing entities, summary, and risk category in a guaranteed schema. It may support one field, but it does not solve the JSON contract requirement.\nJSON mode with Azure OpenAI\nAzure OpenAI REST API reference", "topic": "Agents and tools", "source": 42}, {"id": "542338", "stem": "You are instrumenting a claims-processing agent. The agent can retrieve policy documents and request approval before issuing a payment adjustment.\nSnippet\nimport os\nfrom opentelemetry import trace\nfrom azure.monitor.opentelemetry import configure_azure_monitor\nconfigure_azure_monitor(\nconnection_string=os.environ[“APPLICATIONINSIGHTS_CONNECTION_STRING”]\n)\ntracer = trace.get_tracer(“claims-agent”)\ndef run_claim_review(agent, claim_request, approval):\nwith tracer.start_as_current_span(“agent.claim_review”) as span:\nspan.set_attribute(“ai.agent.name”, “claims-review-agent”)\nspan.set_attribute(“ai.workflow.id”, claim_request.workflow_id)\nspan.set_attribute(“ai.provenance.source_doc_id”, claim_request.policy_doc_id)\nspan.set_attribute(“ai.provenance.index_version”, claim_request.index_version)\nspan.set_attribute(“ai.tool.name”, “payment_adjustment”)\nspan.set_attribute(“ai.approval.required”, True)\n(MISSING CONFIG)\nresult = agent.run(\ninput=claim_request.summary,\ntool_context={“approval_id”: approval.id}\n)\nspan.set_attribute(“ai.run.status”, “completed”)\nreturn result\nWhich missing configuration best completes the audit trail?", "options": ["Store raw prompt archive", "Add approval decision event", "Replace provenance metadata with embeddings", "Disable tracing after approvals complete"], "answer": 1, "explanation": "Adding an approval decision event is the best completion because the trace already records the agent workflow, provenance fields, and the sensitive tool name. The missing audit element is the actual approval outcome, such as who approved or rejected the action, when the decision occurred, and which approval request it related to.\nFor responsible AI auditing, approval decisions should be correlated with the same trace that records the agent run and tool execution. This lets reviewers connect the final action to the retrieved evidence, the approval workflow, and the runtime behavior that led to the decision.\nWhy the other options are incorrect:\n• A. Storing a raw prompt archive may create privacy, security, and retention concerns. It also does not directly link the approval outcome to the trace span. A raw prompt can be useful in some debugging scenarios, but it is not the missing workflow approval record. The question needs an auditable event in the existing trace context.\n• C. Replacing provenance metadata with embeddings would weaken auditability. Embeddings help similarity search, but they are not human-readable evidence of the source document or index version. Auditors need clear provenance identifiers, not just vector representations. This option removes useful audit evidence instead of completing it.\n• D. Disabling tracing after approvals complete would reduce visibility into the final action. The system still needs to capture the result of the approved tool call and completion status. Turning off tracing would create a gap between approval and execution. That is the opposite of a responsible audit design.\nTrace and observe AI agents in Microsoft Foundry\nUsing function tools with human in the loop approvals", "topic": "Agents and tools", "source": 42}, {"id": "541986", "stem": "A claims application uses the current Microsoft Foundry Python SDK. Each open claim must use one persistent conversation so follow-up questions retain the previous claim details.\nThe team does not want to store the claim as long-term cross-session user memory.\nSnippet\nimport os\nfrom azure.identity import DefaultAzureCredential\nfrom azure.ai.projects import AIProjectClient\nPROJECT_ENDPOINT = os.environ[“PROJECT_ENDPOINT”]\nAGENT_NAME = “claims-agent”\nproject = AIProjectClient(\nendpoint=PROJECT_ENDPOINT,\ncredential=DefaultAzureCredential(),\n)\nopenai = project.get_openai_client(agent_name=AGENT_NAME)\nconversation = openai.conversations.create()\nfirst = openai.responses.create(\nconversation=conversation.id,\ninput=”Claim CLM-4821 is for a damaged laptop.”\n)\nsecond = openai.responses.create(\n(MISSING CONFIG)\n)\nprint(second.output_text)\nThe second user message is:\nThe screen is also cracked. Does that change the assessment?”\nWhich configuration should replace (MISSING CONFIG)?", "options": ["conversation=conversation.id, input=\"The screen is also cracked...\"", "previous_response_id=first.id, input=\"The screen is also cracked...\"", "conversation=first.id, input=\"The screen is also cracked...\"", "conversation=openai.conversations.create().id, input=\"The screen is also cracked...\""], "answer": 0, "explanation": "The same conversation ID should be supplied to the second response request. Microsoft’s current Foundry SDK quickstart demonstrates creating a conversation once and passing that conversation ID to each response in a multi-turn interaction, which allows the conversation to maintain the prior history.\nThis is different from durable user memory. A conversation represents interaction state for the ongoing exchange, which is exactly what an open claim needs in this scenario. Creating another conversation would establish a separate context, while storing the claim as durable memory would extend persistence beyond the stated requirement.\nWhy the other options are incorrect:\nB. previous_response_id=first.id, input=”The screen is also cracked…”. The Responses API can support continuation patterns involving prior responses in appropriate scenarios, making this a plausible distractor. However, the application requirement explicitly calls for all claim turns to exist within the persistent conversation object that was already created. Using the conversation identifier follows the Foundry agent multi-turn pattern documented for this purpose. It also keeps conversation lifecycle management explicit instead of replacing the specified conversation object with another continuation mechanism.\nC. conversation=first.id, input=”The screen is also cracked…”. first.id identifies the response object rather than the conversation created by openai.conversations.create(). The conversation parameter should identify the conversation whose state the new response belongs to. Confusing response identity with conversation identity would not attach the follow-up to the intended conversation. The correct value is therefore conversation.id.\nD. conversation=openai.conversations.create().id, input=”The screen is also cracked…”. This creates a new conversation immediately before processing the follow-up. As a result, the new conversation does not contain the first statement about claim CLM-4821 unless the application manually resupplies that context. That defeats the requirement to preserve the open claim’s multi-turn history in one conversation. A new conversation is appropriate for a separate interaction, not a continuation of this one.\nMicrosoft Foundry SDKs and endpoints\nFoundry Agent Service runtime components", "topic": "Agents and tools", "source": 37}, {"id": "542353", "stem": "An organization is deploying a customer support agent in Foundry. The agent must use private connectivity, retrieve grounding data from Azure AI Search, avoid stored service keys, and allow separate projects for future business units.\nProblem:\nThe current prototype uses a public endpoint, a Search admin key, and a single shared environment for all teams.\nProposed solution:\nCreate a Microsoft Foundry resource, create a dedicated Foundry project for the support agent, configure Foundry Agent Service with private networking, connect Azure AI Search by using the project managed identity, and assign the required Search RBAC role.\nDoes the proposed solution meet the goal?", "options": ["Yes", "No"], "answer": 0, "explanation": "The proposed solution meets the stated goal because it replaces the public, key-based prototype with a Foundry-based infrastructure design using project separation, private networking, and managed identity. A Foundry resource and project provide a better organizational boundary for the agent workload and future business-unit separation.\nThe solution also addresses secure retrieval from Azure AI Search. Using the project managed identity and assigning the required Search RBAC role avoids stored service keys and supports private, identity-based access to the grounding index.\nWhy the other options are incorrect:\n• B. No is incorrect because the proposed design directly addresses each problem in the prototype. It removes reliance on a public endpoint by introducing private networking. It replaces the Search admin key with project managed identity and RBAC. It also creates a dedicated project, which supports separation for the current agent and future workloads.\nWhat is Microsoft Foundry Agent Service?\nConfigure network isolation for Microsoft Foundry", "topic": "Agents and tools", "source": 43}]}]};
